// Per-stage dialogues (speaker, English, Hebrew) and per-sentence teaching notes for the business English track.
// CAREER_EXPLAIN[stage][sentence] is the note for that sentence, in the same order as CAREER_STAGES.
const CAREER_DIALOGUES = [
  [["HR", "Thanks for coming in. Could you start by telling us a little about yourself?", "תודה שבאת. אפשר להתחיל בכך שתספר לנו קצת על עצמך?"], ["Candidate", "Sure. I have been working as a sales assistant for three years.", "בוודאי. אני עובד כעוזר מכירות כבר שלוש שנים."], ["HR", "That's great. What did your role involve?", "מצוין. במה התפקיד שלך כלל?"], ["Candidate", "My main responsibility was handling customer accounts. I'm looking for a position where I can use my analytical skills.", "האחריות העיקרית שלי הייתה לטפל בחשבונות לקוחות. אני מחפש תפקיד שבו אוכל להשתמש בכישורים האנליטיים שלי."]],
  [["HR", "Tell me about your strengths and weaknesses.", "ספר לי על החוזקות והחולשות שלך."], ["Candidate", "One of my strengths is that I stay calm under pressure. I tend to be too detailed, so I have started setting time limits.", "אחת החוזקות שלי היא שאני נשאר רגוע תחת לחץ. אני נוטה להיות מפורט מדי, ולכן התחלתי לקבוע לעצמי מגבלות זמן."], ["HR", "That's a good approach. How do you handle feedback?", "זו גישה טובה. איך אתה מתמודד עם משוב?"], ["Candidate", "I take feedback seriously and try to act on it quickly.", "אני לוקח משוב ברצינות ומנסה לפעול לפיו במהירות."]],
  [["HR", "Can you tell me about a result you are proud of?", "אפשר לספר על תוצאה שאתה גאה בה?"], ["Candidate", "In my last job, I introduced a new filing system that saved two hours a day.", "בעבודה האחרונה שלי הכנסתי מערכת תיוק חדשה שחסכה שעתיים ביום."], ["HR", "How did your team react?", "איך הצוות שלך הגיב?"], ["Candidate", "They were happy with it. I trained the new employees myself.", "הם היו מרוצים. אני הדרכתי את העובדים החדשים בעצמי."]],
  [["HR", "Why are you interested in this role?", "למה אתה מעוניין בתפקיד הזה?"], ["Candidate", "What attracts me most is the chance to work closely with the product team.", "מה שמושך אותי יותר מכול הוא ההזדמנות לעבוד בקרבה עם צוות המוצר."], ["HR", "What are your salary expectations?", "מה ציפיות השכר שלך?"], ["Candidate", "My expectations are in line with the market. I'd be happy to discuss the package once we know more about the role.", "הציפיות שלי תואמות את השוק. אשמח לדון בתנאים לאחר שנדע עוד על התפקיד."]],
  [["HR", "Could you give me an example of a difficult situation you faced at work?", "האם תוכל לתת דוגמה למצב קשה שהתמודדת איתו בעבודה?"], ["Candidate", "A client was unhappy with the results. I started by listening carefully and then found a practical solution.", "לקוח לא היה מרוצה מהתוצאות. התחלתי בהקשבה מדוקדקת, ואחר כך מצאתי פתרון מעשי."], ["HR", "What would you do if a deadline is at risk?", "מה היית עושה אם דדליין נמצא בסכנה?"], ["Candidate", "I'd tell the team early and we'd adjust the plan together.", "הייתי מודיע לצוות מוקדם, ואנחנו היינו מתאימים את התוכנית ביחד."]],
  [["HR", "Do you have any questions for us?", "יש לך שאלות אלינו?"], ["Candidate", "What does a typical day look like in this role?", "איך נראה יום טיפוסי בתפקיד הזה?"], ["HR", "It usually starts with a team meeting. Then you work on your projects.", "בדרך כלל הוא מתחיל בישיבת צוות. אחר כך עובדים על הפרויקטים."], ["Candidate", "Thanks. Is there an opportunity to take on new projects after the first year?", "תודה. האם יש הזדמנות לקחת פרויקטים חדשים אחרי השנה הראשונה?"]],
  [["HR", "Thank you for coming today. Is there anything else you'd like to add?", "תודה שבאת היום. יש עוד משהו שתרצה להוסיף?"], ["Candidate", "Thank you again for your time. I really enjoyed our conversation.", "שוב תודה על הזמן. נהניתי מאוד מהשיחה."], ["HR", "We'll be in touch with you by the end of next week.", "ניצור איתך קשר עד סוף השבוע הבא."], ["Candidate", "Great. I look forward to hearing from you.", "מצוין. אני מצפה לשמוע מכם."]],
  [["Anna", "Hi Michael, I'm attaching the monthly report. Let me know if you have questions.", "היי מיכאל, אני מצרף את הדוח החודשי. תגיד לי אם יש שאלות."], ["Michael", "Thanks for sending it so quickly. Could we schedule a meeting next Thursday?", "תודה שנשלח כל כך מהר. אפשר לקבוע פגישה ליום חמישי הבא?"], ["Anna", "Sure, I'm available. I'll send a calendar invite.", "בטח, אני פנוי. אשלח הזמנה ביומן."], ["Michael", "Perfect. Best regards, Michael.", "מצוין. בברכה, מיכאל."]],
  [["Anna", "Hi Mike, I'm writing to check the status of our order from last week.", "היי מייק, אני כותבת כדי לברר מה מצב ההזמנה שלנו מהשבוע שעבר."], ["Mike", "Sorry for the delay. Could you resend the file in PDF format? I couldn't open it.", "מצטער על העיכוב. אפשר לשלוח שוב את הקובץ ב-PDF? לא הצלחתי לפתוח אותו."], ["Anna", "Sure, I'll resend it today. Could you reply by noon tomorrow?", "בטח, אשלח שוב היום. אפשר לענות עד מחר בצהריים?"], ["Mike", "Of course. Thank you for your patience.", "בוודאי. תודה על הסבלנות."]],
  [["Anna", "As agreed in our call, I'm sending you the updated figures.", "כפי שסוכם בשיחה, אני שולחת לך את הנתונים המעודכנים."], ["Mike", "Thanks. I'm not sure the current wording is accurate. Could you suggest any changes?", "תודה. אני לא בטוח שהניסוח הנוכחי מדויק. אפשר להציע שינויים?"], ["Anna", "Sure. I'd appreciate it if you could review it again by Friday.", "בטח. אודה לך אם תעבור עליו שוב עד יום שישי."], ["Mike", "No problem. I'll review it before the meeting.", "אין בעיה. אעבור עליו לפני הפגישה."]],
  [["Lawyer", "Following your message on Monday, the matter has been referred to our legal department.", "בהמשך להודעתך מיום שני, הנושא הועבר למחלקה המשפטית שלנו."], ["Client", "We need the contract soon. Can you meet the original timeline?", "אנחנו צריכים את החוזה בקרוב. אפשר לעמוד בלוח הזמנים המקורי?"], ["Lawyer", "I'm sorry, we're unable to meet the original timeline. I recommend that we review the clauses first.", "אני מצטערת, איננו יכולים לעמוד בלוח הזמנים המקורי. אני ממליצה שנבחן קודם את הסעיפים."], ["Client", "Fine. I'd be grateful if you could clarify the third clause.", "בסדר. אודה לך אם תבהירי את הסעיף השלישי."]],
  [["Lead", "After we reviewed the proposal, we think it meets our needs, but we need more flexible payment terms.", "אחרי שעברנו על ההצעה, אנחנו חושבים שהיא מתאימה לצרכים שלנו, אבל אנחנו צריכים תנאי תשלום גמישים יותר."], ["Vendor", "Because of the current limits, we can't change the terms this month.", "בגלל המגבלות הנוכחיות, אנחנו לא יכולים לשנות את התנאים החודש."], ["Lead", "If we don't get approval by Tuesday, we may have to cancel the order.", "אם לא נקבל אישור עד יום שלישי, ייתכן שנצטרך לבטל את ההזמנה."], ["Vendor", "I understand. Let's set up another call so we can agree on the next steps.", "אני מבין. בוא נקבע שיחה נוספת כדי שנסכים על הצעדים הבאים."]],
  [["Dana", "I'm following up on the email I sent last Tuesday. I haven't heard back yet.", "אני חוזרת למייל ששלחתי ביום שלישי שעבר. עדיין לא קיבלתי תשובה."], ["Tom", "Sorry for the delay. Please find attached the signed agreement for your records.", "מצטער על העיכוב. מצורף ההסכם החתום לתיעוד שלכם."], ["Dana", "Thanks for pointing out the mistake. Could you confirm which version you mean?", "תודה שציינת את הטעות. אפשר לאשר לאיזו גרסה אתה מתכוון?"], ["Tom", "The latest one. We need a few more days to read the contract carefully.", "הגרסה האחרונה. אנחנו צריכים עוד כמה ימים כדי לקרוא את החוזה בעיון."]],
  [["Client", "Thank you for your detailed feedback. It helped us improve the proposal.", "תודה על המשוב המפורט. הוא עזר לנו לשפר את ההצעה."], ["Vendor", "You're welcome. Our legal team has checked the terms and has no problem with the new version.", "בבקשה. צוות המשפטים שלנו בדק את התנאים ואין לו בעיה עם הגרסה החדשה."], ["Client", "Great. Let me know if you would prefer a different format for the final report.", "מצוין. תגיד לי אם אתה מעדיף פורמט אחר לדוח הסופי."], ["Vendor", "I will. I hope this answers your question.", "בטח. אני מקווה שזה עונה על השאלה שלך."]],
  [["Lead", "Good morning, everyone. Let's get started. I suggest we go through the agenda in order.", "בוקר טוב לכולם. בואו נתחיל. אני מציע שנעבור על סדר היום לפי הסדר."], ["Dana", "Sounds good. We have about ten minutes, so let's keep it short.", "נשמע טוב. יש לנו בערך עשר דקות, אז בואו נקצר."], ["Lead", "Who would like to give an update on the project?", "מי רוצה לתת עדכון על הפרויקט?"], ["Dana", "I can. Could you repeat the last question, please? I missed it.", "אני יכולה. אפשר לחזור על השאלה האחרונה? פספסתי אותה."]],
  [["Lead", "I'd like to present our plan for the next quarter. Let's check whether everyone understands the goal.", "אני רוצה להציג את התוכנית שלנו לרבעון הבא. בוא נבדוק אם כולם מבינים את המטרה."], ["Dana", "Yes. I have a question about the budget for the marketing campaign.", "כן. יש לי שאלה לגבי התקציב של קמפיין השיווק."], ["Lead", "According to the data, sales went up by ten percent last month.", "לפי הנתונים, המכירות עלו בעשרה אחוז בחודש שעבר."], ["Dana", "Great. My team will finish the first draft by the end of the month.", "מצוין. הצוות שלי יסיים את הטיוטה הראשונה עד סוף החודש."]],
  [["Lead", "I'd like to add an item to the agenda about the glitch we found yesterday.", "אני רוצה להוסיף לסדר היום נושא בנוגע לתקלה שמצאנו אתמול."], ["Omer", "Before we continue, let's agree on the definitions of the key terms.", "לפני שנמשיך, בוא נסכים על ההגדרות של המונחים המרכזיים."], ["Lead", "If we leave this task until the end, we'll probably miss the deadline.", "אם נשאיר את המשימה הזאת לסוף, כנראה נפספס את הדדליין."], ["Omer", "Agreed. Let's focus on finding a solution rather than on who caused the problem.", "מסכים. בוא נתמקד במציאת פתרון ולא במי גרם לבעיה."]],
  [["Lead", "Before we discuss the plan, I want to make sure the assumptions behind it are up to date.", "לפני שנדון בתוכנית, אני רוצה לוודא שההנחות שמאחוריה עדכניות."], ["Noa", "There seems to be a gap between what was presented and what is happening on the ground.", "נראה שיש פער בין מה שהוצג לבין מה שקורה בשטח."], ["Lead", "Given the budget pressure, we need an approach that balances cost and quality.", "בהתחשב בלחץ התקציבי, אנחנו צריכים גישה שמאזנת בין עלות לאיכות."], ["Noa", "I suggest we assign one person to track the follow-up on each decision.", "אני מציע שנמנה אדם אחד שיהיה אחראי על מעקב אחרי כל החלטה."]],
  [["Lead", "The alternative looks attractive, but it has legal risks we haven't checked fully.", "החלופה נראית מפתה, אבל יש בה סיכונים משפטיים שלא בדקנו עד הסוף."], ["Yael", "I want to be clear: I'm not against the idea, only against how it's presented.", "אני רוצה להיות ברורה: אני לא נגד הרעיון, רק נגד האופן שבו הוא מוצג."], ["Lead", "Today's meeting is not for a final decision. We need to list the points that need senior approval.", "מטרת הישיבה היום אינה לקבל החלטה סופית. עלינו לרשום את הנקודות שדורשות אישור בכירים."], ["Yael", "Then let's set a date to come back to this topic and make a decision.", "אז בוא נקבע מועד לחזור לנושא הזה ונקבל החלטה."]],
  [["Lead", "Before we start, can we check that everyone has the latest version of the slides?", "לפני שמתחילים, אפשר לבדוק שלכולם יש את הגרסה האחרונה של השקפים?"], ["Sara", "Yes. I'd like to hear from people who haven't spoken yet.", "כן. אני רוצה לשמוע מאנשים שעוד לא דיברו."], ["Lead", "We keep talking about the same thing, so let's make a decision.", "אנחנו ממשיכים לדבר על אותו דבר, אז בוא נחליט."], ["Sara", "That's a good point, but I'd like to see some data first.", "זו נקודה טובה, אבל אני רוצה לראות קודם נתונים."]],
  [["Lead", "Let's make sure each team knows its tasks before we leave the room.", "בוא נוודא שכל צוות יודע את המשימות שלו לפני שיוצאים מהחדר."], ["Ron", "I'll send the minutes by tomorrow. Please tell me if I missed anything.", "אשלח את הסיכום עד מחר. נא לומר לי אם פספסתי משהו."], ["Lead", "Thank you all. Let's meet again on Friday to check our progress.", "תודה לכולם. בוא נתכנס שוב ביום שישי כדי לבדוק את ההתקדמות."], ["Ron", "Sounds good. I'm glad we agreed, even though it took longer than I expected.", "נשמע טוב. אני שמח שהסכמנו, גם אם זה לקח יותר זמן ממה שציפיתי."]],
  [["Agent", "Hello, how can I help you today?", "שלום, איך אוכל לעזור לך היום?"], ["Customer", "I understand there's a problem with my order. It hasn't arrived.", "אני מבין שיש בעיה עם ההזמנה שלי. היא לא הגיעה."], ["Agent", "I'm sorry for the inconvenience. Could I have your order number, please?", "אני מצטער על אי הנוחות. אפשר לקבל את מספר ההזמנה שלך?"], ["Agent", "Let me check that for you right now. Thank you for contacting us.", "תן לי לבדוק את זה עבורך עכשיו. תודה שפנית אלינו."]],
  [["Agent", "I'm sorry for the inconvenience. The issue has been fixed.", "אני מצטער על אי הנוחות. התקלה תוקנה."], ["Customer", "Thank you. Can I get a link to reset my password?", "תודה. אפשר לקבל קישור לאיפוס הסיסמה?"], ["Agent", "Yes, I can send you a link right now. Would you like me to transfer you to billing?", "כן, אוכל לשלוח לך קישור עכשיו. תרצה שאעביר אותך לחיובים?"], ["Customer", "No, that's fine. Thanks for your help.", "לא, זה בסדר. תודה על העזרה."]],
  [["Agent", "I understand the situation is frustrating. Unfortunately, our policy doesn't allow refunds after thirty days.", "אני מבין שהמצב מתסכל. לצערי, המדיניות שלנו לא מאפשרת החזר אחרי שלושים יום."], ["Customer", "That's not fair. I have been a customer for years.", "זה לא הוגן. אני לקוח כבר שנים."], ["Agent", "I know. I can offer you a discount on your next order. Would that help?", "אני יודע. אני יכול להציע לך הנחה על ההזמנה הבאה. זה יעזור?"], ["Customer", "Yes, that's a reasonable offer. Thank you.", "כן, זו הצעה סבירה. תודה."]],
  [["Agent", "I understand our decision isn't what you wanted, and I'm happy to explain the reasoning.", "אני מבין שההחלטה שלנו לא הייתה מה שרצית, ואשמח להסביר את השיקולים."], ["Customer", "Please do. I need to know why the exchange was refused.", "בבקשה. אני צריך לדעת למה ההחלפה נדחתה."], ["Agent", "According to our policy, you can exchange the item within fourteen days. I'd suggest a video call with a technician.", "לפי המדיניות שלנו, אפשר להחליף את הפריט תוך ארבעה עשר יום. הייתי מציע שיחת וידאו עם טכנאי."], ["Customer", "Okay. I'd appreciate it if you could set that up today.", "בסדר. אודה לך אם תוכל לקבוע את זה היום."]],
  [["Customer", "I'm very angry. The product broke after two days!", "אני מאוד כועס. המוצר נשבר אחרי יומיים!"], ["Agent", "I understand your anger, but this policy is the same for every customer. Let me look at your options.", "אני מבין את הכעס, אבל המדיניות הזאת זהה לכל הלקוחות. תן לי לבדוק את האפשרויות שלך."], ["Agent", "I can't approve your request as it is, but I can offer you something that covers most of the loss.", "אני לא יכול לאשר את הבקשה כמו שהיא, אבל אני יכול להציע לך משהו שמכסה את רוב ההפסד."], ["Customer", "Fine. Please send me the details by email.", "בסדר. נא לשלוח לי את הפרטים במייל."]],
  [["Agent", "I've noted your concern in our system, and a supervisor will look at it today.", "רשמתי את הפנייה שלך במערכת, ומנהל יבדוק אותה היום."], ["Customer", "Thank you. Could I get an update tomorrow?", "תודה. אפשר לקבל עדכון מחר?"], ["Agent", "Of course. Please keep your receipt. We need it to handle the return.", "בוודאי. נא לשמור את הקבלה. אנחנו צריכים אותה כדי לטפל בהחזרה."], ["Customer", "Okay. Thank you for your patience.", "בסדר. תודה על הסבלנות."]],
  [["Agent", "Thanks for telling us. We wrote down your feedback and shared it with the product team.", "תודה שסיפרת לנו. רשמנו את המשוב שלך ושיתפנו אותו עם צוות המוצר."], ["Customer", "Good. Will the new version fix the problem?", "טוב. הגרסה החדשה תפתור את הבעיה?"], ["Agent", "It should. We added a credit to your account, and you should see it on your next statement.", "היא אמורה. הוספנו זיכוי לחשבון שלך, ואתה אמור לראות אותו בדף החשבון הבא."], ["Customer", "Thanks. Have a great day!", "תודה. יום נעים!"]],
  [["Rep", "Thanks for meeting with us today. I'd like to tell you about our product.", "תודה שנפגשתם איתנו היום. אני רוצה לספר לכם על המוצר שלנו."], ["Client", "Sure. What does it do exactly?", "בטח. מה הוא עושה בדיוק?"], ["Rep", "Our software helps companies save time on daily reports. Would you like to see a short demo?", "התוכנה שלנו עוזרת לחברות לחסוך זמן בדוחות היומיים. תרצו לראות הדגמה קצרה?"], ["Client", "Yes, please. Let's see what it can do for our team.", "כן, בבקשה. בוא נראה מה היא יכולה לעשות לצוות שלנו."]],
  [["Rep", "Our software helps companies save time. Many of our clients have seen a clear improvement.", "התוכנה שלנו עוזרת לחברות לחסוך זמן. הרבה מהלקוחות שלנו ראו שיפור ברור."], ["Client", "Interesting. What would make this decision easier for you?", "מעניין. מה היה מקל עליכם לקבל את ההחלטה?"], ["Rep", "If you sign this month, we can offer a discount on the first year.", "אם תחתמו החודש, נוכל להציע הנחה על השנה הראשונה."], ["Client", "That helps. Could you tell me who else will be involved in the decision?", "זה עוזר. האם תוכל לומר לי מי נוסף ייכלל בהחלטה?"]],
  [["Client", "Your price is high. We understand your concern about the price.", "המחיר שלכם גבוה. אנחנו מבינים את החשש שלנו מהמחיר."], ["Rep", "We'd like to find a middle ground. Could you share what budget range you had in mind?", "אנחנו רוצים למצוא פשרה. האם תוכלו לשתף איזה טווח תקציב חשבתם עליו?"], ["Client", "Around this amount. We're not in a position to pay more.", "בסביבות הסכום הזה. איננו במצב לשלם יותר."], ["Rep", "I understand. We can waive the training costs, and we'll discuss the rest on Friday.", "אני מבין. נוכל לוותר על עלויות ההדרכה, ונדבר על השאר ביום שישי."]],
  [["Client", "Your offer doesn't include a long warranty. That's a problem for us.", "ההצעה שלכם לא כוללת אחריות ארוכה. זו בעיה בשבילנו."], ["Rep", "We can meet you halfway by extending the warranty. I'd rather be honest about what we can deliver.", "נוכל לבוא לקראתכם בחצי הדרך על ידי הארכת האחריות. אני מעדיף להיות כן לגבי מה שאנחנו יכולים לספק."], ["Client", "We're comparing you with other vendors, so the total cost matters.", "אנחנו משווים אתכם לספקים אחרים, לכן העלות הכוללת חשובה."], ["Rep", "Let's look at the total cost of ownership. Would you be open to a shorter contract?", "בוא נסתכל על העלות הכוללת לאורך זמן. האם תהיו פתוחים לחוזה קצר יותר?"]],
  [["Rep", "Our proposal shows the full value we offer. Let's split the difference on the setup fee.", "ההצעה שלנו מראה את מלוא הערך שאנחנו נותנים. בוא נחלק את ההפרש בדמי ההקמה."], ["Client", "We know you have other options, but the discount you ask for is too big for us.", "אנחנו יודעים שיש לכם אפשרויות אחרות, אבל ההנחה שאתם מבקשים גדולה מדי בשבילנו."], ["Rep", "Let's be realistic. The timeline is tight, so we need to decide what to deliver first.", "בואו נהיה ריאליים. לוח הזמנים צפוף, ולכן צריך להחליט מה מספקים קודם."], ["Client", "Fair enough. Let's stop for a moment and check that we're talking about the same numbers.", "הוגן. בוא נעצור רגע ונבדוק שאנחנו מדברים על אותם מספרים."]],
  [["Client", "We read your counteroffer. The main problem seems to be the delivery schedule.", "קראנו את ההצעה הנגדית שלכם. נראה שהבעיה העיקרית היא לוח האספקה."], ["Rep", "If we agree on the delivery dates, I think we can close the deal this quarter.", "אם נסכים על תאריכי האספקה, אני חושב שנוכל לסגור את העסקה ברבעון הזה."], ["Client", "Our legal team needs a few days to read the new terms before we sign.", "הצוות המשפטי שלנו צריך כמה ימים לקרוא את התנאים החדשים לפני החתימה."], ["Rep", "Of course. If you are happy with these terms, I'll prepare the final agreement this afternoon.", "בוודאי. אם אתם מרוצים מהתנאים, אכין את ההסכם הסופי אחר הצהריים."]],
  [["Rep", "Thank you for being open during this negotiation. It made reaching a fair deal much easier.", "תודה שהיית פתוח לאורך המשא ומתן. זה הקל מאוד על הגעה לעסקה הוגנת."], ["Client", "We look forward to a long relationship. Please tell me if you need anything else before we start.", "אנחנו מצפים ליחסים ארוכים. נא לספר לי אם אתם צריכים עוד משהו לפני שנתחיל."], ["Rep", "Next, our team will schedule the kickoff meeting and send you the project plan.", "בשלב הבא, הצוות שלנו יקבע את פגישת הפתיחה וישלח לכם את תוכנית הפרויקט."], ["Client", "Perfect. Let's schedule a review in three months to see how the partnership is going.", "מעולה. בוא נקבע סקירה בעוד שלושה חודשים כדי לראות איך השותפות מתקדמת."]],
  [["Presenter", "Good morning, and thank you all for being here. My presentation has three main parts.", "בוקר טוב, ותודה לכולם שאתם כאן. למצגת שלי יש שלושה חלקים עיקריים."], ["Presenter", "Let's start with a quick overview of the market. As you can see on this slide, sales increased steadily.", "בוא נתחיל בסקירה קצרה של השוק. כפי שאתם רואים בשקף הזה, המכירות עלו בקצב יציב."], ["Audience", "Could you go back to the chart? I missed the numbers.", "אפשר לחזור לגרף? פספסתי את המספרים."], ["Presenter", "Of course. Please feel free to ask questions at any time.", "בוודאי. אתם מוזמנים לשאול שאלות בכל רגע."]],
  [["Presenter", "Good morning, everyone. Today I'm going to talk about our results from last year.", "בוקר טוב לכולם. היום אני הולך לדבר על התוצאות שלנו מהשנה שעברה."], ["Presenter", "My presentation has three main parts. In this section, I'll explain how we arrived at these numbers.", "למצגת שלי יש שלושה חלקים עיקריים. בחלק הזה אסביר איך הגענו למספרים האלה."], ["Audience", "Could you explain the main reason for the increase?", "אפשר להסביר מה הסיבה המרכזית לעלייה?"], ["Presenter", "Of course. The main reason was the new pricing model. Let me show you a comparison.", "בוודאי. הסיבה המרכזית הייתה מודל התמחור החדש. תנו לי להראות לכם השוואה."]],
  [["Presenter", "The data supports our conclusion, but there are a few limitations I want to point out.", "הנתונים תומכים במסקנה שלנו, אבל יש כמה מגבלות שאני רוצה להצביע עליהן."], ["Presenter", "If you look closely at the second column, you'll notice an unexpected dip.", "אם מסתכלים היטב על העמודה השנייה, רואים ירידה לא צפויה."], ["Audience", "Is the dip related to the seasonal changes?", "האם הירידה קשורה לשינויים העונתיים?"], ["Presenter", "Yes, it is. We're still gathering evidence, so I'd treat these figures as preliminary.", "כן, היא קשורה. אנחנו עדיין אוספים ראיות, ולכן כדאי להתייחס לנתונים האלה כאל ראשוניים."]],
  [["Presenter", "Our analysis suggests that the problem is structural, not just a matter of timing.", "הניתוח שלנו מצביע על כך שהבעיה מבנית, ולא רק עניין של תזמון."], ["Audience", "What about employee morale? The numbers don't show it.", "מה לגבי המוראל של העובדים? המספרים לא מראים את זה."], ["Presenter", "That's a great point. I'd argue that the real risk lies not in the investment itself, but in delaying it.", "זו נקודה מצוינת. הייתי טוען שהסיכון האמיתי אינו בהשקעה עצמה, אלא בדחייה שלה."], ["Audience", "I see. Let's look at the costs in more detail.", "אני מבין. בוא נסתכל על העלויות בפירוט רב יותר."]],
  [["Presenter", "Our data challenges the common idea that growth must cost quality.", "הנתונים שלנו מאתגרים את הרעיון הרווח שצמיחה חייבת לבוא על חשבון איכות."], ["Audience", "But your sample is small. Can you draw such a big conclusion from it?", "אבל המדגם שלכם קטן. אפשר להסיק ממנו מסקנה כל כך גדולה?"], ["Presenter", "That's a fair question. I want to be honest about the uncertainty in these estimates.", "זו שאלה הוגנת. אני רוצה להיות כן לגבי אי הוודאות בהערכות האלה."], ["Presenter", "We shouldn't draw a big conclusion from such a small sample, even if the pattern looks convincing.", "אסור להסיק מסקנה גדולה ממדגם קטן כל כך, גם אם הדפוס נראה משכנע."]],
  [["Presenter", "Before we go to questions, let me remind you of the three main points.", "לפני שנעבור לשאלות, תנו לי להזכיר את שלוש הנקודות המרכזיות."], ["Audience", "I didn't understand the second point. Could you explain it again?", "לא הבנתי את הנקודה השנייה. אפשר להסביר שוב?"], ["Presenter", "Let me explain again, because I think my first explanation was not clear.", "תנו לי להסביר שוב, כי נראה לי שההסבר הראשון שלי לא היה ברור."], ["Presenter", "I'll share the slides after the meeting, so you can read the details.", "אשתף את השקפים אחרי הפגישה, כדי שתוכלו לקרוא את הפרטים."]],
  [["Presenter", "To finish: the facts point in one direction, but the decision still depends on the risk and the timing.", "לסיום: העובדות מצביעות לכיוון אחד, אבל ההחלטה עדיין תלויה בסיכון ובתזמון."], ["Presenter", "My advice is simple: start small, measure carefully, and grow only what works.", "העצה שלי פשוטה: להתחיל בקטן, למדוד בזהירות, ולהגדיל רק את מה שעובד."], ["Audience", "What is the next step?", "מה הצעד הבא?"], ["Presenter", "Our next step is to show the budget to the board. Thank you for your time.", "הצעד הבא שלנו הוא להציג את התקציב לדירקטוריון. תודה על הזמן."]],
  [["Manager", "I'm the project manager for the new website launch. Our main goal is to finish on time.", "אני מנהל הפרויקט של השקת האתר החדש. המטרה המרכזית שלנו היא לסיים בזמן."], ["Dev", "Got it. Who is responsible for testing the new features?", "הבנתי. מי אחראי על בדיקת התכונות החדשות?"], ["Manager", "Maria is. We're currently on schedule, but the budget is a bit tight.", "מריה. כרגע אנחנו בזמן, אבל התקציב קצת הדוק."], ["Dev", "Thanks. Please update the task board after you finish each item.", "תודה. נא לעדכן את לוח המשימות אחרי שאתם מסיימים כל פריט."]],
  [["Manager", "We've identified three risks that could delay the project. Let's assign an owner to each task.", "זיהינו שלושה סיכונים שעלולים לעכב את הפרויקט. בוא נמנה בעל תפקיד לכל משימה."], ["Dev", "Sure. The developers are working on the integration, and they expect to finish next week.", "בטח. המפתחים עובדים על האינטגרציה, והם מצפים לסיים בשבוע הבא."], ["Manager", "If the vendor delivers late, the whole timeline will shift. I'd like to escalate the issue.", "אם הספק יספק באיחור, כל לוח הזמנים יזוז. אני רוצה להעלות את הנושא לדרג גבוה יותר."], ["Dev", "Agreed. We have a dependency on the legal team, so we need their sign-off first.", "מסכים. יש לנו תלות בצוות המשפטי, לכן אנחנו צריכים את האישור שלהם קודם."]],
  [["Manager", "The original estimate didn't account for the testing phase, which is why we're behind.", "האומדן המקורי לא כלל את שלב הבדיקות, וזו הסיבה שאנחנו מאחור."], ["Dev", "We can either reduce the scope or extend the deadline. We can't do both without consequences.", "אפשר או לצמצם את ההיקף או להאריך את הדדליין. אי אפשר לעשות את שניהם בלי השלכות."], ["Manager", "I'd suggest a short retrospective after every milestone. The main bottleneck is the approval process.", "הייתי מציע סיכום קצר אחרי כל אבן דרך. צוואר הבקבוק המרכזי הוא תהליך האישורים."], ["Dev", "Let's make sure the stakeholders are informed before any major change.", "בוא נוודא שבעלי העניין מעודכנים לפני כל שינוי מהותי."]],
  [["Manager", "We have to balance the trade-off between speed and quality, and I think we've leaned too far toward speed.", "אנחנו צריכים לאזן בין מהירות לאיכות, ואני חושב שנטינו יותר מדי לכיוון המהירות."], ["Dev", "The root cause was a lack of clear communication between the teams, not the technology.", "שורש הבעיה היה חוסר תקשורת ברורה בין הצוותים, לא הטכנולוגיה."], ["Manager", "Let's agree on a change-control process, so that new requests go through a formal review.", "בוא נסכים על תהליך לניהול שינויים, כך שבקשות חדשות יעברו בדיקה רשמית."], ["Dev", "Good idea. Rather than chase perfection, we should aim for a version that delivers real value.", "רעיון טוב. במקום לרדוף אחרי שלמות, עלינו לכוון לגרסה שנותנת ערך אמיתי."]],
  [["Manager", "The schedule is ambitious, but we can meet it if we stay disciplined about scope and priorities.", "לוח הזמנים שאפתני, אבל נוכל לעמוד בו אם נישמר על ההיקף והעדיפויות."], ["Dev", "The vendor's offer looks cheaper, but the integration costs could cancel the savings.", "ההצעה של הספק נראית זולה יותר, אבל עלויות האינטגרציה עלולות לבטל את החיסכון."], ["Manager", "If we had planned better at the start, we would not have to redo so much work now.", "אילו היינו מתכננים טוב יותר מההתחלה, לא היינו צריכים לעשות עכשיו כל כך הרבה עבודה מחדש."], ["Dev", "I agree. I recommend a pilot. Real users will show problems we can't predict.", "מסכים. אני ממליץ על פיילוט. משתמשים אמיתיים יגלו בעיות שאיננו יכולים לחזות."]],
  [["Manager", "Could you walk me through why we missed the milestone, so we can learn from it?", "אפשר להסביר לי למה לא עמדנו באבן הדרך, כדי שנוכל ללמוד מזה?"], ["Dev", "We need one more backend developer, so I'd like to ask for approval.", "אנחנו צריכים מפתח נוסף לצד השרת, ולכן אני מבקש אישור."], ["Manager", "Before we agree on the new date, let's check that every team can do the work.", "לפני שנסכים על התאריך החדש, בוא נבדוק שלכל צוות יש את היכולת לעשות את העבודה."], ["Dev", "Good. I suggest a small change in the workflow. It could save us hours each week.", "טוב. אני מציע שינוי קטן בתהליך העבודה. הוא יכול לחסוך לנו שעות בכל שבוע."]],
  [["Manager", "The project is on track now. Thank you, team, for your commitment during a hard period.", "הפרויקט בדרך הנכונה עכשיו. תודה לצוות על המחויבות בתקופה קשה."], ["Dev", "Our next priority is to make the release stable. We'll fix bugs before adding anything new.", "העדיפות הבאה שלנו היא לייצב את הגרסה. נתקן תקלות לפני שנוסיף משהו חדש."], ["Manager", "Let's write down what we learned, so the next project starts stronger.", "בוא נרשום מה למדנו, כדי שהפרויקט הבא יתחיל חזק יותר."], ["Dev", "From now on, I'd like status meetings to be short and focused on decisions.", "מעכשיו, אני רוצה שפגישות הסטטוס יהיו קצרות ויתמקדו בהחלטות."]],
  [["Caller", "Hello, could I speak to Ms. Cohen, please?", "שלום, אפשר לדבר עם גב' כהן, בבקשה?"], ["Receptionist", "I'm sorry, she's not available right now. Would you like to leave a message?", "מצטערת, היא לא זמינה כרגע. תרצה להשאיר הודעה?"], ["Caller", "Yes, please tell her I'll call back this afternoon.", "כן, בבקשה תגידי לה שאתקשר שוב אחר הצהריים."], ["Receptionist", "Of course. Thank you for calling, and have a good day.", "בוודאי. תודה שהתקשרת, ויום טוב."]],
  [["Caller", "Hello, I'm calling about the invoice we received last Monday.", "שלום, אני מתקשר בנוגע לחשבונית שקיבלנו ביום שני שעבר."], ["Clerk", "I'm afraid she's in a meeting until three o'clock. Would it be convenient for you to call back?", "אני חושש שהיא בפגישה עד שלוש. האם מתאים לך להתקשר שוב?"], ["Caller", "Yes. I'd like to reschedule our call to a time that suits you better.", "כן. הייתי רוצה להעביר את השיחה לזמן שמתאים לך יותר."], ["Clerk", "Sorry, I didn't catch that. Could you say it again?", "סליחה, לא תפסתי. אפשר לחזור על זה?"]],
  [["Caller", "I'm calling because we've noticed a discrepancy between the order and the invoice.", "אני מתקשר כי שמנו לב לאי התאמה בין ההזמנה לחשבונית."], ["Clerk", "I understand that you're busy, so let me check that quickly. Our system shows a different figure.", "אני מבין שאתה עסוק, אז תן לי לבדוק את זה מהר. המערכת שלנו מראה מספר אחר."], ["Caller", "I'm not sure I understood correctly. Could you walk me through it once more?", "אני לא בטוח שהבנתי נכון. אפשר להסביר לי שוב, צעד אחר צעד?"], ["Clerk", "Of course. I'd be grateful if you could send me a written confirmation, so we can sort this out today.", "בוודאי. אודה לך אם תשלח לי אישור כתוב, כדי שנוכל לפתור את זה היום."]],
  [["Caller", "Given the urgency, I'd like to ask whether there's a way to expedite the approval process.", "לאור הדחיפות, אני רוצה לשאול אם יש דרך להאיץ את תהליך האישור."], ["Clerk", "We're open to negotiating, but we'd need some flexibility on the delivery dates.", "אנחנו פתוחים למשא ומתן, אבל נצטרך מעט גמישות בתאריכי האספקה."], ["Caller", "I'd prefer to handle this by email so that we have a clear written record.", "הייתי מעדיף לטפל בזה במייל, כדי שיהיה לנו תיעוד כתוב ברור."], ["Clerk", "Sure. I'm not able to make a commitment on the date until I've checked with our warehouse.", "בטח. איני יכול להתחייב לתאריך לפני שאבדוק עם המחסן שלנו."]],
  [["Caller", "Thank you for your call. I appreciate you explaining things in detail.", "תודה על השיחה. אני מעריך שהסברת את הדברים בפירוט."], ["Clerk", "I can't give you an answer right now. The committee meets on Wednesdays.", "איני יכול לתת לך תשובה עכשיו. הוועדה מתכנסת בימי רביעי."], ["Caller", "I hear you, but I'm not sure the new change solves the real problem.", "אני שומע אותך, אבל אני לא בטוח שהשינוי החדש פותר את הבעיה האמיתית."], ["Clerk", "Let's agree on a deadline for the next step, so we don't wait forever.", "בוא נסכים על דדליין לצעד הבא, כדי שלא נחכה לנצח."]],
  [["Caller", "I'm calling about the voicemail I left on Monday. I want to make sure you got it.", "אני מתקשר בנוגע להודעה הקולית שהשארתי ביום שני. אני רוצה לוודא שקיבלת אותה."], ["Clerk", "Hold on, I'm going to check the system. Sorry, the line dropped. Could you call me back?", "רגע, אני הולך לבדוק במערכת. סליחה, הקו נותק. אפשר להתקשר אליי חזרה?"], ["Caller", "Of course. Before we hang up, let me repeat what we decided.", "בוודאי. לפני שנסיים, תן לי לחזור על מה שהחלטנו."], ["Clerk", "Thanks for waiting. Is there anything else I can do for you today?", "תודה שחיכית. יש עוד משהו שאוכל לעשות בשבילך היום?"]],
  [["Caller", "Thank you for your time today. We made real progress, and I look forward to the next steps.", "תודה על הזמן היום. התקדמנו באמת, ואני מצפה לצעדים הבאים."], ["Clerk", "I'll send you a summary email within the hour, so you have everything in writing.", "אשלח לך מייל עם סיכום תוך שעה, כך שיהיה לך הכול בכתב."], ["Caller", "Please call me if anything comes up before our meeting on Thursday.", "נא להתקשר אליי אם משהו יעלה לפני הפגישה שלנו ביום חמישי."], ["Clerk", "It was good talking to you. Thanks for calling. I'll make sure your question gets to the right person.", "היה נעים לדבר איתך. תודה על השיחה. אדאג שהשאלה שלך תגיע לאדם הנכון."]],
  [["Traveler", "I have a flight to London on Monday morning. Could you book a hotel near the airport?", "יש לי טיסה ללונדון ביום שני בבוקר. אפשר להזמין מלון ליד שדה התעופה?"], ["Assistant", "Of course. Would you like a window seat for the flight too?", "בוודאי. תרצה גם מושב ליד החלון לטיסה?"], ["Traveler", "Yes, if possible. Do I need a visa for this trip?", "כן, אם אפשר. האם אני צריך ויזה לנסיעה הזאת?"], ["Assistant", "No, but please check the entry rules before you go.", "לא, אבל נא לבדוק את כללי הכניסה לפני שאתה נוסע."]],
  [["Traveler", "I'd like to change my return flight to a later date. Is breakfast included in the room rate?", "אני רוצה לשנות את טיסת החזור שלי לתאריך מאוחר יותר. האם ארוחת הבוקר כלולה במחיר החדר?"], ["Assistant", "Yes, breakfast is included. Could you recommend a good restaurant near the office too?", "כן, ארוחת הבוקר כלולה. אפשר גם להמליץ על מסעדה טובה ליד המשרד?"], ["Traveler", "Sure, I'd be happy to. The shuttle to the airport leaves every hour from the lobby, right?", "בטח, אשמח. ההסעה לשדה התעופה יוצאת כל שעה מהלובי, נכון?"], ["Assistant", "That's right. I'm afraid the hotel has no record of our reservation.", "נכון. אני חושש שאין למלון רישום של ההזמנה שלנו."]],
  [["Traveler", "Unfortunately, my connecting flight was canceled, so I had to rebook through Frankfurt.", "לצערי, הטיסה המקשרת שלי בוטלה, ולכן נאלצתי להזמין מחדש דרך פרנקפורט."], ["Assistant", "I'm sorry to hear that. Would it be possible to upgrade your room, since you're arriving late?", "מצטער לשמוע. האם אפשר לשדרג את החדר שלך, מכיוון שאתה מגיע מאוחר?"], ["Traveler", "Yes, please. I'd like to request reimbursement for the taxi, but I'm not sure it falls under the policy.", "כן, בבקשה. הייתי רוצה לבקש החזר על המונית, אבל אני לא בטוח שזה נכלל במדיניות."], ["Assistant", "Let me check. The company covers the extra night if the trip is extended by a day.", "תן לי לבדוק. החברה מכסה את הלילה הנוסף אם הנסיעה מתארכת ביום אחד."]],
  [["Traveler", "Given the time difference, I'd suggest we schedule the call for early afternoon, our time.", "בהתחשב בפער השעות, הייתי מציע שנקבע את השיחה לתחילת אחר הצהריים, לפי השעון שלנו."], ["Partner", "Sounds good. Could you provide a breakdown of the hotel charges? One item seems to be double-counted.", "נשמע טוב. אפשר לקבל פירוט של חיובי המלון? נראה שאחד הסעיפים נספר פעמיים."], ["Traveler", "I'll check that. Given the jet lag, I'd recommend we keep the first day light.", "אבדוק את זה. בהתחשב בג'ט־לג, הייתי ממליץ לשמור על היום הראשון קל."], ["Partner", "Agreed. I'm happy to travel, but I'd appreciate some notice so I can arrange childcare.", "מסכים. אני שמח לנסוע, אבל אודה להודעה מוקדמת כדי שאוכל לסדר שמירה לילדים."]],
  [["Partner", "Even though the trip was tiring, the progress we made will help our partnership for years.", "למרות שהנסיעה הייתה מתישה, ההתקדמות שעשינו תעזור לשותפות שלנו לשנים."], ["Traveler", "If we hadn't changed the schedule, we would have missed the signing ceremony.", "אם לא היינו משנים את הלוח, היינו מפספסים את טקס החתימה."], ["Partner", "Because of the situation in the region, we need to check the safety rules first.", "בגלל המצב באזור, אנחנו צריכים לבדוק קודם את כללי הבטיחות."], ["Traveler", "Agreed. The two sites are far apart, so one travel day can take half of our work time.", "מסכים. שני האתרים רחוקים זה מזה, לכן יום נסיעה אחד יכול לקחת חצי מזמן העבודה שלנו."]],
  [["Traveler", "Could you tell me the check-in and check-out times, and whether early check-in is possible?", "אפשר לספר לי את שעות הצ'ק־אין והצ'ק־אאוט, ואם אפשר צ'ק־אין מוקדם?"], ["Assistant", "Check-in is at three and check-out is at noon. Early check-in is possible if you pay extra.", "הצ'ק־אין בשלוש והצ'ק־אאוט בצהריים. צ'ק־אין מוקדם אפשרי אם משלמים תוספת."], ["Traveler", "I'll need to check the flight times first. Let me call the airline.", "אצטרך לבדוק קודם את זמני הטיסה. תן לי להתקשר לחברת התעופה."], ["Assistant", "Of course. Please bring your ID and your printed boarding passes to the airport.", "בוודאי. נא להביא את תעודת הזהות ואת כרטיסי העלייה המודפסים לשדה התעופה."]],
  [["Manager", "Overall, the trip went well, and the relationships we built with the client team will help us.", "בסך הכול, הנסיעה הייתה טובה, והקשרים שבנינו עם צוות הלקוח יעזרו לנו."], ["Traveler", "I'll send the expense report by Friday, and I've attached the receipts so approval is faster.", "אשלח את דוח ההוצאות עד יום שישי, וצירפתי את הקבלות כדי שהאישור יהיה מהיר יותר."], ["Manager", "Thanks for handling the logistics so well. The whole team saw how much effort you put in.", "תודה שטיפלת בלוגיסטיקה כל כך טוב. כל הצוות ראה כמה מאמץ השקעת."], ["Traveler", "Thank you. Before the next trip, let's agree on a checklist, so we don't forget anything.", "תודה. לפני הנסיעה הבאה, בוא נסכים על רשימת בדיקה, כדי שלא נשכח שום דבר."]],
  [["HR", "Welcome to the team! We're happy to have you on board. Your manager will show you around this morning.", "ברוכים הבאים לצוות! אנחנו שמחים שאתה מצטרף אלינו. המנהל שלך יעביר אותך במשרד הבוקר."], ["New hire", "Thank you so much. Where can I find the cafeteria?", "תודה רבה. איפה אפשר למצוא את הקפיטריה?"], ["HR", "It's on the second floor, next to the elevator. Feel free to ask me anything.", "היא בקומה השנייה, ליד המעלית. אתה מוזמן לשאול אותי כל דבר."], ["New hire", "Great. I'll ask if I have questions.", "מצוין. אשאל אם יהיו לי שאלות."]],
  [["HR", "Welcome to the team! Your probation period is three months, and we'll review your progress.", "ברוכים הבאים לצוות! תקופת הניסיון שלך היא שלושה חודשים, ונבחן את ההתקדמות שלך."], ["New hire", "Thank you. Could you tell me when the training budget can be used?", "תודה. אפשר לספר לי מתי אפשר לנצל את תקציב ההדרכה?"], ["HR", "Your annual leave accrues each month, and you can use it after the first quarter.", "חופשת השנה שלך נצברת מדי חודש, ואפשר לנצל אותה אחרי הרבעון הראשון."], ["New hire", "Great. Please let me know if I need any changes to my schedule.", "מצוין. נא לעדכן אותי אם אני צריך שינויים בלוח שלי."]],
  [["HR", "We're looking for a candidate who can take ownership of recruitment for the whole department.", "אנחנו מחפשים מועמד שיוכל לקחת אחריות על הגיוס של כל המחלקה."], ["Candidate", "I'd like to know more. Does the job require strong communication skills?", "הייתי רוצה לדעת עוד. האם התפקיד דורש כישורי תקשורת חזקים?"], ["HR", "Yes, since you'll be working with managers at all levels. We noticed a drop in engagement scores.", "כן, כי תעבוד עם מנהלים בכל הדרגים. שמנו לב לירידה בציוני המעורבות."], ["Candidate", "I see. Please make sure the job description is up to date before you publish it.", "אני מבין. נא לוודא שתיאור התפקיד מעודכן לפני שמפרסמים אותו."]],
  [["HR", "We understand that the restructuring has been unsettling, and we're committed to keeping everyone informed.", "אנחנו מבינים שהארגון מחדש היה מטלטל, ואנחנו מחויבים לעדכן את כולם."], ["Employee", "Could you clarify how the bonus criteria were applied this year?", "אפשר להבהיר איך יושמו קריטריוני הבונוס השנה?"], ["HR", "Of course. The new policy is designed to make expectations explicit.", "בוודאי. המדיניות החדשה נועדה להפוך את הציפיות לברורות."], ["Employee", "Thank you. I'd like to discuss my development plan, if possible.", "תודה. הייתי רוצה לדון בתוכנית ההתפתחות שלי, אם אפשר."]],
  [["Employee", "Why did the company change the policy? It seems unfair to some of us.", "למה החברה שינתה את המדיניות? זה נראה לא הוגן לחלק מאיתנו."], ["HR", "We changed it after feedback from several departments. It has created some new tension.", "שינינו אותה אחרי משוב ממחלקות שונות. זה יצר מתח חדש."], ["Employee", "I see. Had you asked the team earlier, you could have predicted many of these concerns.", "אני מבין. אילו הייתם שואלים את הצוות מוקדם יותר, יכולתם לצפות הרבה מהחששות האלה."], ["HR", "That's a fair point. Our policy protects privacy, but I can assure you the review was thorough.", "זו נקודה הוגנת. המדיניות שלנו שומרת על פרטיות, אבל אני יכול להבטיח לך שהבדיקה הייתה יסודית."]],
  [["Manager", "Could you tell me what you hope to get from the next review, so I can prepare?", "אפשר לספר לי מה אתה מקווה להשיג בבדיקה הבאה, כדי שאוכל להתכונן?"], ["Employee", "I'd like to set clear goals for next quarter. Success should mean more responsibility.", "הייתי רוצה לקבוע יעדים ברורים לרבעון הבא. הצלחה צריכה להיות אחריות רבה יותר."], ["Manager", "Let's meet again in two weeks to see how the plan works in practice.", "בוא נתכנס שוב בעוד שבועיים כדי לראות איך התוכנית עובדת בפועל."], ["Employee", "Sounds good. Thank you for being honest in our discussion.", "נשמע טוב. תודה שהיית כנה בדיון שלנו."]],
  [["Manager", "Thank you for your hard work this year. Your work made a real difference for the team.", "תודה על העבודה הקשה השנה. העבודה שלך עשתה הבדל אמיתי לצוות."], ["Employee", "Thank you. I hope the new arrangement works well for everyone.", "תודה. אני מקווה שההסדר החדש יעבוד היטב לכולם."], ["Manager", "I'm glad to confirm your promotion. Our door is always open, and you're always welcome to talk to me.", "אני שמח לאשר את הקידום שלך. הדלת שלנו תמיד פתוחה, ואתה תמיד מוזמן לדבר איתי."], ["Employee", "Thank you for everything. I wish us success in the next step.", "תודה על הכול. אני מאחל לנו הצלחה בשלב הבא."]]
];

const CAREER_EXPLAIN = [
  ["הפתיחה \"Thank you for taking the time\" היא ביטוי מקובל לתודה על הזמן. \"Taking the time\" = להקדיש זמן, ולכן נאמר \"for taking\" ולא \"for to take\".", "להביע ניסיון שנמשך עד היום משתמשים ב-Present Perfect Continuous: \"have been working\". \"For three years\" מציין את משך הזמן. בעברית זה \"עובד כבר שלוש שנים\".", "\"My main responsibility was\" משתמש בעבר כי מדובר בתפקיד שכבר נגמר. אחרי \"handling\" בא שם הפעולה (ing), ולא \"to handle\".", "בתיאור לימודים משתמשים ב-Past Simple: \"I studied\". Present Perfect (\"I have studied\") מתאים רק כשהלימודים עדיין נמשכים או כשהם משפיעים עכשיו.", "\"A position where I can...\" מציג תפקיד מוגדר בצורה כללית. \"Where\" מחבר בין התפקיד לבין מה שאני יכול לעשות בו.", "\"Feel comfortable + ing\" = מרגיש נוח לעשות משהו. זו דרך טבעית להגיד שאתה נוח עם עבודה מסוימת. בלי \"to\" אחרי \"comfortable\".", "\"Could you tell me more about\" היא שאלה מנומסת. \"The team I would be joining\" משתמש ב-would כי זה עתידי בעבר: הצוות שאצטרף אליו.", "\"Excited about\" + שם עצם או ing = מתלהב ממשהו. \"The chance to work\" מציין הזדמנות עתידית.", "\"Would describe\" מתאר מה מישהו אחר היה אומר עלי. \"Would\" מציין השערה, כלומר אני לא מדבר בשם המנהל.", "\"Available to start\" = זמין להתחיל. \"Within two weeks\" = תוך שבועיים, לא \"in two weeks\" שמציין נקודה מסוימת בעתיד."],
  ["\"One of my strengths is that...\" = אחת החוזקות שלי היא. פותחים כך כדי להציג חוזקה בבירור. \"Stay calm\" = להישאר רגוע.", "\"Tend to\" = נוטה ל-, לתיאור הרגל. \"Too detailed\" = מפורט מדי. אחרי המגבלה בא פתרון, ולכן \"so I have started\".", "\"I work best when...\" מציג תנאים שבהם הכי טוב לי. זה דרך לעזור למראיין להבין איך להציב אותך, בלי לדבר על עצמך בצורה מתנשאת.", "\"Used to be\" מתאר מצב שהיה בעבר ואינו נכון יותר. \"But I have improved\" מציג את השיפור ב-Present Perfect כי השיפור קיים עכשיו.", "\"Take feedback seriously\" = לקחת משוב ברצינות. \"Act on it\" = לפעול לפיו. שני ביטויים קבועים שמתארים בשלות מקצועית.", "\"Good at\" + ing (explaining). אחרי \"at\" תמיד בא שם פועל בצורת ing, לא \"to explain\".", "\"Learned to say no\" מתאר למידה שהתרחשה, והיא נמשכת: \"I've learned\" (Present Perfect), כי זו תובנה שאני מחזיק בה עכשיו.", "\"Helps me understand\" = עוזר לי להבין. \"Really\" לפני \"need\" מדגיש את ההבדל בין מה שלקוחות אומרים לבין מה שהם צריכים באמת.", "\"Can be impatient with\" = לפעמים אני לא סבלני. \"Working on it\" = אני עובד על זה. ההודאה במגבלה מתונה והשיפור מוצג מיד אחריה.", "\"Has taught me a lot\" = לימד אותי הרבה. מבנה Present Perfect: הלימוד נמשך והשפיע עכשיו. \"Working with people\" הוא נושא ב-ing."],
  ["סיפור בראיון מתחיל ב-Past Simple: \"introduced\", \"saved\". \"A day\" = ליום, כלומר כל יום. התוצאה מוצגת במספר מדויק.", "\"Met with\" = נפגש עם. מתאים לפגישה עם לקוח. \"To resolve it\" מציין את המטרה, ומשתמשים ב-to + פועל.", "\"Split the team into two groups\" = חילקתי את הצוות לשתי קבוצות. \"Into\" מציין כיוון לחלוקה. \"Tight deadline\" הוא דדליין קצר, ביטוי קבוע.", "\"I was asked to train\" = ביקשו ממני להדריך. זו צורה סבילה (was asked) שמתארת משימה שמישהו נתן לי.", "\"Misjudged\" הוא פועל עבר שמתאר טעות בהערכה. באנגלית מדברים על הטעות עצמה, לא על מה שגרם לה.", "\"Test assumptions\" = לבדוק הנחות. \"Now I always\" מציג שינוי בהרגל. \"Early\" = מוקדם, בלי צורך ב-\"in the process\".", "\"Negotiated a better price\" = ניהלתי משא ומתן על מחיר טוב יותר. \"Which saved\" מתייחס לכל המשפט הקודם, ולכן מופיע פסיק לפניו.", "\"Worked with\" + צוות = עבדתי עם צוות. \"Until it was fixed\" = עד שהבעיה תוקנה. סבילה (was fixed) כי מה שחשוב הוא התיקון, לא מי תיקן.", "\"Was promoted\" = קודמתי. זו צורה סבילה שמתארת קידום שנעשה לי. \"After six months\" מציין אחרי כמה זמן.", "\"I'd like to show you\" = הייתי רוצה להראות לכם, נוסח מנומס. \"That changed\" מתייחס לדוח עצמו. \"I created\" הוא משפט יחסי (relative clause) שמתאר את הדוח."],
  ["\"Interested in this role because...\" = מעוניין בתפקיד הזה כי. זו דרך ברורה להסביר מוטיבציה, והסיבה באה מיד אחרי \"because\".", "\"What attracts me most is...\" = מה שמושך אותי יותר מכול הוא. זה מבנה של משפט חיתוך (cleft sentence) שמדגיש את הנקודה החשובה.", "\"Not just a job\" = לא סתם עבודה. \"Long-term growth\" = צמיחה לטווח ארוך. זו הבחנה נפוצה בראיונות.", "\"In line with\" = תואם ל-. ביטוי נפוץ לדיבור על שכר בצורה ענינית וללא נימה של דרישה.", "\"Would be happy to discuss\" = אשמח לדון. \"Once we know\" אחרי פסיק עם הווה, כי זה תנאי בעתיד (once + present).", "\"Not only... I also care about\" מציג שני דברים חשובים. \"I'm not only looking at\" מוסיף את הדגש על מה שמעניין אותי.", "\"How performance is reviewed\" הוא שאלה עקיפה, ולכן בא סדר מילים של משפט רגיל ולא שאלה (\"is reviewed\" ולא \"is performance reviewed\").", "\"A role that offers more responsibility\" = תפקיד שמציע אחריות רבה יותר. \"Over time\" מציין התפתחות לאורך זמן.", "\"Depending on\" = בהתאם ל-. \"Notice period\" = תקופת ההודעה המוקדמת לפני סיום עבודה קודמת. ביטוי מקצועי בהתחלה.", "\"Would be a real benefit\" = תהיה הטבה אמיתית. \"Real\" מדגיש שזה משמעותי, בלי להיות דרמטי."],
  ["\"Could you give me an example of\" = אפשר לתת דוגמה ל-. זו שאלה מנומסת שמבקשת סיפור מהעבר.", "\"How would you handle\" שואל מה היית עושה בתרחיש. זה תרחיש היפותטי, ולכן \"would\" ולא \"will\".", "\"Start by listening... and then finding\" = מקבילות: אחרי \"start by\" ו-\"then\" באים שמות פעולה (ing) באותה צורה. זה נשמע מסודר וטבעי.", "תנאי מסוג 1 (If + הווה, I'll + פועל) מתאר תוצאה אפשרית וסבירה בעתיד. בתוך משפט התנאי הזמן הוא הווה: \"If a deadline is at risk\", לא \"will be\".", "\"I'm not sure I have... but I know how to\" מודה שאין לי כל התשובות, בלי להיראות חלש, כי \"I know how\" מציג יכולת.", "\"When I disagree\" = כשאני לא מסכים. \"Raise the issue privately and respectfully\" = להעלות את הנושא בפרטיות ובכבוד. שני תארי פועל (privately, respectfully) שמתארים את הדרך.", "\"Asking for help early is a sign of strength\" = לבקש עזרה מוקדם הוא סימן של חוזק. ביטוי נפוץ לשיח על התנהלות מקצועית. \"Not weakness\" מחזק את הניגוד.", "\"Handles conflicts\" = מתמודד עם מחלוקות. \"Handle\" + שם עצם הוא ביטוי עסקי נפוץ, \"deal with\" נשמע פחות פורמלי.", "תנאי מסוג 2 (If + Past, I'd + פועל): תרחיש שלא קורה במציאות. \"If I were\" הוא הצורה הסטנדרטית בתנאי מסוג 2, גם עם I.", "\"Keep my cool\" = לשמור על קור רוח. \"Even when\" = גם כאשר. \"Becomes stressful\" מציג שינוי במצב, בלי להניח שזה קרה."],
  ["\"What does a typical day look like\" = איך נראה יום טיפוסי. שאלה פתוחה שמזמינה תיאור של השגרה, ולכן \"does\" ולא \"do\" (שאלה על מצב כללי).", "\"The biggest challenges\" = האתגרים הגדולים. \"Team is facing\" = הצוות מתמודד. אחרי \"the team\" הפועל בלשון יחיד (\"is\"), כי הצוות הוא יחידה אחת.", "\"How do you measure success\" שואל על שיטה. \"Someone in this position\" = מישהו בתפקיד הזה, דרך כללית ומנומסת לשאול על ציפיות.", "\"Who would I be working with\" שואל על עמיתים עתידיים. \"Most closely\" = הכי קרוב, ביטוי מדויק לקשר עבודה.", "\"What kind of training\" = איזה סוג של הכשרה. \"What kind of\" + שם עצם בלשון יחיד (\"kind of training\") הוא מבנה טבעי לשאלה על סוג.", "\"Take on new projects\" = לקחת על עצמי פרויקטים חדשים. \"After the first year\" מציין מתי: שאלה על הזדמנות עתידית.", "\"How would you describe\" מזמין תיאור. \"Management style\" = סגנון ניהול, מונח נפוץ בראיון.", "\"Why is this position open\" = מדוע התפקיד פתוח. \"Open\" במשמעות של פנוי למילוי. השאלה נשאלת בנימוס ולא מאשימה.", "\"Are there any plans to\" שואל על תכניות קיימות בלי להניח שיש. \"Plans to + פועל\" = כוונות עתידיות. \"Expand the team\" = להרחיב את הצוות.", "\"The next step in the hiring process\" = השלב הבא בתהליך הגיוס. שאלה ישירה, מקצועית ומובנת."],
  ["\"Thank you again for your time\" היא סגירה מקצועית של ראיון. \"I really enjoyed\" = נהניתי באמת. שני משפטים נפרדים עם נקודה, לא פסיק.", "\"Look forward to hearing\" = מצפה לשמוע. אחרי \"look forward to\" בא ing, לא \"to hear\". זה ביטוי סגירה נפוץ מאוד במייל ובשיחה.", "\"Feel free to contact me\" = אל תהסס לפנות אליי. ביטוי מנומס שמזמין, אבל \"if you need any more information\" הוא התנאי.", "\"I'll send a short follow-up email\" = אשלח מייל קצר של מעקב. \"To confirm my interest\" מציין את המטרה של המייל.", "\"Would it be possible to get an answer\" = האם אפשר לקבל תשובה. שאלה מנומסת מאוד שמבקשת דחייה קלה בזמן.", "\"It was a pleasure meeting you\" = היה לי העונג להכיר אותך. \"Meeting\" אחרי \"pleasure\" הוא ing, ו-\"and I hope we can\" מוסיף תקווה לעבודה משותפת.", "\"Happy to come back\" = שמח לחזור. \"If needed\" מציין תנאי קצר: אם יידרש, בלי להזכיר את התנאי במלואו.", "\"I'll bring my portfolio\" = אביא את תיק העבודות שלי. \"Bring\" משמש כשמביאים משהו לפגישה, לא \"take\".", "\"Thank you for the detailed explanation\" = תודה על ההסבר המפורט. ביטוי הכרה מכובד, ו-\"detailed\" מדגיש שההסבר היה מלא.", "\"I'm confident that my experience matches\" = אני בטוח שהניסיון שלי מתאים. \"What you're looking for\" = מה שאתם מחפשים, ביטוי ניטרלי ומנומס."],
  ["\"Hello Dana\" הוא פתיחה רשמית למייל עם שם. \"I'm attaching\" = אני מצרף. ביטוי קבוע במייל: בזמן הווה כי הפעולה נעשית עכשיו עם שליחת המייל.", "\"Thanks for your quick reply\" = תודה על תשובתך המהירה. \"Yesterday\" מציין את זמן התשובה, ולכן משתמשים ב-Past Simple בהקשר.", "\"Could we schedule a meeting\" = אפשר לקבוע פגישה. \"For next Thursday\" = ליום חמישי הבא. בשאלה משתמשים ב-\"could\" כדי להיות מנומסים.", "\"I'm sorry for the delay\" = אני מתנצל על העיכוב. \"Getting back to you\" = לחזור אליך, ביטוי נפוץ במייל לתשובה מאוחרת.", "\"Please confirm that you received\" = נא לאשר שקיבלת. \"Revised\" = מעודכן. \"Please\" בתחילת המשפט מבקש בצורה ישירה ומנומסת.", "\"I'm available any time tomorrow morning\" = אני זמין כל שעה מחר בבוקר. \"Any time\" מדגיש גמישות.", "\"Please let me know if anything changes\" = נא לעדכן אותי אם משהו משתנה. ביטוי קבוע לבקשת עדכון, ו-\"on your side\" מסמן שהשינוי אצל הצד השני.", "\"Has been moved\" = הועבר. זו צורה סבילה (has been + V3): לא חשוב מי העביר, והפגישה היא הנושא.", "\"The notes... are attached\" = הסיכומים מצורפים. מכיוון ש-\"notes\" הוא שם ברבים, הפועל בא בלשון רבים (\"are\").", "\"Best regards\" = בברכה, סיום מכובד. אחריו פסיק, ואחריו השם בשורה נפרדת או באותה שורה, לפי הנוהג."],
  ["\"I'm writing to check\" = אני כותב כדי לבדוק. \"To check\" מציין את המטרה, ו-\"The status of\" = מצב. זו פתיחה ברורה למייל בירור.", "\"Couldn't open the file\" = לא הצלחתי לפתוח את הקובץ, בעבר. \"So could you resend it\" = לכן אפשר לשלוח שוב, בשאלה מנומסת.", "\"Would appreciate\" = אודה. \"By the end of the week\" מציין מועד אחרון. צורת הנימוס היא \"would appreciate\" ולא \"want\".", "\"Thank you for your patience\" = תודה על הסבלנות. \"We are working on the issue right now\" מציג מצב עכשיו, בהווה מתמשך.", "\"I suggest we move\" = אני מציע שנעביר. \"Suggest\" + מילת פועל בלי \"to\" (כאן \"we move\"), מתאר הצעה מנומסת.", "\"What was agreed\" = מה שסוכם. מבנה סביל שלא מציין מי הסכים, מתאים כשהפעולה חשובה יותר מהאדם.", "\"We need approval\" = אנחנו צריכים אישור. \"Before we can move forward\" = לפני שנוכל להתקדם. \"Can\" אחרי \"before\" מציין יכולת.", "\"I've added your colleague\" = הוספתי את העמית שלך. Present Perfect כי הפעולה הושלמה ומשפיעה עכשיו: העמית נמצא ברשימה.", "\"That sounds like a good solution\" = זה נשמע כמו פתרון טוב. מגיב להצעה בצורה נעימה. \"But let's check\" מציג הסתייגות.", "\"I'd be grateful if you could reply\" = אודה לך אם תוכל לענות. מבנה נימוס מאוד, שנשמע מכובד במייל."],
  ["\"As agreed in our call\" = כפי שסוכם בשיחה. \"I'm sending you\" = אני שולח לך, בהווה כי זו הפעולה שמתרחשת עכשיו.", "\"I'm not sure... so I'd welcome your suggestions\" = לא בטוח, לכן אשמח להצעות. זה מבנה נימוס: מודים בחוסר ודאות ופותחים לשיתוף פעולה.", "תנאי מסוג 1: \"If the delay is caused, please let us know\". אחרי \"if\" בא הווה (\"is caused\"), גם כשמדובר בעתיד.", "\"I've highlighted the key points\" = סימנתי את הנקודות המרכזיות. \"But please review it once more\" מציג הבקשה. \"Once more\" = פעם נוספת.", "\"Unless you can offer\" = אלא אם תוכלו להציע. \"Unless\" = אלא אם כן, מילה שמחליפה \"if not\". \"Better terms\" = תנאים טובים יותר.", "\"I'd appreciate it if you could coordinate\" = אודה אם תוכל לתאם. מבנה נימוס שבו \"it\" הוא מילת הכנה לתנאי (\"if you could\").", "\"So far we haven't received\" = עד כה לא קיבלנו. Present Perfect עם \"so far\" כי מדובר בתקופה שעדיין נמשכת.", "\"Higher than what we need\" = גבוה ממה שאנחנו צריכים. \"What we need\" הוא נושא מלא בתוך המשפט, בלי \"that\" אחרי \"than\".", "\"Please make sure the invoice includes\" = נא לוודא שהחשבונית כוללת. \"Make sure\" + משפט, והפועל \"includes\" בלשון יחיד כי \"invoice\" הוא יחיד.", "\"We'd love to hear your opinion\" = נשמח לשמוע את דעתך. \"Before we finalize the decision\" = לפני שנסגור את ההחלטה. \"Before\" + הווה."],
  ["\"Following your message on Monday\" פותח מייל תגובה רשמי. \"Has been referred to\" = הועבר ל-, צורה סבילה שמדגישה את התהליך.", "\"We appreciate your patience\" = אנו מודים על הסבלנות. \"We're unable to meet\" = איננו מסוגלים לעמוד. \"Unable to\" מנוסח רשמי יותר מ-\"can't\".", "\"I recommend that we review\" = אני ממליץ שנבחן. אחרי \"recommend that\" בא פועל בלי \"s\" (\"review\", לא \"reviews\"). זו צורת ההצעה בסגנון רשמי.", "\"Because of recent budget changes\" = בגלל שינויים בתקציב. \"Because of\" + שם עצם, ו-\"because\" + משפט מלא. \"Reassess\" = לבחון מחדש.", "\"I'd be grateful if you could clarify\" = אודה אם תוכל להבהיר. \"Before we sign\" = לפני שנחתום. \"Before\" מתייחס לעתיד, אבל הפועל בהווה.", "\"This may delay the launch\" = זה עלול לעכב את ההשקה. \"May\" מציין אפשרות. \"It's important to update all the teams\" = חשוב לעדכן את כל הצוותים.", "\"In light of the findings\" = לאור הממצאים. ביטוי רשמי שמציג בסיס להחלטה. \"I suggest we postpone\" = אני מציע לדחות. בלי \"to\" אחרי \"we\".", "\"I want to make sure everyone understands\" = אני רוצה לוודא שכולם מבינים. \"Make sure\" + משפט, ו-\"before we continue\" = לפני שנמשיך.", "\"Based on the comments\" = בהתבסס על ההערות. \"Based on\" מציין על מה נשען הדבר. \"Meeting summary\" = סיכום הישיבה, שם עצם כפול.", "\"I would appreciate it if you could\" = אודה אם תוכל. צורה מכובדת שמבקשת תשובה ב\"אישור קבלה\" ו\"זמן משוער\"."],
  ["\"After we reviewed the proposal\" = אחרי שבחנו את ההצעה. Past Simple אחרי \"after\" כי הפעולה הסתיימה, ו-\"we think\" בהווה כי זו דעה עכשיו.", "\"Because of the current limits\" = בגלל המגבלות הנוכחיות. \"We have to reduce\" = אנחנו צריכים לצמצם. \"Have to\" מציין הכרח חיצוני.", "\"Still haven't received\" = עדיין לא קיבלנו. Present Perfect עם \"still\" מציין שמשהו לא קרה עד עכשיו. \"Please answer the points I raised\" = הנקודות שהעליתי.", "\"Despite the difficulties\" = למרות הקשיים. אחרי \"despite\" בא שם עצם או ing, בלי \"of\" ובלי \"that\". \"Grateful for that\" = אסירי תודה על כך.", "\"We realized that\" + Past Simple: \"were not based\" = לא התבססו. ההתרחשות באה בעבר, והתובנה נמשכת. \"Current data\" = נתונים עדכניים.", "\"Permission to use\" = רשות לשימוש. אחרי \"permission\" בא \"to\" + פועל. \"We need clear permission\" מדגיש שזה נדרש במפורש.", "\"We should have told\" = היה עלינו לספר. \"Should have\" + V3 מתאר טעות בעבר. \"So they would not be confused\" מציין את המטרה של הדיווח.", "תנאי מסוג 1: \"If we don't get approval, we may have to cancel\". \"May have to\" = אולי נצטרך. \"By Tuesday\" מציין מועד אחרון.", "\"I understand your request, but\" = אני מבין את הבקשה, אבל. \"I don't have the authority to approve\" = אין לי הסמכה לאשר. \"Right now\" מדגיש שזה המצב כרגע.", "\"Let's set up another call so we can agree\" = בוא נקבע שיחה נוספת כדי שנסכים. \"Set up\" = לקבוע, ו-\"so we can\" מציין את המטרה."],
  ["\"I'm following up on the email\" = אני חוזר למייל. \"I haven't heard back yet\" = עדיין לא קיבלתי תשובה. Present Perfect עם \"yet\" כי ההמתנה נמשכת.", "\"Could you update me on\" = אפשר לעדכן אותי לגבי. \"On\" אחרי \"update\" מציין את הנושא שמעדכנים לגביו.", "\"Please find attached\" = מצורף, ביטוי רשמי במייל. \"The signed agreement for your records\" = ההסכם החתום לתיעוד שלך.", "\"I've copied my manager\" = העתקתי את המנהל שלי. Present Perfect כי העתקה נעשתה עכשיו. \"So that we can decide together\" מציין את המטרה.", "תנאי מסוג 1: \"We can change the timeline if the scope changes\". \"If\" + הווה (\"changes\") גם כשמדובר בעתיד.", "\"Before I reply\" = לפני שאענה. \"Before\" + הווה. \"Which version of the document you mean\" = לאיזו גרסה אתה מתכוון. המילה \"mean\" בסוף השאלה.", "\"Thanks for pointing out the mistake\" = תודה שהצבעת על הטעות. \"I'll fix it and send you the new file\" = אתקן ואשלח לך את הקובץ. עבר בתשובה לטעות של האחר בנימוס.", "\"We need a few more days to read\" = אנחנו צריכים עוד כמה ימים כדי לקרוא. \"A few\" = כמה, מספר קטן וחיובי. \"Carefully\" מתאר את אופן הקריאה.", "\"If you have any concerns, please tell me\" = אם יש לך הסתייגויות, נא לומר לי. \"Any\" אחרי \"have\" בתנאי מתייחס לכל דבר שייתכן, בלי להניח שיש בעיה.", "\"I'd be grateful for a short call to answer\" = אודה לשיחה קצרה כדי לענות. \"For a call\" משמש לשיחה קצרה, \"to answer\" מציין מטרה."],
  ["\"Thank you for your detailed feedback\" = תודה על המשוב המפורט. \"It helped us improve\" = זה עזר לנו לשפר. \"Helped\" + פועל בלי \"to\" במקרים רבים.", "\"Sorry for the problem caused by\" = מצטערים על הבעיה שנגרמה מ-. \"Caused by\" הוא ביטוי סביל שמראה את הגורם של הבעיה.", "\"We fixed the problem on our side\" = תיקנו את הבעיה מצידנו. \"On our side\" = מהצד שלנו. \"We expect the next shipment on time\" = אנו מצפים שהמשלוח יגיע בזמן.", "\"As we discussed\" = כפי שדיברנו. \"I'll follow up on this\" = אעקוב אחרי זה. \"Update you every week\" = לעדכן אותך כל שבוע. \"Every week\" = בכל שבוע.", "\"We don't have much time, so let's start\" = אין לנו הרבה זמן, לכן בוא נתחיל. הצעה מפורשת לסדר עדיפויות. \"Much\" משמש עם שם עצם שאי אפשר לספור, כמו \"time\".", "\"I want to make sure my message is clear\" = אני רוצה לוודא שההודעה ברורה. \"Please tell me if something is not clear\" = נא לומר לי אם משהו לא ברור. שאלה חוזרת בנימוס.", "\"Has no problem with\" = אין לו בעיה עם. אחרי \"problem with\" בא שם עצם או ing. \"Has no\" הוא ביטוי שלילי טבעי יותר מ-\"doesn't have\".", "\"We are happy to confirm the meeting\" = אנחנו שמחים לאשר את הפגישה. \"We look forward to working together\" = אנחנו מצפים לעבוד יחד. אחרי \"look forward to\" בא ing.", "\"Let me know if you would prefer\" = תגיד לי אם תעדיף. \"Would prefer\" + שם עצם או \"to\", ומאפשר לשאול בנימוס על העדפה.", "\"I hope this answers your question\" = אני מקווה שזה עונה על השאלה שלך. \"If not, I can explain more\" = אם לא, אוכל להסביר יותר. מבנה סיום מנומס למייל הסבר."],
  ["\"Let's get started\" = בואו נתחיל. זה ביטוי פתיחה נפוץ בישיבה, והוא מדבר בשם כולם (\"let's\").", "\"I suggest we go through\" = אני מציע שנעבור על. אחרי \"suggest\" בא ing (\"going\"), או \"we\" + פועל. \"In order\" = לפי הסדר.", "\"Who would like to give an update\" = מי רוצה לתת עדכון. \"Would like to\" מנומס יותר מ-\"want to\" כשמזמינים מישהו לדבר.", "\"We have about ten minutes left\" = נשארו לנו בערך עשר דקות. \"Left\" אחרי השם מתאר מה שנשאר. \"Keep it short\" = לקצר.", "\"I agree with you on that point\" = מסכים איתך בנקודה הזאת. \"Agree with\" + אדם, ו-\"on\" + נושא.", "\"Could you repeat the last question\" = אפשר לחזור על השאלה האחרונה. זו בקשה מנומסת, שבה \"could\" מחליף \"can\" כדי להיות מכבד יותר.", "\"We have a problem with the schedule\" = יש לנו בעיה בלוח הזמנים. \"With\" אחרי \"problem\" מציין את התחום של הבעיה.", "\"Let's talk about this after the meeting\" = בוא נדבר על זה אחרי הישיבה. דרך מנומסת לדחות נושא שלא שייך לישיבה הנוכחית.", "\"Thanks for coming, and see you next week\" = תודה שהגעתם, ונתראה בשבוע הבא. זה סיום ישיבה חם וקצר, וה-\"see you\" הוא דרך טבעית לומר להתראות.", "\"Can someone take notes on\" = מישהו יכול לרשום. \"Take notes\" = לרשום סיכום. \"Action items\" = משימות לביצוע, מונח שגור בישיבות."],
  ["\"I'd like to present\" = הייתי רוצה להציג. \"Would like to\" מנומס. \"Our plan for the next quarter\" = התוכנית שלנו לרבעון הבא. \"Quarter\" = רבעון שנה.", "\"Let's check whether everyone understands\" = בוא נבדוק אם כולם מבינים. \"Whether\" = אם, כשמדובר בשאלה עם שתי אפשרויות. \"Before we continue\" = לפני שנמשיך.", "\"According to the data\" = לפי הנתונים. \"Went up by ten percent\" = עלה בעשרה אחוז. \"By\" מציין את גודל השינוי, ו-\"up\" מציין כיוון.", "\"I have a question about the budget\" = יש לי שאלה לגבי התקציב. \"About\" מציין את הנושא של השאלה. זה נשמע יותר מנומס מ-\"I want to talk about\".", "\"Will finish the first draft by the end of the month\" = יסיים את הטיוטה הראשונה עד סוף החודש. \"By\" מציין מועד אחרון, לא תקופה. \"Will\" לפעולה עתידית שמתוכננת.", "\"Could we postpone the final decision until the next meeting\" = אפשר לדחות את ההחלטה הסופית עד הישיבה הבאה. \"Postpone\" + שם עצם או ing, \"until\" מציין עד מתי.", "\"I think we should consider\" = אני חושב שכדאי לשקול. \"Should\" + פועל בלי \"to\". \"Consider\" + שם פועל (ing) או שם עצם, לא \"to consider\".", "\"Who is responsible for the launch\" = מי אחראי על ההשקה. \"Responsible for\" + שם עצם. באנגלית אחרי \"responsible\" בא \"for\", לא \"of\".", "\"Let's summarize the decisions\" = בוא נסכם את ההחלטות. \"Let's\" + פועל בלי \"to\". \"We made today\" = שקיבלנו היום, מתאר את ההחלטות שהתקבלו.", "\"I'm sorry, but I have to leave early\" = מצטער, אבל אני צריך לצאת מוקדם. \"Have to\" מציין הכרח, ו-\"early\" מתאר זמן שהוא לפני הרגיל."],
  ["\"I'd like to add an item to the agenda\" = הייתי רוצה להוסיף נושא לסדר היום. \"Agenda\" = סדר היום. \"About the glitch we found yesterday\" מתאר את הנושא.", "\"Before we continue, let's agree on the definitions\" = לפני שנמשיך, בוא נסכים על ההגדרות. \"Agree on\" + נושא: אנחנו מסכימים על משהו, לא \"agree the definitions\".", "תנאי מסוג 1: \"If we leave this task until the end, we'll probably miss\". אחרי \"if\" בא הווה (\"leave\"), וה-\"will\" בתוצאה. \"Probably\" מציין הסתברות.", "\"I'm not sure everyone is clear about\" = לא בטוח שכולם ברורים לגבי. \"Clear about\" = ברור לגבי משהו, כלומר מבין את הנושא.", "\"We'd welcome alternative proposals if anyone has them\" = נשמח להצעות חלופיות, אם למישהו יש. \"Would welcome\" = נשמח לקבל, צורה מנומסת מאוד להזמנה.", "\"The data show a positive trend\" = הנתונים מראים מגמה חיובית. \"Data\" הוא ברבים, לכן הפועל \"show\". \"Too small to draw firm conclusions\" = קטן מדי להסיק מסקנות.", "\"Let's focus on finding a solution rather than on who caused the problem\" = בוא נתמקד במציאת פתרון במקום במי גרם לבעיה. \"Rather than\" + ing, ו-\"focus on\" + ing.", "\"I suggest we break the project into smaller stages\" = אני מציע שנחלק את הפרויקט לשלבים קטנים יותר. \"Break into\" = לחלק ל-. \"So we can get early feedback\" = כדי לקבל משוב מוקדם.", "\"This decision will affect every department\" = ההחלטה הזאת תשפיע על כל מחלקה. \"Every\" + שם עצם ביחיד, לכן \"department\" בלי \"s\". \"Worth involving everyone\" = שווה לשתף את כולם.", "\"Let's set a clear time limit for this discussion\" = בוא נקבע מגבלת זמן ברורה לדיון. \"Set a time limit\" הוא הביטוי הנכון, לא \"make\"."],
  ["\"Before we discuss the plan, I want to make sure\" = לפני שנדון בתוכנית, אני רוצה לוודא. \"Up to date\" = עדכני, ביטוי מילולי ולא תחליף ל-\"current\". \"Behind it\" = שמאחוריה.", "\"There seems to be a gap between what was presented and what is happening\" = נראה שיש פער בין מה שהוצג לבין מה שקורה. \"Seems to be\" מציין הערכה שלא בטוחה. \"On the ground\" = בשטח, בפועל.", "\"We need to decide whether to stay on the current course or change direction\" = אנחנו צריכים להחליט אם להישאר במסלול הנוכחי או לשנות כיוון. \"Whether... or\" = אם... או, מבנה שאלה עם שתי אפשרויות.", "\"Given the budget pressure, we need an approach that balances cost and quality\" = בהתחשב בלחץ התקציבי, אנחנו צריכים גישה שמאזנת בין עלות לאיכות. \"Given\" = לאור, ו-\"balances\" מתאר איזון בין שני דברים.", "תנאי מסוג 1: \"If we can identify the main cause, we can fix the whole process\". \"If\" + הווה, ו-\"can\" מציין יכולת שתתאפשר אם התנאי מתקיים.", "\"I suggest we assign one person to track\" = אני מציע שנמנה אדם אחד שיעקוב. \"Assign X to Y\" = למנות אדם ל-. \"Track\" = לעקוב, מונח עסקי נפוץ.", "\"It seems we agree, but we should make sure\" = נראה שאנחנו מסכימים, אבל כדאי לוודא. \"Happy with\" + ביטוי: מרוצה מהניסוח. \"Should\" מציין המלצה.", "\"I'd like us to address the concerns that were raised\" = אני רוצה שנתייחס לחששות שהועלו. \"Address\" = להתייחס ל-. \"Were raised\" = סבילה, לא חשוב מי העלה. \"Before we vote\" = לפני ההצבעה.", "\"This meeting was productive, but a few open issues still need follow-up\" = הישיבה הייתה פרודוקטיבית, אבל נותרו כמה נושאים פתוחים שדורשים מעקב. \"Still need\" = עדיין צריכים.", "\"If we keep this pace, we'll finish before the deadline\" = אם נשמור על הקצב הזה, נסיים לפני הדדליין. תנאי מסוג 1 עם הווה בתנאי ו-\"will\" בתוצאה. \"Free up resources\" = לשחרר משאבים."],
  ["\"The alternative looks attractive, but it has legal risks\" = החלופה נראית מפתה, אבל יש בה סיכונים משפטיים. \"Looks attractive\" = נראה מפתה. \"We haven't checked fully\" = לא בדקנו עד הסוף, Present Perfect כי הבדיקה לא הושלמה.", "\"I want to be clear: I'm not against the idea, only against how it's presented\" = אני רוצה להיות ברור: אני לא נגד הרעיון, רק נגד הדרך שבה הוא מוצג. הנקודותיים לפני ההסבר. \"Against\" = נגד.", "\"We assumed we all saw the situation the same way\" = הנחנו שכולנו רואים את המצב באותו אופן. \"Assumed\" בעבר כי ההנחה הייתה בעבר. \"The same way\" = באותו אופן.", "\"Before we approve the budget, we need to check whether the plan meets the new regulations\" = לפני שנאשר את התקציב, צריך לבדוק אם התוכנית עומדת בתקנות. \"Meets\" = עומדת בדרישה. \"Before\" + הווה.", "\"Today's meeting is not for a final decision\" = הישיבה היום אינה להחלטה סופית. \"Is not for\" מציין מטרה. \"We need to list the points that need senior approval\" = נדרש לרשום נקודות שדורשות אישור בכירים.", "\"If we keep postponing this discussion, we may lose the opportunity altogether\" = אם נמשיך לדחות את הדיון, אולי נאבד את ההזדמנות לגמרי. תנאי מסוג 1 עם \"may\" שמציין אפשרות. \"Altogether\" = לגמרי.", "\"The data seem selective\" = הנתונים נראים סלקטיביים, כלומר נבחרו חלקית. \"Not convinced by the explanation\" = לא משוכנע מההסבר. \"Convinced by\" = משוכנע על ידי.", "\"People here have different points of view, which affects their conclusions\" = לאנשים כאן יש נקודות מבט שונות, וזה משפיע על המסקנות שלהם. \"Which\" מתייחס לכל המשפט הקודם.", "\"If we don't agree on what success means, we won't be able to measure it\" = אם לא נסכים מה נחשב הצלחה, לא נוכל למדוד אותה. תנאי מסוג 1 עם \"won't be able to\" = לא נוכל.", "\"Let's set a date to come back to this topic\" = בוא נקבע מועד לחזור לנושא. \"Come back to\" = לחזור ל-. \"And make a decision\" = ולקבל החלטה, פועל מקביל ל-\"come\"."],
  ["\"Can we check that everyone has the latest version\" = אפשר לבדוק שלכולם יש את הגרסה האחרונה. \"Latest version\" = הגרסה העדכנית ביותר. \"Before we start\" = לפני שנתחיל.", "\"Let me sum up the main points\" = תנו לי לסכם את הנקודות המרכזיות. \"Sum up\" = לסכם, ביטוי פועל שפותח סיכום. \"And then we can discuss them\" = ואז נוכל לדון בהן.", "\"I'd like to hear from people who haven't spoken yet\" = הייתי רוצה לשמוע מאנשים שעוד לא דיברו. \"Hear from\" = לשמוע מפי, ו-\"yet\" עם Present Perfect מציין שהם עוד לא דיברו.", "\"We keep talking about the same thing\" = אנחנו ממשיכים לדבר על אותו דבר. \"Keep + ing\" = להמשיך לעשות. \"So let's make a decision\" = לכן בוא נחליט.", "\"Would someone like to lead the follow-up\" = מישהו רוצה להוביל את המעקב. \"Would someone like to\" מציג בקשה כללית, בלי להצביע על אדם.", "\"That's a good point, but I'd like to see some data first\" = זו נקודה טובה, אבל הייתי רוצה לראות נתונים קודם. \"First\" בסוף המשפט מציין סדר פעולות.", "\"Let's leave that question for now and come back to it later\" = בוא נשאיר את השאלה לעת עתה ונחזור אליה מאוחר יותר. \"For now\" = לעת עתה, \"later\" = מאוחר יותר.", "\"I'm happy to take the first draft\" = אני שמח לקחת את הטיוטה הראשונה. \"Happy to\" + פועל, מציע עזרה בנימוס.", "\"We should set a deadline for each task, so nothing gets forgotten\" = כדאי לקבוע דדליין לכל משימה, כדי שלא ישכח שום דבר. \"Nothing gets forgotten\" = שום דבר לא נשכח, סביל עם שלילה.", "\"Before we wrap up, does anyone have anything else to add\" = לפני שנסיים, יש למישהו עוד משהו להוסיף? \"Wrap up\" = לסיים, ביטוי מילולי מתאים לסיום ישיבה."],
  ["\"Thank you all for your ideas\" = תודה לכולם על הרעיונות. \"Today's decision will shape the next quarter\" = ההחלטה של היום תעצב את הרבעון הבא. \"Shape\" = לעצב, פועל שמתאר השפעה ארוכה.", "\"I'll send the minutes by tomorrow\" = אשלח את הסיכום עד מחר. \"Minutes\" = פרוטוקול ישיבה, מונח נפוץ. \"By\" מציין מועד אחרון, \"tomorrow\" הוא מועד.", "\"Given what we discussed, I think the best approach is to launch in stages\" = בהתחשב במה שדיברנו, הגישה הטובה ביותר היא להשיק בשלבים. \"Given\" מציג בסיס לטענה. \"In stages\" = בשלבים.", "\"Let's make sure each team knows its tasks before we leave the room\" = בוא נוודא שכל צוות יודע את המשימות שלו לפני שיוצאים מהחדר. \"Each team\" + פועל ביחיד (\"knows\"), ו-\"its\" כי \"team\" הוא יחידה.", "\"I'd like to look at the timeline again when we have the test results\" = הייתי רוצה לבדוק שוב את לוח הזמנים כשיהיו תוצאות הבדיקה. \"When we have\" = כשיהיו לנו, Present Simple לאחר \"when\" בתנאי עתידי.", "\"Our position has changed since last week\" = העמדה שלנו השתנתה מאז השבוע שעבר. \"Since\" + זמן מסוים, ו-Present Perfect (\"has changed\") כי השינוי משפיע עכשיו.", "\"Please tell me any concerns directly after the meeting, not in the group chat\" = נא לספר לי על כל הסתייגות ישירות אחרי הישיבה, ולא בקבוצת הצ'אט. \"Directly\" = ישירות.", "\"I'm glad we agreed, even though it took longer than I expected\" = שמח שהסכמנו, למרות שזה לקח יותר זמן ממה שציפיתי. \"Even though\" = למרות ש-, אחריו משפט מלא.", "\"Let's meet again on Friday to check our progress\" = בוא נתכנס שוב ביום שישי כדי לבדוק את ההתקדמות. \"On Friday\" עם יום, ו-\"to check\" מציין מטרה.", "\"The main point from today is that each decision needs one owner\" = הנקודה המרכזית מהיום היא שלכל החלטה צריך בעל אחד. \"Each decision needs\" ביחיד, כי \"each\" + שם יחיד. \"Owner\" = בעל תפקיד."],
  ["\"Hello, how can I help you today?\" = שלום, איך אוכל לעזור לך היום? הפתיחה הסטנדרטית בשירות לקוחות. \"Can I help\" מתאים לתפקיד נותן שירות.", "\"I understand that there's a problem\" = אני מבין שיש בעיה. \"Understand that\" + משפט, פותח הכרה בבעיה לפני פתרון.", "\"Could I have your order number, please?\" = אפשר לקבל את מספר ההזמנה שלך? \"Could I have\" מנומס יותר מ-\"can you give me\", ו-\"please\" בסוף מוסיף נימוס.", "\"I'm sorry for the inconvenience this has caused you\" = מצטער על אי הנוחות שגרמה לך. \"Caused you\" מציין מי סבל מהבעיה, והמשפט מתאר את הנזק בלי להאשים.", "\"Let me check that for you right now\" = תן לי לבדוק את זה עבורך עכשיו. \"Let me\" + פועל, ו-\"right now\" מציין מיידיות.", "\"The refund should appear in your account\" = ההחזר אמור להופיע בחשבון. \"Should\" מציין ציפייה סבירה, לא ודאות. \"Within three business days\" = תוך שלושה ימי עסקים.", "\"Is there anything else I can help you with\" = יש עוד משהו שאוכל לעזור לך בו? המילה \"with\" נשארת בסוף המשפט: \"help someone with something\".", "\"Thank you for contacting us\" = תודה שפנית אלינו. אחרי \"for\" בא ing (\"contacting\"), ולא \"to contact\". זה ביטוי סיום נפוץ בשירות.", "\"The item you asked about is still in stock\" = המוצר שעליו שאלת עדיין במלאי. \"In stock\" = במלאי, ביטוי קבוע בלי \"the\" ובלי \"a\". \"Asked about\" מתאר את השאלה.", "\"I can offer you a similar product if you'd like\" = אני יכול להציע לך מוצר דומה, אם תרצה. \"If you'd like\" הוא סיום מנומס שלא לוחץ."],
  ["\"Thank you for your patience while I looked into this\" = תודה על הסבלנות בזמן שבדקתי את העניין. \"Look into\" = לבדוק, לחקור. \"While\" + Past Simple לפעולה שהתרחשה במקביל.", "\"I can send you a link to reset your password\" = אני יכול לשלוח לך קישור לאיפוס הסיסמה. \"To reset\" מציין מטרה: הקישור לשם איפוס.", "\"The issue has been fixed, and the service should be working again tomorrow\" = התקלה תוקנה, והשירות אמור לחזור לפעול מחר. \"Has been fixed\" = צורה סבילה לתיאור פעולה שנעשתה.", "\"Would you like me to transfer you to the right department?\" = האם תרצה שאעביר אותך למחלקה המתאימה? \"Would you like me to\" + פועל הוא הצעה מנומסת.", "\"I can see that your order was shipped yesterday\" = אני רואה שההזמנה נשלחה אתמול. \"Was shipped\" הוא צורה סבילה, כי השאלה היא מה נעשה עם ההזמנה, לא מי שלח.", "\"We would be happy to help you exchange the product\" = נשמח לעזור לך להחליף את המוצר. \"Help you\" + פועל בלי \"to\" (אחרי \"help\" + אדם, אפשר גם \"to\", אבל בלי \"to\" טבעי יותר).", "\"Thank you for the feedback; it helps us improve our service\" = תודה על המשוב, הוא עוזר לנו לשפר את השירות. נקודה-פסיק מחברת שני משפטים קשורים.", "\"I understand your frustration, and I want to solve this for you\" = אני מבין את התסכול שלך, ואני רוצה לפתור את זה עבורך. \"Frustration\" = תסכול, שם עצם. \"For you\" מציין למי הפתרון מיועד.", "\"Do you have any other details that would help us find the problem?\" = יש לך פרטים נוספים שיעזרו לנו למצוא את הבעיה? \"Would help\" מציין פעולה תיאורטית בהקשר של עזרה.", "\"The invoice will be sent to your email in a few minutes\" = החשבונית תישלח לאימייל שלך בעוד כמה דקות. סביל לעתיד: \"will be sent\". \"In a few minutes\" = בעוד כמה דקות."],
  ["\"I understand the situation is frustrating\" = אני מבין שהמצב מתסכל. \"Frustrating\" (פועל ing) מתאר את המצב, ו-\"frustrated\" מתאר את האדם.", "\"Unfortunately, our policy doesn't allow refunds after thirty days\" = לצערי, המדיניות לא מאפשרת החזרים אחרי שלושים יום. \"Unfortunately\" בתחילת סירוב מרכך את המסר.", "\"If you'd like, I can arrange a follow-up call\" = אם תרצה, אוכל לקבוע שיחת המשך. \"If you'd like\" הוא דרך מנומסת להציע בלי לכפות. \"Arrange\" = לתאם, לקבוע.", "\"I see this problem has come up before\" = אני רואה שהבעיה הזאת כבר עלתה בעבר. \"Has come up\" = עלתה, Present Perfect כי זה משפיע על ההחלטה עכשיו. \"Escalating\" = מעביר לגורם בכיר יותר.", "\"From what you described, the product arrived damaged, so we'll send you a replacement\" = ממה שתיארת, המוצר הגיע פגום, לכן נשלח לך חלופה. \"From what you described\" = לפי מה שתיארת, פותח משפט על הבנה.", "\"We can offer you a discount on your next order to make up for the problem\" = נוכל להציע לך הנחה על ההזמנה הבאה כדי לפצות על הבעיה. \"To make up for\" = לפצות על.", "\"I'm sorry, but I don't have access to those details\" = מצטער, אבל אין לי גישה לפרטים האלה. \"Access to\" = גישה ל-. \"So I'll pass your question to the right team\" = לכן אעביר את השאלה לצוות הנכון.", "\"To resolve this, I first need to verify your identity\" = כדי לפתור את זה, אני קודם צריך לאמת את זהותך. \"To resolve\" מציין מטרה בתחילת המשפט. \"First\" = קודם.", "\"We'll look into this and get back to you within twenty-four hours\" = נבדוק את זה ונחזור אליך תוך עשרים וארבע שעות. \"Get back to you\" = לחזור אליך, ביטוי קבוע בשירות.", "\"I'd recommend trying the updated version\" = הייתי ממליץ לנסות את הגרסה המעודכנת. אחרי \"recommend\" בא ing (\"trying\"), לא \"to try\". \"Which fixes most of the reported issues\" = שפותרת רוב הבעיות שדווחו."],
  ["\"I understand our decision isn't what you wanted\" = אני מבין שההחלטה שלנו אינה מה שרצית. \"What you wanted\" = מה שרצית, נושא מלא בתוך המשפט.", "\"Unfortunately, the error came from a system that wasn't updated in time\" = לצערנו, הטעות נבעה ממערכת שלא עודכנה בזמן. \"Came from\" = נבעה מ-. \"Wasn't updated\" צורה סבילה לשלילה.", "\"I want to make sure my explanation was clear\" = אני רוצה לוודא שההסבר שלי היה ברור. \"Was\" בעבר, כי ההסבר כבר נאמר. \"I'll be glad to go through it again\" = אשמח לעבור עליו שוב.", "\"According to our policy, you can exchange the item within fourteen days\" = לפי המדיניות שלנו, אפשר להחליף את הפריט תוך ארבעה עשר ימים. \"Within\" = תוך, מציין גבול זמן.", "\"The problem you describe is complicated, so I'd suggest a video call\" = הבעיה שתיארת מסובכת, לכן הייתי מציע שיחת וידאו. \"I'd suggest\" + שם עצם (a video call), לא פועל.", "\"We know the delay affected your plans\" = אנחנו יודעים שהעיכוב פגע בתוכניות שלך. \"Affected\" בעבר כי הפגיעה כבר קרתה, ו-\"we're prepared to compensate\" מציג את ההתחייבות.", "\"If your request was denied, you can file an appeal\" = אם הבקשה נדחתה, אפשר להגיש ערעור. התנאי בעבר (\"was denied\") מציג מצב שייתכן שקרה, והתוצאה ב-\"can\" מציגה אפשרות אמיתית.", "\"Since the issue involves several departments, I've passed it to a manager\" = מכיוון שהנושא נוגע למספר מחלקות, העברתי אותו למנהל. \"I've passed\" = Present Perfect כי ההעברה הושלמה ומשפיעה עכשיו.", "\"I appreciate your patience, and I want to be sure the solution I offer really works for you\" = אני מעריך את הסבלנות שלך, ורוצה לוודא שהפתרון באמת מתאים לך. \"Really\" מדגיש את הכנות.", "\"Because of high call volume, the wait is longer than usual\" = בגלל עומס שיחות, ההמתנה ארוכה מהרגיל. \"Volume\" = כמות, ו-\"because of\" + שם עצם."],
  ["\"I understand your anger, but this policy is the same for every customer\" = אני מבין את הכעס, אבל המדיניות הזאת זהה לכל הלקוחות. \"Is the same for\" = זהה ל-, \"for every customer\" = לכל לקוח.", "\"We checked your complaint carefully, and we agree with you\" = בדקנו את התלונה שלך בקפידה, ואנחנו מסכימים איתך. \"Checked\" בעבר כי הבדיקה הסתיימה. \"Agree with you\" = מסכימים איתך.", "\"I don't want to promise what we can't do\" = אני לא רוצה להבטיח את מה שאיננו יכולים לעשות. \"Promise\" + מה שמובטח. \"Look at your options honestly\" = לבדוק את האפשרויות שלך בכנות.", "\"The problem is not the product, but the way it was used\" = הבעיה לא במוצר, אלא בדרך שבה הוא שימש. \"Was used\" סביל כי מדובר בשימוש, לא בבן אדם שהשתמש.", "\"We know this is not convenient for you, so your satisfaction comes first\" = אנחנו יודעים שזה לא נוח לך, לכן שביעות הרצון שלך קודמת. \"Comes first\" = קודם בסדר העדיפויות.", "\"If we can't find the cause of the error today, you'll get an update tomorrow morning\" = אם לא נמצא את סיבת השגיאה היום, תקבל עדכון מחר בבוקר. תנאי מסוג 1 עם \"can't\" בתנאי.", "\"On behalf of the company, I'm sorry for how this was handled\" = בשם החברה, אני מתנצל על איך שהעניין טופל. \"On behalf of\" = בשם. \"How this was handled\" = איך זה טופל, סביל.", "\"I can't approve your request as it is, but I can offer you something that covers most of the loss\" = אינני יכול לאשר את הבקשה כמו שהיא, אבל אציע משהו שמכסה את רוב ההפסד. \"Covers\" בלשון יחיד כי \"something\" הוא יחיד.", "\"If you want to continue through the official channel, I'll send all the details, so you won't need to explain again\" = אם תרצה להמשיך דרך הערוץ הרשמי, אשלח את כל הפרטים כך שלא תצטרך להסביר שוב. \"Won't need to\" = לא תצטרך.", "\"I understand the experience wasn't good. We want to improve so this doesn't happen to other customers\" = אני מבין שהחוויה לא הייתה טובה. אנחנו רוצים להשתפר כדי שזה לא יקרה ללקוחות אחרים. \"So this doesn't happen\" = כך שזה לא יקרה."],
  ["\"I've noted your concern in our system\" = רשמתי את הפנייה שלך במערכת. \"Noted\" = רשמתי, Present Perfect כי הפעולה הושלמה. \"A supervisor will look at it today\" = מנהל יבדוק את זה היום.", "\"Could you tell me step by step what happened?\" = אפשר לספר לי צעד אחר צעד מה קרה? \"Step by step\" = צעד אחר צעד, מבנה שמתאר סדר מדויק.", "\"We have more orders than usual right now, so answers may take longer\" = יש לנו יותר הזמנות מהרגיל כרגע, לכן התשובות עשויות לקחת יותר זמן. \"May\" מציין אפשרות. \"Than usual\" = מהרגיל.", "\"Please keep your receipt. We need it to handle the return\" = נא לשמור את הקבלה. אנחנו צריכים אותה כדי לטפל בהחזרה. \"Need it to\" + פועל מציין מטרה.", "\"I'd like to offer you a free upgrade, as a thank you for your patience\" = הייתי רוצה להציע לך שדרוג חינם, כתודה על הסבלנות. \"As a thank you\" = כתודה, ביטוי שמצדיק מתנה קטנה.", "\"That's a reasonable request, and I'll make sure it's handled first\" = זו בקשה סבירה, ואדאג שהיא תטופל קודם. \"Make sure\" + משפט, ו-\"handled\" סביל.", "\"Please contact us again if the problem comes back\" = נא לפנות אלינו שוב אם הבעיה תחזור. תנאי מסוג 1: \"if\" + הווה (\"comes back\") ו-\"please\" בתוצאה.", "\"We value you as a customer, and we want to fix this for you\" = אנחנו מעריכים אותך כלקוח, ורוצים לתקן את זה בשבילך. \"Value you as a customer\" = להעריך אותך ככזה.", "\"I can see in your account that you've been with us for several years\" = אני רואה בחשבון שלך שאתה איתנו כבר כמה שנים. Present Perfect Continuous (\"have been with\") מציין משך שנמשך עד היום.", "\"Thank you for your patience while we solve this together\" = תודה על הסבלנות בזמן שאנחנו פותרים את זה ביחד. \"While\" מתאר פעולה במקביל."],
  ["\"Thanks for telling us. This helped us fix a problem that affected many customers\" = תודה שסיפרת לנו. זה עזר לנו לתקן בעיה שפגעה בהרבה לקוחות. \"Helped us fix\" = עזר לנו לתקן, פועל בלי \"to\" אחרי \"helped us\".", "\"We wrote down your feedback and shared it with the product team\" = רשמנו את המשוב שלך ושיתפנו אותו עם צוות המוצר. שני פעלים בעבר (wrote, shared) שמתארים סדרה של פעולות שהסתיימו.", "\"If something is still unclear, reply to this message\" = אם משהו עדיין לא ברור, השב להודעה הזאת. תנאי מסוג 1 בצורה של הוראה (\"reply\"). \"Still unclear\" = עדיין לא ברור.", "\"We care about your satisfaction, so we'll call you when the replacement is shipped\" = אכפת לנו משביעות הרצון שלך, לכן נתקשר אליך כשהחלופה תישלח. \"When\" + הווה (\"is shipped\") לאירוע עתידי.", "\"The new policy will make returns much easier for customers in the future\" = המדיניות החדשה תקל מאוד על החזרות ללקוחות בעתיד. \"Make X easier\" = להקל על X. \"Much easier\" = הרבה יותר קל.", "\"Let me check the details of the replacement before I order it\" = תן לי לבדוק את הפרטים של החלופה לפני שאזמין אותה. \"Before I order\" + הווה, לא עתיד.", "\"We added a credit to your account. You should see it on your next statement\" = הוספנו זיכוי לחשבון שלך. אתה אמור לראות אותו בדף החשבון הבא. \"Should\" מציין ציפייה סבירה.", "\"Please tell me if the new arrangement works for you, or if you want another option\" = נא לספר לי אם ההסדר החדש מתאים לך, או אם אתה רוצה אפשרות אחרת. \"Works for you\" = מתאים לך. שני \"if\" במשפט קצר נשמעים טבעיים.", "\"I'm glad I could help, and I hope your next experience with us will be better\" = שמחתי לעזור, ואני מקווה שהחוויה הבאה שלך איתנו תהיה טובה יותר. \"I'm glad I could\" הוא סיום חם וטבעי בשירות.", "\"Thanks for your patience today. Have a great rest of your day\" = תודה על הסבלנות היום, ויום נעים לך. \"Have a great rest of your day\" הוא סיום שגור בשירות לקוחות, ו-\"rest\" כאן = שאר היום."],
  ["\"Thanks for meeting with us today\" = תודה שנפגשתם איתנו היום. \"I'd like to tell you about\" = הייתי רוצה לספר לכם על. פתיחה חמה ומנומסת לפגישת מכירה.", "\"Helps companies save time on daily reports\" = עוזרת לחברות לחסוך זמן בדוחות יומיים. אחרי \"helps\" + שם עצם, פועל בלי \"to\" במבנה הזה (\"help companies save\"). \"On\" מציין את התחום שבו החיסכון.", "\"Many of our clients have seen a clear improvement\" = הרבה מהלקוחות שלנו ראו שיפור ברור. Present Perfect (\"have seen\") מציין תוצאות שמשפיעות עכשיו. \"In their results\" = בתוצאות שלהם.", "\"Would you like to see a short demo\" = האם תרצו לראות הדגמה קצרה? \"Would you like to\" הזמנה מנומסת שלא לוחצת.", "\"Our price depends on the number of users\" = המחיר שלנו תלוי במספר המשתמשים. \"Depends on\" = תלוי ב-. \"The number of\" + שם עצם ברבים, אבל הפועל ביחיד (\"the number... depends\").", "\"We offer a free trial for thirty days\" = אנחנו מציעים ניסיון חינם למשך שלושים יום. \"Free trial\" = ניסיון חינם. \"For\" מציין משך.", "\"What is your biggest challenge right now?\" = מה האתגר הגדול ביותר שלכם כרגע? שאלה פתוחה שמעודדת את הלקוח לדבר על הצרכים שלו. \"Right now\" = עכשיו.", "\"I think our solution could fit your needs very well\" = אני חושב שהפתרון שלנו יכול להתאים מאוד לצרכים שלכם. \"Could\" מציין אפשרות, לא ודאות. \"Fit your needs\" = להתאים לצרכים.", "\"Our support team is available twenty-four hours a day\" = צוות התמיכה שלנו זמין עשרים וארבע שעות ביממה. \"Available\" = זמין, בלי פועל עזר. \"A day\" = ליום, כלומר בכל יום.", "\"Let's set up a follow-up call next week\" = בוא נקבע שיחת המשך לשבוע הבא. \"Set up\" = לקבוע, ו-\"follow-up\" = מעקב אחרי הפגישה."],
  ["\"Your competitors are already using our product, and they're seeing good results\" = המתחרים שלכם כבר משתמשים במוצר שלנו, ורואים תוצאות טובות. \"Already\" עם Present Perfect או Present Continuous. \"They're seeing\" = רואים כרגע.", "\"We can tailor the package to match your budget and your goals\" = אנחנו יכולים להתאים את החבילה לתקציב ולמטרות שלכם. \"Tailor\" = להתאים בצורה מדויקת. \"Match\" = להתאים ל-.", "תנאי מסוג 1: \"If you sign this month, we can offer a discount on the first year\". אחרי \"if\" בא הווה (\"sign\"), וה-\"can\" בתוצאה מציין אפשרות שמתאפשרת.", "\"What would make this decision easier for you?\" = מה היה מקל עליכם לקבל את ההחלטה? \"Would make\" = שאלה היפותטית שמזמינה את הלקוח לחשוב על הצרכים שלו.", "\"We're confident that the return on investment will be clear within six months\" = אנחנו בטוחים שהתשואה על ההשקעה תהיה ברורה תוך שישה חודשים. \"Within\" = תוך, מציין גבול זמן.", "\"Could you tell me who else will be involved in the decision?\" = אפשר לספר לי מי נוסף ייכלל בהחלטה? \"Who else\" = מי עוד. בשאלה עקיפה בא סדר מילים של משפט רגיל.", "\"I'd like to understand what your current process looks like\" = הייתי רוצה להבין איך נראה התהליך הנוכחי שלכם. \"What X looks like\" = איך נראה X. שאלה שמביאה את הלקוח לדבר על עצמו.", "\"We've helped similar companies cut their costs by almost a fifth\" = עזרנו לחברות דומות להוריד את העלויות שלהן בכמעט חמישית. \"Help X + פועל\" בלי \"to\". \"A fifth\" = חמישית, שבר של שליש או רבע.", "\"Let me send you a case study that shows the results in detail\" = תנו לי לשלוח לכם מקרה בוחן שמראה את התוצאות בפירוט. \"A case study\" = מקרה בוחן. \"That shows\" משתמש ב-\"that\" כמשפט יחסי לדבר.", "\"Our team will handle the setup, so you won't need to do much work\" = הצוות שלנו יטפל בהקמה, כך שלא תצטרכו לעשות הרבה עבודה. \"Won't need to\" = לא יהיה צורך ל-. \"Much work\" עם שם עצם שאי אפשר לספור."],
  ["\"We understand your concern about the price, but the value goes well beyond the initial cost\" = אנחנו מבינים את החשש מהמחיר, אבל הערך חורג הרבה מעבר לעלות הראשונית. \"Goes beyond\" = חורג מ-. \"Well beyond\" = הרבה מעבר.", "\"If we lower the price, we'd need to reduce the level of support, and I don't think that would be good for you\" = אם נוריד את המחיר, נצטרך לצמצם את רמת התמיכה, ואני לא חושב שזה יהיה טוב לכם. תנאי מסוג 2: \"if\" + Past Simple (\"lower\") ו-\"would\" בתוצאה, כי מדובר בתרחיש היפותטי.", "\"Could you share what budget range you had in mind for this project?\" = אפשר לשתף איזה טווח תקציב חשבתם עליו לפרויקט? \"Had in mind\" = חשבתם, במשמעות של \"היה לכם בראש\".", "\"We'd like to find a middle ground that works for both sides\" = נשמח למצוא פשרה שעובדת לשני הצדדים. \"Middle ground\" = פשרה, ביטוי קבוע. \"Works for\" = מתאים ל-.", "\"I think there's room to adjust the terms if we commit to a longer agreement\" = אני חושב שיש מקום להתאים את התנאים אם נתחייב להסכם ארוך יותר. \"Room to\" + פועל = מרחב ל-. תנאי מסוג 1 עם \"commit\" בהווה.", "\"Before we discuss the price, I want to make sure we agree on the scope\" = לפני שנדון במחיר, אני רוצה לוודא שאנחנו מסכימים על היקף העבודה. \"Before\" + הווה, ו-\"make sure\" + משפט.", "\"We're not in a position to offer a discount on the setup fee, but we can waive the training costs\" = איננו במצב להציע הנחה על דמי ההקמה, אבל נוכל לוותר על עלויות ההדרכה. \"In a position to\" = במצב ל-. \"Waive\" = לוותר על, מונח משפטי ועסקי.", "תנאי מסוג 1: \"If you can give us a commitment by Friday, we can hold this price for another month\". \"Commitment\" = התחייבות, \"hold a price\" = לשמור על מחיר.", "\"We'd prefer not to rush into a decision, so take the time you need\" = נעדיף לא למהר להחלטה, לכן קחו את הזמן שאתם צריכים. \"Prefer not to\" = מעדיף לא ל-. \"Take the time you need\" = קחו את הזמן שנדרש לכם.", "\"Let's look at the numbers together and see where the savings would come from\" = בוא נסתכל על המספרים ביחד ונראה מאיפה החיסכון יבוא. \"Where\" בשאלה עקיפה משתמש בסדר מילים של משפט רגיל."],
  ["\"Your demand for a longer warranty is reasonable, but it would change the deal a lot\" = הדרישה שלכם לאחריות ארוכה יותר סבירה, אבל היא תשנה הרבה את העסקה. \"Would change\" = תשנה, תנאי מסוג 2 עם \"would\" בתוצאה.", "\"We can meet you halfway by extending the warranty\" = נוכל לבוא לקראתכם בחצי הדרך על ידי הארכת האחריות. \"Meet halfway\" = להגיע לפשרה. \"By\" + ing מציין איך.", "\"I'd rather be honest about what we can and can't deliver than promise something we can't keep\" = עדיף לי להיות כן לגבי מה שנוכל ולא נוכל לספק, מאשר להבטיח משהו שלא נוכל לקיים. \"I'd rather X than Y\" = עדיף לי X על פני Y. \"Can and can't\" = מה שנוכל ומה שלא.", "\"Our position is that quality comes first, so we won't compromise on the testing phase\" = העמדה שלנו היא שהאיכות קודמת, לכן לא נתפשר על שלב הבדיקות. \"Comes first\" = קודם בסדר העדיפויות. \"Compromise on\" = להתפשר על.", "\"If you're comparing us with other vendors, I'd encourage you to look at the total cost of ownership\" = אם אתם משווים אותנו לספקים אחרים, הייתי מעודד אתכם לבחון את העלות הכוללת לאורך הבעלות. \"Encourage you to\" + פועל, מציע בלי ללחוץ. \"Total cost of ownership\" = עלות הבעלות הכוללת.", "\"We're willing to consider a phased approach, starting with a smaller pilot\" = אנחנו מוכנים לשקול גישה מדורגת, שמתחילה בפיילוט קטן יותר. \"Willing to consider\" = מוכנים לשקול. \"Phased\" = מדורג, בשלבים.", "\"The concessions we've offered so far are already substantial, and we need something in return\" = הוויתורים שהצענו עד עכשיו כבר משמעותיים, ואנחנו צריכים משהו בתמורה. \"Concessions\" = ויתורים. \"In return\" = בתמורה.", "\"Let me clarify what we mean by 'implementation'\" = תנו לי להבהיר מה אנחנו מתכוונים ל'הטמעה'. \"What we mean by\" = מה שאנחנו מתכוונים אליו כש... \"Clarify\" = להבהיר, בזמן הווה כי זו הפעולה שמתרחשת עכשיו.", "\"I can't commit to that timeline without checking with our engineering team first\" = איני יכול להתחייב ללוח הזמנים הזה בלי לבדוק קודם עם צוות ההנדסה. \"Commit to\" + שם עצם. \"Without\" + ing.", "\"Would you be open to a shorter contract with an option to renew?\" = האם תהיו פתוחים לחוזה קצר יותר עם אפשרות לחידוש? \"Open to\" + שם עצם או ing. \"Option to renew\" = אופציה לחדש."],
  ["\"Our proposal shows the full value we offer, and I'd be surprised if others matched our quality\" = ההצעה שלנו מראה את מלוא הערך שאנחנו מציעים, ואופתע אם אחרים יתאימו לאיכות שלנו. \"I'd be surprised if\" = אופתע אם, תנאי מסוג 2 עם \"would\" בתוצאה.", "\"We know you have other options, but we believe a long-term partnership is most important\" = אנחנו יודעים שיש לכם אפשרויות אחרות, אבל אנחנו מאמינים שהשותפות לטווח ארוך חשובה ביותר. \"Most important\" = החשוב ביותר, בלי \"the\" כשמדברים באופן כללי.", "\"Given what you described, a lower price would mean less quality\" = לפי מה שתיארתם, מחיר נמוך יותר יאומר פחות איכות. \"Would mean\" = יהיה פירושו, תנאי מסוג 2. \"Given\" = לפי, בהתחשב ב-.", "\"Let's split the difference on the setup fee, and check the scope again in a month\" = בוא נחלק את ההפרש בדמי ההקמה, ונבדוק שוב את ההיקף בעוד חודש. \"Split the difference\" = לחלק את ההפרש, ביטוי פשרה קבוע.", "\"We listened to your feedback, and our new offer answers your points\" = הקשבנו למשוב שלכם, וההצעה החדשה שלנו עונה על הנקודות שהעליתם. \"Answers\" = עונה, פועל שמקבל את הנקודות כמושא ישיר.", "\"Before we continue, I need to know if the decision is yours or your board's\" = לפני שנמשיך, אני צריך לדעת אם ההחלטה שלכם או של הדירקטוריון. \"Yours\" ו-\"board's\" = מילות קניין שמחליפות את השם.", "\"Let's be realistic. The timeline is tight, so we need to decide what to deliver first\" = בואו נהיה ריאליים. לוח הזמנים צפוף, לכן צריך להחליט מה מספקים קודם. \"Deliver\" = לספק, ו-\"what to deliver\" = מה לספק.", "\"The discount you ask for would become a precedent, and we can't offer it to other clients\" = ההנחה שאתם מבקשים תהפוך לתקדים, ואנחנו לא יכולים להציע אותה ללקוחות אחרים. \"Would become\" = תהפוך, תנאי מסוג 2 לתוצאה היפותטית.", "\"We are ready to stop the talks if we can't find terms that are fair to both sides\" = אנחנו מוכנים להפסיק את המשא ומתן אם לא נמצא תנאים הוגנים לשני הצדדים. \"Ready to\" = מוכנים ל-. \"Fair to\" = הוגן ל-.", "\"Let's stop for a moment and check that we are talking about the same numbers\" = בוא נעצור לרגע ונבדוק שאנחנו מדברים על אותם מספרים. \"For a moment\" = לרגע. \"Check that\" + משפט, ו-\"same numbers\" = אותם מספרים."],
  ["\"We read your counteroffer. The main problem seems to be the delivery schedule\" = קראנו את ההצעה הנגדית שלכם. נראה שהבעיה העיקרית היא לוח האספקה. \"Counteroffer\" = הצעה נגדית, מונח משא ומתן.", "תנאי מסוג 1: \"If we agree on the delivery dates, I think we can close the deal this quarter\". \"Close the deal\" = לסגור עסקה. \"This quarter\" = ברבעון הזה.", "\"We can change the payment terms, as long as the order size stays the same\" = נוכל לשנות את תנאי התשלום, בתנאי שגודל ההזמנה יישאר אותו דבר. \"As long as\" = בתנאי ש-, מדגיש תנאי ברור.", "\"Our legal team needs a few days to read the new terms before we sign\" = הצוות המשפטי שלנו צריך כמה ימים לקרוא את התנאים החדשים לפני החתימה. \"Before we sign\" = לפני שנחתום, הווה אחרי \"before\".", "\"I want to be honest: we can't give every client the same discount\" = אני רוצה להיות כן: איננו יכולים לתת לכל לקוח את אותה הנחה. \"Every client\" + שם עצם ביחיד. \"The same discount\" = אותה הנחה.", "\"Would an exit clause after the first year help you?\" = האם סעיף יציאה אחרי השנה הראשונה יעזור לכם? \"Exit clause\" = סעיף יציאה מהחוזה. שאלה היפותטית שמציעה פתרון.", "\"We are sure the product will show its value after a couple of months of use\" = אנחנו בטוחים שהמוצר יוכיח את ערכו אחרי כמה חודשי שימוש. \"A couple of\" = כמה, ביטוי לא מדויק למספר קטן אבל נפוץ בדיבור.", "תנאי מסוג 1: \"If you are happy with these terms, I'll prepare the final agreement this afternoon\". \"Happy with\" = מרוצה מ-. \"This afternoon\" = אחר הצהריים של היום.", "\"That's a fair counteroffer, and I think we can meet in the middle\" = זו הצעה נגדית הוגנת, ואני חושב שנוכל להיפגש באמצע. \"Meet in the middle\" = לבוא לקראת הדדית, ביטוי פשרה.", "\"Let's write our agreement down, so both teams know what was decided\" = בוא נכתוב את ההסכמה שלנו, כדי ששני הצוותים ידעו מה הוחלט. \"Write down\" = לרשום. \"What was decided\" = מה שהוחלט, מבנה סביל."],
  ["\"Thank you for being open during this negotiation\" = תודה שהיית פתוח לאורך המשא ומתן. \"For being open\" = על כך שהיית פתוח, אחרי \"for\" בא ing. \"It made reaching a fair deal much easier\" = זה הקל מאוד להגיע לעסקה הוגנת.", "\"We look forward to a long relationship, and we'll make sure the start goes smoothly\" = אנחנו מצפים ליחסים ארוכים, ונדאג שההתחלה תהיה חלקה. \"Look forward to\" + שם עצם, לא \"to be\". \"Goes smoothly\" = מתקדם בצורה חלקה.", "\"Next, our team will schedule the kickoff meeting and send you the project plan\" = בשלב הבא, הצוות שלנו יקבע את פגישת הפתיחה וישלח לכם את תוכנית הפרויקט. \"Kickoff meeting\" = פגישת פתיחה.", "\"I believe we built this deal in a way that protects both companies\" = אני מאמין שבנינו את העסקה בדרך שמגינה על שתי החברות. \"In a way that\" = בדרך ש-. \"Protects\" = מגן על.", "\"If the results are not what we expect after the trial, we'll review the agreement together\" = אם התוצאות לא יהיו כמו שציפינו אחרי הניסיון, נבחן את ההסכם ביחד. תנאי מסוג 1 עם \"are\" בהווה כי הזמן הוא עתידי בתנאי.", "\"Let's schedule a review in three months to see how the partnership is going\" = בוא נקבע סקירה בעוד שלושה חודשים כדי לראות איך השותפות מתקדמת. \"In three months\" = בעוד שלושה חודשים, מציין נקודת זמן בעתיד.", "\"Please tell me if you need anything else before we start\" = נא לספר לי אם אתם צריכים עוד משהו לפני שנתחיל. \"Before we start\" + הווה.", "\"We value your business, and we are proud to work with a company that cares about quality\" = אנחנו מעריכים את העסקה איתכם, וגאים לעבוד עם חברה שאכפת לה מאיכות. \"Cares about\" = אכפת לו מ-. \"Proud to\" + פועל.", "\"The next thing I'll do is send you a summary\" = הדבר הבא שאעשה הוא לשלוח לכם סיכום. מבנה חיתוך (cleft): \"the next thing... is\" + פועל בלי \"to\", ולכן \"send\".", "\"This agreement is good for both sides, and it sets us up well for the year ahead\" = ההסכם הזה טוב לשני הצדדים, והוא מכין אותנו היטב לשנה הקרובה. \"Sets us up\" = מכין אותנו. \"The year ahead\" = השנה שלפנינו."],
  ["\"Good morning, and thank you all for being here\" = בוקר טוב, ותודה לכולם שאתם כאן. \"Thank you all for being here\" = ביטוי פתיחה נפוץ למצגת.", "\"Today I'm going to talk about our results from last year\" = היום אני הולך לדבר על התוצאות שלנו מהשנה שעברה. \"Going to\" מתאר תוכנית קרובה. \"From last year\" = מהשנה שעברה.", "\"My presentation has three main parts\" = למצגת שלי יש שלושה חלקים עיקריים. \"Has\" בלשון יחיד כי \"presentation\" הוא יחיד. זה נותן מפה לקהל.", "\"Let's start with a quick overview of the market\" = בוא נתחיל בסקירה קצרה של השוק. \"Overview\" = סקירה כללית, מונח מצגות נפוץ.", "\"As you can see on this slide, sales increased steadily\" = כפי שאתם רואים בשקף הזה, המכירות עלו בקצב יציב. \"Increased steadily\" = עלו בקצב יציב, תיאור של מגמה.", "\"This chart shows the number of new customers each month\" = הגרף הזה מראה את מספר הלקוחות החדשים בכל חודש. \"The number of\" + שם עצם ברבים, אבל הפועל \"shows\" ביחיד כי \"the number\" הוא הנושא.", "\"Please feel free to ask questions at any time\" = אתם מוזמנים לשאול שאלות בכל רגע. \"Feel free to\" = אתם מוזמנים ל-, מזמין בלי לחץ. \"At any time\" = בכל זמן.", "\"I'll come back to that point later in the presentation\" = אחזור לנקודה הזאת בהמשך המצגת. \"Come back to\" = לחזור ל-. \"Later in\" = בהמשך.", "\"To sum up, our growth was driven by three things\" = לסיכום, הצמיחה שלנו נבעה משלושה דברים. \"Was driven by\" = נבעה מ-, מבנה סביל שמציין סיבה.", "\"Thank you, and I'm happy to take your questions now\" = תודה, ואשמח לענות על שאלותיכם עכשיו. \"Take questions\" = לענות על שאלות. \"Now\" סוגר את המצגת."],
  ["\"In this section, I'll explain how we arrived at these numbers\" = בחלק הזה אסביר איך הגענו למספרים האלה. \"How we arrived at\" = איך הגענו ל-. \"Arrived at\" + תוצאה.", "\"The main reason for the increase was the new pricing model\" = הסיבה המרכזית לעלייה הייתה מודל התמחור החדש. \"Reason for\" + שם עצם, לא \"of\". \"Pricing model\" = מודל תמחור.", "\"Let me show you a comparison between this year and last year\" = תנו לי להראות לכם השוואה בין השנה הזאת לשנה שעברה. \"Comparison between\" = השוואה בין שני דברים.", "\"As the graph indicates, we're ahead of our target by fifteen percent\" = כפי שהגרף מראה, אנחנו מקדימים את היעד ב-חמישה-עשר אחוז. \"Ahead of target by\" = מקדימים ביעד ב-, \"by\" מציין את ההפרש.", "\"The most important number here is customer retention\" = המספר החשוב ביותר כאן הוא שימור הלקוחות. \"Retention\" = שימור, מונח עסקי נפוץ לשמירה על לקוחות.", "\"We can see a clear pattern in the data from the last quarter\" = אפשר לראות דפוס ברור בנתונים מהרבעון האחרון. \"In the data\" = בנתונים, \"from the last quarter\" = מהרבעון האחרון.", "\"I'd like to highlight two key findings from this study\" = הייתי רוצה להדגיש שני ממצאים מרכזיים מהמחקר הזה. \"Highlight\" = להדגיש. \"Findings\" = ממצאים.", "\"This slide summarizes the feedback we received from our users\" = השקף הזה מסכם את המשוב שקיבלנו מהמשתמשים. \"Received\" בעבר כי הקבלה הסתיימה, ו-\"summarizes\" בהווה כי השקף מתאר עכשיו.", "\"Let's look at the costs in more detail on the next slide\" = בוא נסתכל על העלויות בפירוט רב יותר בשקף הבא. \"Look at\" = להסתכל על, לא \"look on\". \"In more detail\" = בפירוט רב יותר.", "\"Here is a summary of what we achieved in the first half of the year\" = הנה סיכום של מה שהשגנו במחצית הראשונה של השנה. \"What we achieved\" = מה שהשגנו, שאלה עקיפה כנושא. \"The first half of the year\" = המחצית הראשונה של השנה."],
  ["\"The data supports our conclusion, but there are a few limitations I want to point out\" = הנתונים תומכים במסקנה שלנו, אבל יש כמה מגבלות שאני רוצה להצביע עליהן. \"Supports\" בלשון יחיד כי \"the data\" מתייחס לקבוצה. \"Point out\" = להצביע על.", "\"Our approach was to test the idea on a small group before scaling it up\" = הגישה שלנו הייתה לבחון את הרעיון על קבוצה קטנה לפני שמרחיבים אותו. \"Scaling up\" = הרחבה, ואחרי \"before\" בא ing.", "\"If you look closely at the second column, you'll notice an unexpected dip\" = אם מסתכלים היטב על העמודה השנייה, תבחינו בירידה לא צפויה. \"Look closely\" = להסתכל היטב. \"Unexpected dip\" = ירידה לא צפויה.", "\"That dip is related to the seasonal changes we saw in the previous year\" = הירידה הזאת קשורה לשינויים העונתיים שראינו בשנה הקודמת. \"Related to\" = קשור ל-. \"We saw\" בעבר כי מדובר בשנה שעברה.", "\"We considered three options, and each one came with its own trade-offs\" = שקלנו שלוש אפשרויות, ולכל אחת מהן יש יתרונות וחסרונות. \"Each one came with\" = לכל אחת היו. \"Trade-offs\" = פשרות, יתרונות וחסרונות מול זה.", "\"I'd like to frame this issue in terms of the risk it poses\" = הייתי רוצה למסגר את הנושא לפי הסיכון שהוא מציב. \"Frame in terms of\" = למסגר במונחים של. \"Poses\" = מציב, מציג.", "\"The chart might look dramatic, but the underlying trend is actually stable\" = הגרף עשוי להיראות דרמטי, אבל המגמה הבסיסית למעשה יציבה. \"Might look\" = עשוי להיראות, מציין אפשרות. \"Underlying\" = בסיסי, שמאחורי.", "\"We're still gathering evidence, so I'd treat these figures as preliminary\" = אנחנו עדיין אוספים ראיות, לכן כדאי להתייחס לנתונים האלה כראשוניים. \"Treat X as Y\" = להתייחס ל-X כאל Y. \"Preliminary\" = ראשוני.", "\"Let me explain why the results differ from what we had originally projected\" = תנו לי להסביר למה התוצאות שונות ממה שחזינו בתחילה. \"Had projected\" = Past Perfect כי החיזוי קדם לתוצאות. \"Differ from\" = שונה מ-.", "\"Before I move on, does anyone have a question about the methodology?\" = לפני שאמשיך, יש למישהו שאלה לגבי המתודולוגיה? \"Move on\" = לעבור לנושא הבא. \"Anyone\" בשאלה כללית."],
  ["\"Our analysis suggests that the problem is structural\" = הניתוח שלנו מצביע על כך שהבעיה מבנית. \"Suggests that\" + משפט מלא. \"Structural\" = מבני, קשור לאופן שבו המערכת בנויה.", "\"The question we need to answer is whether the new approach can be sustained\" = השאלה שעלינו לענות עליה היא אם אפשר לשמר את הגישה החדשה. \"Whether\" = אם, בשאלה עם שתי אפשרויות.", "\"What the numbers don't show is the impact on employee morale\" = מה שהמספרים לא מראים הוא ההשפעה על המוראל של העובדים. מבנה חיתוך (\"What... is\"), שמדגיש את הנושא. \"Equally important\" = חשוב באותה מידה.", "\"I'd like to draw a parallel between this project and a similar initiative\" = הייתי רוצה לעשות הקבלה בין הפרויקט הזה ליוזמה דומה. \"Draw a parallel\" = לעשות הקבלה, ביטוי קבוע.", "\"The results are encouraging, but we need to be careful not to read too much into a single quarter\" = התוצאות מעודדות, אבל עלינו להיזהר לא לפרש יותר מדי רבעון אחד. \"Read too much into\" = לפרש יתר על המידה. \"Careful not to\" + פועל.", "\"Once we account for the one-time expenses, the margin looks much healthier\" = אחרי שנביא בחשבון את ההוצאות החד־פעמיות, השולים נראה הרבה יותר בריא. \"Account for\" = להביא בחשבון. \"Once\" עם הווה לתנאי בעתיד.", "\"Let me walk you through the three scenarios\" = תנו לי להציג בפניכם את שלושת התרחישים. \"Walk through\" = להסביר צעד אחר צעד. \"What each one would mean\" = מה כל אחד מהם היה אומר.", "\"The point I want to make is that the strategy only works if the whole organization is aligned\" = הנקודה שאני רוצה להעביר היא שהאסטרטגיה עובדת רק אם כל הארגון מיושר. \"The point is that\" = הנקודה היא ש-. \"Aligned\" = מיושר, כלומר מסכים על כיוון אחד.", "\"I'd argue that the real risk lies not in the investment itself, but in delaying it\" = הייתי טוען שהסיכון האמיתי אינו בהשקעה עצמה, אלא בדחייה שלה. \"Lies not in X but in Y\" = נמצא לא ב-X אלא ב-Y. מבנה טיעון נפוץ.", "\"The conclusion follows from the evidence, although a few assumptions still need to be tested\" = המסקנה נובעת מהראיות, אם כי עדיין צריך לבחון כמה הנחות. \"Although\" = אף ש-. \"Still need to be tested\" = עדיין צריכות להיבדק, סביל."],
  ["\"Our data challenges the common idea that growth must cost quality\" = הנתונים שלנו מאתגרים את הרעיון הרווח שצמיחה חייבת לעלות באיכות. \"Cost quality\" = לעלות באיכות, במשמעות של להיות על חשבון האיכות.", "\"This approach treats customer feedback as a valuable asset\" = הגישה הזאת רואה במשוב לקוחות נכס יקר ערך. \"Treat X as Y\" = לראות ב-X כ-Y. \"Not just as complaints\" = לא רק כתלונות.", "\"The first results were promising, but the long-term picture raises questions we still need to answer\" = התוצאות הראשוניות היו מבטיחות, אבל התמונה לטווח ארוך מעלה שאלות שעדיין צריך לענות עליהן. \"Raises questions\" = מעלה שאלות.", "\"Our method is solid, but it assumes customers behave the same way in every market\" = השיטה שלנו אמינה, אבל היא מניחה שלקוחות מתנהגים באותו אופן בכל שוק. \"Assumes that\" + משפט. \"Behave\" = מתנהגים.", "\"I want to be honest about the uncertainty in these estimates\" = אני רוצה להיות כן לגבי אי הוודאות בהערכות האלה. \"Uncertainty\" = אי ודאות, שם עצם שמתאר מה לא ידוע.", "\"If we accept the starting point, the conclusion follows. But we should check the starting point again\" = אם נקבל את נקודת ההתחלה, המסקנה נובעת. אבל כדאי לבדוק את נקודת ההתחלה שוב. \"Follows\" = נובע, פועל לוגי. \"Starting point\" = נקודת מוצא.", "\"So far the presentation has focused on what we do; I'd like to spend the next few minutes on why we do it\" = עד כה המצגת התמקדה במה שאנחנו עושים, ואני רוצה לבלות את הדקות הבאות במדוע אנחנו עושים את זה. \"Focus on\" = להתמקד ב-. \"Spend time on\" = לבלות זמן על.", "\"This is not only about technology. It's about how we organize people around one goal\" = זה לא רק עניין של טכנולוגיה. זה עניין של איך מארגנים אנשים סביב מטרה אחת. \"Not only about X. It's about Y\" = מבנה שמשנה כיוון. \"Around one goal\" = סביב מטרה אחת.", "\"We shouldn't draw a big conclusion from such a small sample, even if the pattern looks convincing\" = אסור להסיק מסקנה גדולה ממדגם קטן כל כך, גם אם הדפוס נראה משכנע. \"Such\" + שם עצם מציין איכות. \"Even if\" = גם אם.", "\"The proposal is based on a simple idea, but it needs a lot of discipline across departments\" = ההצעה מבוססת על רעיון פשוט, אבל היא דורשת הרבה משמעת בין המחלקות. \"Based on\" = מבוסס על. \"Across departments\" = לאורך המחלקות."],
  ["\"Before we go to questions, let me remind you of the three main points\" = לפני שנעבור לשאלות, תנו לי להזכיר לכם את שלוש הנקודות המרכזיות. \"Remind you of\" = להזכיר לך. \"Let me\" + פועל הוא פתיחה מנומסת.", "\"That's a great question. It is at the heart of the problem\" = זו שאלה מצוינת. היא בלב הבעיה. \"At the heart of\" = בלב של, ביטוי מילולי ותמונתי.", "\"I don't have the exact number here, but I'll send you the detailed data after the session\" = אין לי את המספר המדויק כאן, אבל אשלח לכם את הנתונים המפורטים אחרי המפגש. \"After the session\" = אחרי המפגש. \"Send you\" = לשלוח לך.", "\"Let me explain again, because I think my first explanation was not clear\" = תנו לי להסביר שוב, כי נראה לי שההסבר הראשון שלי לא היה ברור. \"Explain again\" = להסביר שוב, \"again\" בסוף המשפט.", "\"You're right. I need to check that more carefully before I answer\" = אתם צודקים. אני צריך לבדוק את זה יותר בקפידה לפני שאענה. \"More carefully\" = בקפידה יותר, תואר פועל בהשוואה.", "\"I'll share the slides after the meeting, so you can read the details\" = אשתף את השקפים אחרי הפגישה, כדי שתוכלו לקרוא את הפרטים. \"So you can\" = כדי ש-, מציין מטרה.", "\"If something was not clear, come and talk to me\" = אם משהו לא היה ברור, בואו דברו איתי. \"Come and talk\" = בואו ודברו, צורה טבעית לדבר.", "\"The short answer is yes. The long answer depends on how the market reacts next quarter\" = התשובה הקצרה היא כן. התשובה הארוכה תלויה בתגובת השוק ברבעון הבא. \"Depends on how\" = תלוי באופן ש-.", "\"Thank you for your feedback. We'll take those concerns into account in the next version\" = תודה על המשוב. ניקח את החששות האלה בחשבון בגרסה הבאה. \"Take into account\" = לקחת בחשבון.", "\"Thank you for the good questions. They gave me ideas for next steps\" = תודה על השאלות הטובות. הן נתנו לי רעיונות לצעדים הבאים. \"Gave me ideas for\" = נתנו לי רעיונות ל-."],
  ["\"To finish: the facts point in one direction, but the decision still depends on the risk and the timing\" = לסיום: העובדות מצביעות לכיוון אחד, אבל ההחלטה עדיין תלויה בסיכון ובתזמון. \"Point in one direction\" = מצביעות לכיוון אחד.", "\"My advice is simple: start small, measure carefully, and grow only what works\" = העצה שלי פשוטה: להתחיל בקטן, למדוד בקפידה, ולהגדיל רק את מה שעובד. רשימה של פעלים בציווי עם פסיקים.", "\"The success of this project depends more on the people doing the work than on the plan\" = הצלחת הפרויקט תלויה יותר באנשים שעושים את העבודה מאשר בתוכנית. \"Depends more on X than on Y\" = תלוי יותר ב-X מאשר ב-Y.", "\"Our next step is to show the budget to the board\" = הצעד הבא שלנו הוא להציג את התקציב לדירקטוריון. \"Our next step is to\" + פועל בלי \"to\" אחרי \"is\" במבנה הזה.", "\"Thank you for your time. I believe this project can make a real difference for the company\" = תודה על הזמן. אני מאמין שהפרויקט הזה יכול לעשות הבדל אמיתי לחברה. \"Make a difference\" = לעשות הבדל.", "\"In short: the demand is real, the costs are manageable, and we understand the risks\" = בקצרה: הביקוש אמיתי, העלויות ניתנות לניהול, ואנחנו מבינים את הסיכונים. \"In short\" = בקצרה, ביטוי סיכום.", "\"I'm sure we'll reach our goals if we keep clear priorities and work steadily\" = אני בטוח שנגיע ליעדים שלנו אם נשמור על סדר עדיפויות ברור ונעבוד בהתמדה. \"If we keep\" + הווה לתנאי.", "\"Before we close, let's agree who will take the next steps\" = לפני שנסיים, בוא נסכים מי ייקח את הצעדים הבאים. \"Let's agree who\" = שאלה עקיפה אחרי \"agree\".", "\"The data aren't perfect, but the direction is clear. I'd rather act now than wait\" = הנתונים לא מושלמים, אבל הכיוון ברור. עדיף לי לפעול עכשיו מאשר לחכות. \"I'd rather X than Y\" = עדיף לי X על פני Y.", "\"So, to finish: thank you for listening. I look forward to your feedback as we move forward\" = אז לסיום: תודה שהקשבתם. אני מצפה למשוב שלכם בהמשך הדרך. \"Look forward to\" + שם עצם (feedback). \"Move forward\" = להתקדם."],
  ["\"I'm the project manager for the new website launch\" = אני מנהל הפרויקט של השקת האתר החדש. \"Project manager\" הוא הסדר המקובל באנגלית. \"For the launch\" = להשקה.", "\"The project starts on March 1st and ends in June\" = הפרויקט מתחיל ב-1 במרץ ומסתיים ביוני. תאריך מתחיל ב-\"on\" (\"on March 1st\"), וחודש לבד מקבל \"in\" (\"in June\").", "\"Our main goal is to finish the project on time and within budget\" = המטרה המרכזית שלנו היא לסיים את הפרויקט בזמן ובתוך התקציב. \"On time\" = בזמן. \"Within budget\" = בתוך התקציב.", "\"Each team member has a clear role in the project\" = לכל חבר צוות יש תפקיד ברור בפרויקט. \"Each\" + שם עצם ביחיד, ולכן \"has\" ולא \"have\". \"Role in\" = תפקיד ב-.", "\"We meet every Monday to review the progress\" = אנחנו נפגשים בכל יום שני כדי לסקור את ההתקדמות. \"Every Monday\" בלי \"on\". \"To review\" מציין מטרה.", "\"The first milestone is the design approval\" = אבן הדרך הראשונה היא אישור העיצוב. \"Milestone\" = אבן דרך, נקודת ביקורת בפרויקט. \"Design approval\" = אישור עיצוב.", "\"Please update the task board after you finish each item\" = נא לעדכן את לוח המשימות אחרי שאתם מסיימים כל פריט. \"After\" + הווה (\"finish\") בתיאור פעולה עתידית.", "\"We're currently on schedule, but the budget is a bit tight\" = כרגע אנחנו בזמן, אבל התקציב קצת הדוק. \"On schedule\" = בזמן, לפי התוכנית. \"A bit tight\" = הדוק קצת.", "\"Who is responsible for testing the new features?\" = מי אחראי על בדיקת התכונות החדשות? \"Responsible for\" + ing או שם עצם. \"Features\" = תכונות.", "\"The deadline for the first version is the end of next month\" = המועד האחרון לגרסה הראשונה הוא סוף החודש הבא. \"Deadline for\" = מועד אחרון ל-. \"The end of next month\" = סוף החודש הבא."],
  ["\"We've identified three risks that could delay the project\" = זיהינו שלושה סיכונים שעלולים לעכב את הפרויקט. Present Perfect כי הזיהוי הושלם. \"Could delay\" = עלולים לעכב, אפשרות.", "\"Let's assign an owner to each task so nothing gets lost\" = בוא נמנה בעלים לכל משימה כדי ששום דבר לא ילך לאיבוד. \"Nothing gets lost\" = שום דבר לא הולך לאיבוד, מבנה סביל עם שלילה.", "\"The scope has grown since the start, so we need to review the plan\" = ההיקף גדל מאז ההתחלה, לכן אנחנו צריכים לבחון את התוכנית. \"Has grown since\" = Present Perfect עם \"since\" לנקודת זמן.", "\"We need to prioritize the features that matter most to the customers\" = אנחנו צריכים לתעדף את התכונות שחשובות ביותר ללקוחות. \"Prioritize\" = לתעדף. \"That matter most\" = שחשובות ביותר.", "\"The developers are working on the integration, and they expect to finish next week\" = המפתחים עובדים על האינטגרציה, והם מצפים לסיים בשבוע הבא. \"Are working\" = הווה מתמשך לפעולה שקורית עכשיו.", "\"If the vendor delivers late, the whole timeline will shift\" = אם הספק יספק באיחור, כל לוח הזמנים יזוז. תנאי מסוג 1: \"if\" + הווה (\"delivers\") ו-\"will\" בתוצאה.", "\"Let's agree on a clear definition of done before we start the next sprint\" = בוא נסכים על הגדרה ברורה של \"הושלם\" לפני שנתחיל את הספרינט הבא. \"Definition of done\" = מונח Agile לתיאור מתי משימה נחשבת גמורה.", "\"We're tracking progress weekly and sharing the report with management\" = אנחנו עוקבים אחרי ההתקדמות מדי שבוע ומשתפים את הדוח עם ההנהלה. \"Tracking\" + ing לתיאור פעולה שקורית שוב ושוב.", "\"I'd like to escalate the issue, because it's blocking two other teams\" = הייתי רוצה להעלות את הנושא לדרג גבוה יותר, כי הוא חוסם שני צוותים אחרים. \"Escalate\" = להעביר לדרג גבוה. \"Blocking\" = חוסם.", "\"We have a dependency on the legal team, so we need their sign-off first\" = יש לנו תלות בצוות המשפטי, לכן אנחנו צריכים את האישור שלהם קודם. \"Dependency on\" = תלות ב-. \"Sign-off\" = אישור סופי."],
  ["\"The original estimate didn't account for the testing phase, which is why we're behind\" = האומדן המקורי לא כלל את שלב הבדיקות, וזו הסיבה שאנחנו מאחור. \"Account for\" = לכלול. \"Which is why\" = וזו הסיבה ש-.", "\"We can either reduce the scope or extend the deadline, but we can't do both without consequences\" = אפשר או לצמצם את ההיקף או להאריך את הדדליין, אבל אי אפשר לעשות את שניהם בלי השלכות. \"Either... or\" = או... או. \"Without consequences\" = בלי השלכות.", "\"To keep the project healthy, I'd suggest a short retrospective after every milestone\" = כדי לשמור על הפרויקט בריא, הייתי מציע סיכום קצר אחרי כל אבן דרך. \"Retrospective\" = סיכום אחורה, בדיקת הלקחים.", "\"The main bottleneck is the approval process, which takes far longer than anyone expected\" = צוואר הבקבוק המרכזי הוא תהליך האישורים, שלוקח הרבה יותר זמן ממה שמישהו ציפה. \"Bottleneck\" = צוואר בקבוק. \"Far longer than\" = הרבה יותר זמן מ-.", "\"We've mitigated the risk by building a backup plan for the data migration\" = הקטנו את הסיכון על ידי בניית תוכנית גיבוי למעבר הנתונים. \"Mitigated\" = הקטנו, לא ביטלנו. \"By\" + ing מציין אמצעי.", "\"Let's make sure that the stakeholders are informed before any major change\" = בוא נוודא שבעלי העניין מעודכנים לפני כל שינוי מהותי. \"Stakeholders\" = בעלי עניין. \"Make sure that\" + משפט עם סביל.", "\"The team is stretched thin, so we should avoid adding new work until the current release is done\" = הצוות עמוס מאוד, לכן כדאי להימנע מהוספת עבודה חדשה עד שהגרסה הנוכחית תסתיים. \"Stretched thin\" = מרוחב מדי, עמוס מדי. \"Avoid\" + ing.", "\"I'd like to see the burn-down chart before we decide on the next steps\" = הייתי רוצה לראות את תרשים ההתקדמות לפני שנחליט על הצעדים הבאים. \"Burn-down chart\" = תרשים שמראה כמה נשאר לעשות, מונח מקובל בניהול פרויקטים.", "\"Can you tell me which tasks are on the critical path?\" = אתה יכול לומר לי אילו משימות נמצאות על הנתיב הקריטי? \"On the critical path\" = על הנתיב הקריטי, הרצף הארוך ביותר שקובע את תאריך הסיום.", "\"The change request was approved, but it will add two weeks to the schedule\" = בקשת השינוי אושרה, אבל היא תוסיף שבועיים ללוח הזמנים. \"Add X to Y\" = להוסיף X ל-Y."],
  ["\"We have to balance the trade-off between speed and quality, and I think we've leaned too far toward speed\" = אנחנו צריכים לאזן בין מהירות לאיכות, ואני חושב שנטינו יותר מדי למהירות. \"Lean toward\" = להטות לכיוון. \"Too far\" = רחוק מדי.", "\"The root cause of the delays was not technical; it was a lack of clear communication\" = שורש העיכובים לא היה טכני; הוא היה חוסר בתקשורת ברורה. \"Root cause\" = שורש הבעיה. \"A lack of\" + שם עצם.", "\"Without a shared roadmap, each team optimizes for its own goals, which creates friction\" = בלי מפת דרכים משותפת, כל צוות מייעל למטרות שלו, וזה יוצר חיכוך. \"Optimizes for\" = מייעל ל-. \"Friction\" = חיכוך, קונפליקט.", "\"We should separate the must-have requirements from the nice-to-have ones before we commit to a date\" = כדאי להפריד בין הדרישות ההכרחיות לאלה שרק נחמד שיהיו, לפני שנתחייב לתאריך. \"Nice-to-have\" = נחמד שיהיה, דרישה לא הכרחית.", "\"I'm concerned that the current plan depends too heavily on one person's availability\" = אני מודאג שהתוכנית הנוכחית תלויה מדי בזמינות של אדם אחד. \"Depends heavily on\" = תלוי מאוד ב-. \"One person's availability\" = זמינות של אדם אחד, שם עצם בקניין.", "\"Our estimate was based on past projects, but the new technology introduces unknowns we hadn't accounted for\" = האומדן שלנו התבסס על פרויקטים קודמים, אבל הטכנולוגיה החדשה מביאה אי־ודאויות שלא לקחנו בחשבון. \"Hadn't accounted for\" = Past Perfect כי הלקיחה בחשבון הייתה לפני הבעיה.", "\"Let's agree on a change-control process, so that new requests go through a formal review\" = בוא נסכים על תהליך לניהול שינויים, כך שבקשות חדשות יעברו בדיקה רשמית. \"Go through\" = לעבור דרך. \"Formal review\" = בדיקה רשמית.", "\"Rather than chase perfection, we should aim for a version that delivers real value to users\" = במקום לרדוף אחרי שלמות, כדאי לכוון לגרסה שנותנת ערך אמיתי למשתמשים. \"Rather than\" + ing (chase). \"Aim for\" = לכוון ל-.", "\"The milestone slipped because the dependencies weren't mapped out at the beginning\" = אבן הדרך התעכבה כי התלויות לא מופו בהתחלה. \"Slipped\" = התעכב, עבר זמן מתוכנן. \"Mapped out\" = מופו, תוכננו בבירור.", "\"If we don't address the morale issue, productivity will keep dropping regardless of the timeline\" = אם לא נטפל בנושא המוראל, הפרודוקטיביות תמשיך לרדת, ללא קשר ללוח הזמנים. \"Keep dropping\" = ממשיך לרדת. \"Regardless of\" = ללא קשר ל-."],
  ["\"The project's success hinges on our ability to adapt the plan\" = הצלחת הפרויקט תלויה ביכולת שלנו להתאים את התוכנית. \"Hinges on\" = תלוי ב-, ביטוי מילולי ומקצועי.", "\"While the schedule is ambitious, I believe it's achievable if we're disciplined about scope\" = אף שלוח הזמנים שאפתני, אני מאמין שהוא ניתן להשגה אם נהיה ממושמעים לגבי ההיקף. \"While\" = אף ש-. \"Disciplined about\" = ממושמע לגבי.", "\"We need to weigh the cost of delaying the launch against the cost of releasing a product that isn't ready\" = צריך לשקול את העלות של דחיית ההשקה מול העלות של שחרור מוצר שאינו מוכן. \"Weigh X against Y\" = לשקול X מול Y.", "\"The stakeholders have very different definitions of success, and until we reconcile them, progress will stall\" = לבעלי העניין יש הגדרות שונות מאוד להצלחה, ועד שנישר אותן, ההתקדמות תיעצר. \"Until\" + הווה לזמן עתידי. \"Reconcile\" = ליישב, להתאים.", "\"The vendor's proposal looks cheaper on paper, but the hidden costs of integration could easily wipe out the savings\" = ההצעה של הספק נראית זולה יותר על הנייר, אבל העלויות הנסתרות של האינטגרציה עלולות בקלות למחוק את החיסכון. \"On paper\" = על הנייר, כלומר בתיאוריה. \"Wipe out\" = למחוק.", "\"Had we invested in better planning at the outset, we would have avoided most of the rework\" = אילו היינו משקיעים בתכנון טוב יותר מההתחלה, היינו נמנעים מרוב העבודה החוזרת. תנאי מסוג 3 עם \"had\" בתחילת המשפט בלי \"if\".", "\"The risk register is useful only if we review it regularly and act on the warning signs\" = רישום הסיכונים שימושי רק אם בודקים אותו באופן קבוע ופועלים לפי אותות האזהרה. \"Risk register\" = רשימת סיכונים. \"Only if\" = רק אם.", "\"We cannot treat the schedule as fixed when the underlying assumptions have changed this much\" = אי אפשר להתייחס ללוח הזמנים כקבוע כשההנחות הבסיסיות השתנו כל כך. \"Treat X as Y\" = להתייחס ל-X כאל Y. \"Have changed\" = Present Perfect כי השינוי משפיע עכשיו.", "\"A project that runs smoothly on paper can still stumble in practice if the handoffs are poorly managed\" = פרויקט שרץ חלק על הנייר עלול עדיין להיתקל בפועל אם המסירות מנוהלות בצורה גרועה. \"Handoffs\" = מסירות עבודה בין צוותים. \"Stumble\" = להיתקל.", "\"I'd recommend a pilot phase, not because we doubt the design, but because real users will reveal problems\" = הייתי ממליץ על שלב פיילוט, לא כי אנחנו מפקפקים בעיצוב, אלא כי משתמשים אמיתיים יחשפו בעיות. \"Not because... but because\" = מבנה להסבר סיבה כפולה."],
  ["\"Could you walk me through the reasons the milestone was missed?\" = אפשר להסביר לי את הסיבות לכך שאבן הדרך לא הושגה? \"Walk me through\" = להסביר לי צעד אחר צעד. \"Was missed\" = סבילה.", "\"We need one more backend developer, so I'd like to ask for approval\" = אנחנו צריכים מפתח נוסף לצד השרת, ולכן הייתי רוצה לבקש אישור. \"Backend\" = צד שרת. \"Ask for approval\" = לבקש אישור.", "\"Before we agree on the new date, let's check that every team can do the work\" = לפני שנסכים על התאריך החדש, בוא נבדוק שלכל צוות יש את היכולת לעשות את העבודה. \"Every team can\" = כל צוות יכול, \"every\" + שם עצם ביחיד.", "\"The sprint review went well, but we need clearer acceptance criteria for the next round\" = סקירת הספרינט עברה טוב, אבל אנחנו צריכים קריטריוני קבלה ברורים יותר לסבב הבא. \"Clearer\" = ברור יותר, תואר בהשוואה.", "\"Let's make sure the handover documents are complete before the team moves on\" = בוא נוודא שמסמכי המסירה שלמים לפני שהצוות ממשיך. \"Handover\" = מסירה. \"Moves on\" = ממשיך לפרויקט הבא.", "\"I'd like to suggest a small change in the workflow. It could save us hours each week\" = הייתי רוצה להציע שינוי קטן בתהליך העבודה. הוא יכול לחסוך לנו שעות בכל שבוע. \"Could save\" = יכול לחסוך, אפשרות. \"Each week\" = בכל שבוע.", "\"We can't keep adding features without removing something, or the release won't be stable\" = אי אפשר להמשיך להוסיף תכונות בלי להסיר משהו, אחרת הגרסה לא תהיה יציבה. \"Keep + ing\" = להמשיך לעשות. \"Without + ing\" = בלי לעשות.", "\"Who can approve budget changes after the project has started?\" = מי יכול לאשר שינויים בתקציב אחרי שהפרויקט התחיל? \"Has started\" = Present Perfect כי ההתחלה קרתה לפני ההווה.", "\"The client wants an update, so let's prepare a short summary of where we are\" = הלקוח רוצה עדכון, לכן בוא נכין סיכום קצר של המצב. \"Where we are\" = איפה אנחנו, כלומר המצב הנוכחי. שאלה עקיפה בתוך משפט.", "\"I think we should freeze the scope until the first release, and then review what we learned\" = לדעתי כדאי להקפיא את ההיקף עד הגרסה הראשונה, ואז לבחון מה למדנו. \"Freeze the scope\" = לא להוסיף דברים חדשים להיקף."],
  ["\"The project is on track now. Thank you, team, for your commitment during a hard period\" = הפרויקט בדרך הנכונה עכשיו. תודה לצוות על המחויבות בתקופה קשה. \"On track\" = בדרך הנכונה, ביטוי נפוץ בעדכון סטטוס.", "\"Our next priority is to make the release stable, so we'll fix bugs before adding anything new\" = העדיפות הבאה שלנו היא לייצב את הגרסה, לכן נתקן תקלות לפני שנוסיף משהו חדש. \"Make X stable\" = לייצב את X. \"Before adding\" + ing.", "\"Now that the handover is done, the operations team can maintain the system\" = עכשיו, אחרי שהמסירה הסתיימה, צוות התפעול יכול לתחזק את המערכת. \"Now that\" = עכשיו כש-, מציג תנאי שכבר התקיים.", "\"We closed most of the open risks, and each remaining one has an owner\" = סגרנו את רוב הסיכונים הפתוחים, ולכל אחד מהנותרים יש בעלים. \"Each remaining one\" = כל אחד מהנותרים. \"Has an owner\" = בעל תפקיד.", "\"Let's write down what we learned, so the next project starts stronger\" = בוא נרשום מה למדנו, כדי שהפרויקט הבא יתחיל חזק יותר. \"Write down\" = לרשום. \"Stronger\" = חזק יותר, השוואה.", "\"Based on the feedback, we'll update the plan for phase two and share the new timeline next week\" = על בסיס המשוב, נעדכן את התוכנית לשלב השני ונשתף את לוח הזמנים החדש בשבוע הבא. \"Based on\" = על בסיס.", "\"The launch went well, but the real test is how the product works over the next three months\" = ההשקה הייתה טובה, אבל המבחן האמיתי הוא איך המוצר עובד במשך שלושת החודשים הבאים. \"The real test is\" = המבחן האמיתי הוא. \"Over\" = במשך.", "\"I want to thank those of you who worked extra hours. That effort made the difference\" = אני רוצה להודות למי מכם שעבד שעות נוספות. המאמץ הזה עשה את ההבדל. \"Those of you who\" = אלה מכם ש-. \"Made the difference\" = עשה את ההבדל.", "\"From now on, I'd like status meetings to be short and focused on decisions\" = מעכשיו, הייתי רוצה שפגישות הסטטוס יהיו קצרות ויתמקדו בהחלטות. \"From now on\" = מעכשיו והלאה. \"Focused on\" = מתמקדות ב-.", "\"The project finished on time. That is rare, and it shows the discipline we built together\" = הפרויקט הסתיים בזמן. זה נדיר, וזה מראה את המשמעת שבנינו יחד. \"On time\" = בזמן. \"Built together\" = בנינו יחד."],
  ["\"Hello, this is Daniel from Brightline. How can I help you?\" = שלום, כאן דניאל מ-Brightline. איך אוכל לעזור? \"This is\" הוא דרך טבעית לזהות את עצמך בטלפון.", "\"Could I speak to Ms. Cohen, please?\" = אפשר לדבר עם גב' כהן? \"Speak to\" עם \"to\" (לא \"speak with\" כשמבקשים אדם בטלפון). \"Ms.\" = גברת.", "\"She's not available right now. Would you like to leave a message?\" = היא לא זמינה כרגע. תרצה להשאיר הודעה? \"Available\" = זמין. \"Leave a message\" = להשאיר הודעה.", "\"Could you spell your last name for me, please?\" = אפשר לאיית לי את שם המשפחה שלך? \"Spell\" = לאיית. \"For me\" = בשבילי.", "\"I'll call you back this afternoon\" = אתקשר אליך שוב אחר הצהריים. \"Call back\" = להתקשר שוב. \"This afternoon\" = אחר הצהריים של היום.", "\"Can you hear me clearly? The line isn't very good\" = אתה שומע אותי בבירור? הקו לא טוב במיוחד. \"The line\" = הקו בשיחה טלפונית. \"Very good\" = טוב מאוד, נדיר בשלילה \"not very good\".", "\"Let me put you on hold for a moment\" = תן לי להעביר אותך להמתנה לרגע. \"Put on hold\" = להעביר להמתנה, ביטוי קבוע בטלפון.", "\"Would you like me to take a message for him?\" = האם תרצה שאשאיר לו הודעה? \"Take a message\" = לרשום הודעה, ביטוי טלפוני קבוע.", "\"I'm calling to confirm our meeting for Tuesday at ten\" = אני מתקשר כדי לאשר את הפגישה שלנו ביום שלישי בעשר. \"I'm calling to\" = אני מתקשר כדי ל-. \"At ten\" = בשעה עשר.", "\"Thank you for calling, and have a good day\" = תודה שהתקשרת, ויום טוב. סיום שיחה טלפונית נפוץ."],
  ["\"I'm calling about the invoice we received last Monday\" = אני מתקשר בנוגע לחשבונית שקיבלנו ביום שני שעבר. \"Calling about\" = מתקשר בנוגע ל-. \"Last Monday\" = ביום שני שעבר.", "\"Could you transfer me to the accounts department, please?\" = אפשר להעביר אותי למחלקת החשבונות? \"Transfer me to\" = להעביר אותי ל-. \"Accounts department\" = מחלקת חשבונות.", "\"I'm afraid she's in a meeting until three o'clock\" = אני חושש שהיא בפגישה עד שלוש. \"I'm afraid\" = אני חושש ש-, מוסיף רכות לחדשות לא נעימות. \"Until three o'clock\" = עד שלוש.", "\"Would it be convenient for you to talk tomorrow morning?\" = האם זה נוח לך לדבר מחר בבוקר? \"Would it be convenient for you to\" = האם נוח לך ל-. נימוס מאוד בשיחה.", "\"I'd like to reschedule our call to a time that suits you better\" = הייתי רוצה לקבוע מחדש את השיחה שלנו לזמן שמתאים לך יותר. \"Reschedule\" = לקבוע מחדש. \"Suits you\" = מתאים לך.", "\"Sorry, I didn't catch that. Could you say it again?\" = סליחה, לא תפסתי. אפשר לומר שוב? \"Catch\" = לתפוס, במשמעות של לשמוע או להבין. ביטוי טלפוני נפוץ.", "\"I'll make sure he gets your message as soon as he's back\" = אדאג שהוא יקבל את ההודעה שלך ברגע שיחזור. \"Make sure\" + משפט, ו-\"as soon as\" + הווה לאירוע עתידי.", "\"Can I take your number so she can call you back?\" = אפשר לקבל את המספר שלך כדי שהיא תוכל להתקשר אליך שוב? \"So she can\" = כדי ש-, מציין מטרה.", "\"Just to confirm, the delivery is scheduled for Thursday between nine and noon\" = רק כדי לאשר, המשלוח מתוזמן ליום חמישי בין תשע לשתים עשרה. \"Scheduled for\" = מתוזמן ל-. \"Between nine and noon\" = בין תשע לצהריים.", "\"Let me read back the details to make sure I have them right\" = תן לי לחזור על הפרטים כדי לוודא שרשמתי אותם נכון. \"Read back\" = לחזור על מה שנאמר, ביטוי טלפוני נפוץ לאישור."],
  ["\"I'm sorry for calling so early. I hope I didn't catch you at a bad time\" = מצטער שאני מתקשר כל כך מוקדם. מקווה שלא תפסתי אותך ברגע לא נוח. \"Catch you at a bad time\" = לתפוס אותך ברגע לא נוח.", "\"I'm calling because we've noticed a discrepancy between the order and the invoice\" = אני מתקשר כי שמנו לב לאי התאמה בין ההזמנה לחשבונית. \"Discrepancy\" = אי התאמה, שם עצם מדויק וגם מנומס.", "\"Would you mind explaining how the discount was calculated?\" = האם תהיה מוכן להסביר איך חושב ההנחה? \"Would you mind\" + ing = האם יפריע לך ל-, שאלה מנומסת מאוד.", "\"I'd like to speak to someone who can authorize a change to the contract\" = הייתי רוצה לדבר עם מישהו שיכול לאשר שינוי בחוזה. \"Someone who can\" = מישהו ש-, משפט יחסי. \"Authorize\" = לאשר רשמית.", "\"I understand that you're busy, so I'll keep this brief\" = אני מבין שאתה עסוק, לכן אשמור על זה קצר. \"Keep this brief\" = לשמור על זה קצר.", "\"If the issue isn't resolved by Friday, we'll need to escalate it to our manager\" = אם הבעיה לא תיפתר עד יום שישי, נצטרך להעלות אותה למנהל שלנו. תנאי מסוג 1 עם \"isn't\" בהווה ו-\"will need\" בתוצאה.", "\"I'm not sure I understood correctly; could you walk me through it once more?\" = לא בטוח שהבנתי נכון; אפשר להסביר לי שוב צעד אחר צעד? \"Walk me through it\" = להסביר לי את זה.", "\"Our system shows a different figure, so could you check that on your end?\" = המערכת שלנו מראה מספר אחר, אז אפשר לבדוק את זה מצדכם? \"On your end\" = מצדך, מהצד שלך.", "\"I'd be grateful if you could send me a written confirmation of what we agreed on\" = אודה לך אם תוכל לשלוח לי אישור כתוב למה שסיכמנו. \"Agreed on\" = סוכם לגבי. \"Written confirmation\" = אישור כתוב.", "\"Let's try to sort this out today so we don't have to chase it later\" = בוא ננסה לפתור את זה היום, כדי שלא נצטרך לרדוף אחריו מאוחר יותר. \"Sort out\" = לפתור. \"Chase\" = לרדוף אחרי, להזכיר שוב."],
  ["\"I apologize for the misunderstanding; the figures were given to us in a different format\" = אני מתנצל על אי ההבנה; הנתונים הגיעו אלינו בפורמט אחר. \"Apologize for\" + שם עצם, לא \"apologize you\".", "\"Given the urgency, I'd like to ask whether there's a way to expedite the approval process\" = לאור הדחיפות, הייתי רוצה לשאול אם יש דרך להאיץ את תהליך האישור. \"Expedite\" = להאיץ, מונח רשמי יותר מ-\"speed up\".", "\"I'm calling on behalf of my manager, who would like to discuss the terms\" = אני מתקשר בשם המנהל שלי, שהיה רוצה לדון בתנאים. \"On behalf of\" = בשם. \"Who would like to\" = שמעוניין ל-.", "\"We're open to negotiating, but we'd need some flexibility on the delivery dates\" = אנחנו פתוחים למשא ומתן, אבל נצטרך קצת גמישות בתאריכי האספקה. \"Open to\" + ing = פתוח ל-. \"Some flexibility\" = קצת גמישות.", "\"Before we proceed, could you confirm whether the price includes the installation\" = לפני שנמשיך, אפשר לאשר אם המחיר כולל את ההתקנה? \"Proceed\" = להמשיך. \"Whether\" = אם, בשאלה עם שתי אפשרויות.", "\"I'd prefer to handle this by email so that we have a clear written record\" = הייתי מעדיף לטפל בזה במייל, כדי שיהיה לנו תיעוד כתוב ברור. \"Handle by email\" = לטפל בדרך של מייל. \"Written record\" = תיעוד כתוב.", "\"We've been trying to reach your team for several days, and I'd appreciate a prompt reply\" = ניסינו ליצור קשר עם הצוות שלכם כבר כמה ימים, ואודה לתשובה מהירה. Present Perfect Continuous (\"have been trying\") למשך שנמשך עד עכשיו. \"Prompt\" = מהיר.", "\"I'm not able to make a commitment on the date until I've checked the availability\" = איני יכול להתחייב לתאריך לפני שבדקתי את הזמינות. \"Until I've checked\" = עד שבדקתי, Present Perfect כי הבדיקה תושלם לפני ההתחייבות.", "\"Could you explain why the shipment was delayed, and what steps you're taking to prevent it\" = אפשר להסביר למה המשלוח התעכב, ואילו צעדים אתם נוקטים כדי למנוע את זה? \"What steps you're taking\" = איזה צעדים אתם נוקטים עכשיו, הווה מתמשך.", "\"If we're unable to reach an agreement by the end of the call, I'll need to escalate this\" = אם לא נגיע להסכמה עד סוף השיחה, אצטרך להעלות את זה לדרג גבוה. תנאי מסוג 1 עם \"unable\" כתואר של ההווה."],
  ["\"Thank you for your call. I appreciate you explaining things in detail\" = תודה על השיחה. אני מעריך שהסברת את הדברים בפירוט. \"Appreciate you explaining\" = מעריך שאתה מסביר, אחרי \"appreciate\" בא ing.", "\"I can't give you an answer right now. The committee meets on Wednesdays, and they make the decision\" = איני יכול לתת לך תשובה עכשיו. הוועדה מתכנסת בימי רביעי, והם מקבלים את ההחלטה. \"Meets on Wednesdays\" = מתכנס בימי רביעי, \"on\" + יום בשבוע ברבים.", "\"I understand your point, but the board set this policy, and I can't change it\" = אני מבין את הנקודה שלך, אבל הדירקטוריון קבע את המדיניות הזאת, ואין לי סמכות לשנות אותה. \"Set this policy\" = קבע את המדיניות, בעבר כי זה כבר נקבע.", "\"If I read the contract correctly, the penalty applies only after the second missed delivery\" = אם אני קורא את החוזה נכון, הקנס חל רק אחרי האספקה השנייה שהוחמצה. \"If I read\" בהווה לתנאי אמיתי. \"Only after\" = רק אחרי.", "\"Could you put the new terms in writing, so both sides have a clear reference?\" = אפשר לכתוב את התנאים החדשים, כדי ששני הצדדים יהיו עם הפניה ברורה? \"In writing\" = בכתב. \"Clear reference\" = הפניה ברורה.", "\"Let's stop here and talk again after both teams review the numbers\" = בוא נעצור כאן ונדבר שוב אחרי שכל צוות יבחן את המספרים. \"After both teams review\" = אחרי ש-, הווה לזמן עתידי.", "\"I hear you, but I'm not sure the new change solves the real problem\" = אני שומע אותך, אבל אני לא בטוח שהשינוי החדש פותר את הבעיה האמיתית. \"I hear you\" = אני שומע אותך, ביטוי שמביע הבנה בלי הסכמה.", "\"Let's agree on a deadline for the next step, so we don't wait forever\" = בוא נסכים על דדליין לצעד הבא, כדי שלא נחכה לנצח. \"Wait forever\" = לחכות לנצח, במשמעות של לחכות יותר מדי.", "\"Maybe we need a neutral third party to help, since we keep going in circles\" = אולי צריך גורם ניטרלי שיעזור, כי אנחנו ממשיכים להסתובב במעגלים. \"Going in circles\" = להסתובב במעגלים, כלומר לא להתקדם.", "\"Our legal team has to approve any change to the liability terms first\" = הצוות המשפטי שלנו צריך לאשר קודם כל שינוי בתנאי האחריות. \"Has to approve\" = צריך לאשר. \"Liability terms\" = תנאי אחריות."],
  ["\"I'm calling about the voicemail I left on Monday. I want to make sure you got it\" = אני מתקשר בנוגע להודעה הקולית שהשארתי ביום שני. אני רוצה לוודא שקיבלת אותה. \"Voicemail\" = הודעה קולית. \"Got it\" = קיבלת אותה.", "\"Would you mind if I put you on speaker, so my colleague can join?\" = האם יפריע לך אם אשים אותך על רמקול, כדי שהעמית שלי יצטרף? \"Would you mind if I\" + הווה = האם יפריע לך אם אעשה.", "\"Hold on, I'm going to check the system. I'll be back in a moment\" = רגע, אני הולך לבדוק במערכת. אחזור בעוד רגע. \"Hold on\" = חכה, רגע. \"I'll be back\" = אחזור.", "\"Sorry, the line dropped. Could you call me back at this number?\" = סליחה, הקו נותק. אפשר להתקשר אליי חזרה למספר הזה? \"The line dropped\" = הקו נפל, ניתק.", "\"Before we hang up, let me repeat what we decided\" = לפני שנסיים, תן לי לחזור על מה שהחלטנו. \"Hang up\" = לנתק. \"Let me repeat\" = תן לי לחזור.", "\"If you could send me an email with the reference number, that would be very helpful\" = אם תוכל לשלוח לי מייל עם מספר האסמכתא, זה יעזור לי מאוד. \"If you could\" = אם תוכל, תנאי מנומס עם עבר בלי זמן אמיתי.", "\"Thanks for waiting. I know it took a long time, and I appreciate your patience\" = תודה שחיכית. אני יודע שזה לקח הרבה זמן, ואני מעריך את הסבלנות שלך. \"Took a long time\" = לקח זמן רב.", "\"Could you put me through to someone who can help with billing questions?\" = אפשר להעביר אותי למישהו שיכול לעזור בשאלות חיוב? \"Put through to\" = להעביר אל. \"Billing questions\" = שאלות חיוב.", "\"I need to check the figures again before I confirm anything, so I'll call you back\" = אני צריך לבדוק את הנתונים שוב לפני שאאשר משהו, לכן אחזור אליך. \"Before I confirm\" + הווה.", "\"Is there anything else I can do for you today?\" = יש עוד משהו שאוכל לעשות בשבילך היום? \"Anything else I can do\" = עוד משהו שאפשר לעשות. בסוף השיחה זהו סיום נפוץ."],
  ["\"Thank you for your time today. We made real progress, and I look forward to the next steps\" = תודה על הזמן היום. התקדמנו באמת, ואני מצפה לצעדים הבאים. \"Made real progress\" = עשינו התקדמות אמיתית.", "\"I'll send you a summary email within the hour, so you have everything in writing\" = אשלח לך מייל עם סיכום תוך שעה, כך שיהיה לך הכול בכתב. \"Within the hour\" = תוך שעה.", "\"Please don't hesitate to call me directly if anything comes up before our meeting on Thursday\" = אל תהסס להתקשר אליי ישירות אם משהו יעלה לפני הפגישה שלנו ביום חמישי. \"Don't hesitate to\" + פועל = אל תהסס ל-. \"Comes up\" = עולה, קורה.", "\"The call cleared up several points that confused us, and I appreciate your candor\" = השיחה הבהירה כמה נקודות שבלבלו אותנו, ואני מעריך את הכנות שלך. \"Cleared up\" = הבהיר, \"confused us\" = בלבל אותנו.", "\"Let's keep in touch, so we can solve any problem quickly in the future\" = בוא נשמור על קשר, כדי שנוכל לפתור כל בעיה במהירות בעתיד. \"Keep in touch\" = לשמור על קשר. \"In the future\" = בעתיד.", "\"Before we end the call, could you confirm your direct number, in case we get disconnected again?\" = לפני שנסיים את השיחה, אפשר לאשר את המספר הישיר שלך, למקרה שהשיחה תתנתק שוב? \"In case\" + הווה לאירוע אפשרי בעתיד.", "\"I'll follow up with the accounts team today, and the correction will be done by the end of the week\" = אעקוב היום אחרי צוות החשבונות, והתיקון יסתיים עד סוף השבוע. \"Will be done\" = סביל לעתיד.", "\"It was good talking to you. I'm sure we can solve everything smoothly\" = היה נעים לדבר איתך. אני בטוח שנוכל לפתור הכול בצורה חלקה. \"Talking\" אחרי \"good\" הוא ing כי מדובר בפעולה. \"Smoothly\" = בצורה חלקה.", "\"Thanks for calling. I'll make sure your question gets to the right person\" = תודה על השיחה. אדאג שהשאלה שלך תגיע לאדם הנכון. \"Gets to\" = מגיעה אל. \"Right person\" = אדם הנכון.", "\"Next time we talk, I hope we can start in a better place and move forward together\" = בפעם הבאה שנדבר, אני מקווה שנוכל להתחיל ממקום טוב יותר ולהתקדם ביחד. \"Next time\" + הווה לזמן עתידי. \"Move forward together\" = להתקדם יחד."],
  ["\"I have a flight to London on Monday morning\" = יש לי טיסה ללונדון ביום שני בבוקר. \"On Monday morning\" = ביום שני בבוקר, יום מלווה ב-\"on\" גם עם חלקי יום.", "\"Could you book a hotel near the airport, please?\" = אפשר להזמין מלון ליד שדה התעופה? \"Book\" = להזמין, מתאים למלון וטיסה. \"Near the airport\" = ליד שדה התעופה.", "\"What time does check-in close?\" = באיזו שעה נסגר הצ'ק־אין? בשאלה עם \"does\" ופועל בלשון יחיד. \"Check-in\" = הצ'ק־אין, ההרשמה במלון או בטיסה.", "\"I'd like a window seat, if possible\" = הייתי רוצה מושב ליד החלון, אם אפשר. \"Window seat\" = מושב ליד החלון, ביטוי טיסה קבוע.", "\"The meeting is at the head office in downtown Paris\" = הפגישה במשרד הראשי במרכז פריז. \"At the head office\" = במשרד הראשי. \"Downtown\" = במרכז העיר.", "\"Do I need a visa for this trip?\" = האם אני צריך ויזה לנסיעה הזאת? \"For this trip\" = לנסיעה הזאת. \"Need\" בשאלה עם \"do\".", "\"Where can I pick up a taxi?\" = איפה אפשר לקחת מונית? \"Pick up a taxi\" = לקחת מונית, ביטוי נפוץ בשדה התעופה.", "\"My flight was delayed by two hours\" = הטיסה שלי התעכבה בשעתיים. \"Delayed by\" + משך זמן. סביל כי הטיסה היא הנושא.", "\"Could you send me the itinerary for next week?\" = אפשר לשלוח לי את תוכנית הנסיעה לשבוע הבא? \"Itinerary\" = תוכנית נסיעה מפורטת, מונח נפוץ בתחום.", "\"Please keep the receipts for all of your expenses\" = נא לשמור את הקבלות על כל ההוצאות. \"Receipts\" = קבלות. \"All of your\" = כל ההוצאות שלך."],
  ["\"I'd like to change my return flight to a later date\" = הייתי רוצה לשנות את טיסת החזור שלי לתאריך מאוחר יותר. \"Return flight\" = טיסת חזור. \"A later date\" = תאריך מאוחר יותר.", "\"Is breakfast included in the room rate?\" = האם ארוחת הבוקר כלולה במחיר החדר? \"Included in\" = כלול ב-. \"Room rate\" = מחיר החדר.", "\"The conference venue is about twenty minutes from the hotel by car\" = מקום הכנס נמצא במרחק כעשרים דקות נסיעה ברכב מהמלון. \"Venue\" = מקום אירוע. \"By car\" = ברכב, מציין אמצעי תחבורה.", "\"I'm afraid the hotel has no record of our reservation\" = אני חושש שאין למלון רישום של ההזמנה שלנו. \"Has no record of\" = אין לו רישום של. \"Reservation\" = הזמנה, מונח מלונאי.", "\"We need to submit the expense report within a week of returning\" = אנחנו צריכים להגיש את דוח ההוצאות תוך שבוע מהחזרה. \"Within a week of\" = תוך שבוע מ-. \"Returning\" = ing כי אחרי \"of\" בא שם פעולה.", "\"Could you recommend a good restaurant near the office?\" = אפשר להמליץ על מסעדה טובה ליד המשרד? \"Recommend\" + שם עצם, לא \"recommend to go\".", "\"The shuttle to the airport leaves every hour from the lobby\" = ההסעה לשדה התעופה יוצאת כל שעה מהלובי. \"Leaves every hour\" = יוצאת כל שעה. \"Lobby\" = לובי, אולם הכניסה של מלון.", "\"Our client has asked us to arrive a day early for the kickoff\" = הלקוח ביקש שנגיע יום מוקדם לפגישת הפתיחה. \"Asked us to arrive\" = ביקש מאיתנו להגיע. \"A day early\" = יום מוקדם.", "\"I'll need a ride from the train station to the factory\" = אני אצטרך הסעה מתחנת הרכבת למפעל. \"Ride\" = הסעה. \"From... to\" מציין נקודת התחלה וסיום.", "\"Please confirm that the car rental includes full insurance\" = נא לאשר שהשכרת הרכב כוללת ביטוח מלא. \"Car rental\" = השכרת רכב. \"Full insurance\" = ביטוח מלא."],
  ["\"Unfortunately, my connecting flight was canceled, so I had to rebook through Frankfurt\" = לצערי, הטיסה המקשרת שלי בוטלה, ולכן נאלצתי להזמין מחדש דרך פרנקפורט. \"Connecting flight\" = טיסה מקשרת. \"Had to rebook\" = נאלצתי להזמין מחדש.", "\"Would it be possible to upgrade our rooms, since we're arriving late in the evening?\" = האם אפשר לשדרג את החדרים שלנו, מכיוון שאנחנו מגיעים מאוחר בערב? \"Upgrade\" = לשדרג. \"Since\" = מכיוון ש-, מציין סיבה.", "\"I'd like to request reimbursement for the taxi, but I'm not sure it falls under the policy\" = הייתי רוצה לבקש החזר על המונית, אבל לא בטוח שזה נכלל במדיניות. \"Reimbursement\" = החזר הוצאות, מונח משרדי. \"Falls under the policy\" = נכלל במדיניות.", "\"Our team will need to coordinate the schedule carefully, since three of us are flying from different cities\" = הצוות שלנו יצטרך לתאם את הלוח בזהירות, כי שלושה מאיתנו טסים מערים שונות. \"Coordinate\" = לתאם. \"Since\" = כי, מציין סיבה.", "\"The visa application takes longer than usual, so we should start it at least a month in advance\" = הגשת הבקשה לויזה לוקחת יותר זמן מהרגיל, לכן כדאי להתחיל אותה לפחות חודש מראש. \"At least\" = לפחות. \"In advance\" = מראש.", "תנאי מסוג 1: \"If the trip is extended by a day, the company covers the additional hotel night\". \"Extended by\" = מוארכת ביום אחד. \"Covers\" = מכסה.", "\"I'm not comfortable with the meeting being scheduled before my flight lands\" = אני לא מרגיש בנוח עם הפגישה שנקבעה לפני שהטיסה שלי נוחתת. \"Comfortable with\" + ing = נוח עם ... \"Lands\" = נוחתת.", "\"Could you check whether the hotel offers a shuttle service, since the taxi fares are quite high?\" = אפשר לבדוק אם למלון יש שירות הסעות, כי מחירי המוניות גבוהים מאוד? \"Quite high\" = די גבוה. \"Fares\" = מחירי נסיעה.", "\"We were asked to bring printed copies of the contract, so please make sure you have them in your bag\" = ביקשו מאיתנו להביא עותקים מודפסים של החוזה, לכן נא לוודא שיש לך אותם בתיק. \"Were asked to\" = ביקשו מאיתנו. \"Bring\" = להביא.", "\"The conference organizers have offered a group discount, but only if we book by Friday\" = מארגני הכנס הציעו הנחה קבוצתית, אבל רק אם נזמין עד יום שישי. \"Only if\" = רק אם. \"By Friday\" = עד יום שישי."],
  ["\"Given the time difference, I'd suggest we schedule the call for early afternoon, our time\" = בהתחשב בפער השעות, הייתי מציע שנקבע את השיחה לתחילת אחר הצהריים, לפי השעון שלנו. \"Time difference\" = פער שעות. \"Our time\" = לפי השעה שלנו.", "\"I'm not sure the policy covers business-class travel for flights under six hours\" = לא בטוח שהמדיניות כוללת נסיעה במחלקה עסקית בטיסות של פחות משש שעות. \"Under six hours\" = פחות משש שעות. \"Business-class\" = מחלקה עסקית.", "\"The delay caused us to miss the first session, so we had to catch up on the notes afterwards\" = העיכוב גרם לנו לפספס את המפגש הראשון, לכן נאלצנו להשלים את הסיכומים אחר כך. \"Caused us to\" + פועל = גרם לנו ל-. \"Catch up on\" = להשלים.", "\"Since the client's office is far from the city center, we'll need to plan the transport carefully\" = מכיוון שמשרד הלקוח רחוק ממרכז העיר, נצטרך לתכנן את התחבורה בזהירות. \"Far from\" = רחוק מ-. \"Plan the transport\" = לתכנן את התחבורה.", "\"If the trip becomes too costly, we could consider a video conference instead of an in-person visit\" = אם הנסיעה הופכת ליקרה מדי, אפשר לשקול ועידת וידאו במקום ביקור פנים־אל־פנים. \"Too costly\" = יקרה מדי. \"Instead of\" = במקום ל-.", "\"Could you provide a breakdown of the hotel charges, because one of the items seems to be double-counted?\" = אפשר לספק פירוט של חיובי המלון, כי נראה שאחד הסעיפים נספר פעמיים? \"Breakdown\" = פירוט. \"Double-counted\" = נספר פעמיים.", "\"We have to balance the cost of travel against the value of meeting the client face to face\" = אנחנו צריכים לאזן בין עלות הנסיעה לבין הערך של פגישה פנים מול פנים עם הלקוח. \"Balance X against Y\" = לאזן בין X ל-Y. \"Face to face\" = פנים אל פנים.", "\"Given the jet lag, I'd recommend we keep the first day light and schedule the important meetings for the second day\" = בהתחשב בג'ט־לג, הייתי ממליץ לשמור על היום הראשון קל ולקבוע את הפגישות החשובות ליום השני. \"Keep the first day light\" = לשמור על יום ראשון קל. \"Jet lag\" = ג'ט־לג, עייפות אחרי טיסה.", "\"I'm happy to travel, but I'd appreciate some notice so that I can arrange childcare in advance\" = אני שמח לנסוע, אבל אודה להודעה מוקדמת כדי שאוכל לסדר שמירה לילדים מראש. \"Some notice\" = הודעה מוקדמת כלשהי. \"Arrange childcare\" = לסדר שמירה לילדים.", "\"The company's travel policy requires managers to pre-approve any trip that exceeds two thousand dollars\" = מדיניות הנסיעות של החברה דורשת ממנהלים לאשר מראש כל נסיעה שעולה על אלפיים דולר. \"Requires X to\" + פועל = דורשת מ-X ל-. \"Exceeds\" = עולה על."],
  ["\"Even though the trip was tiring, the progress we made will help our partnership for years\" = למרות שהנסיעה הייתה מתישה, ההתקדמות שעשינו תעזור לשותפות שלנו לשנים. \"Even though\" = למרות ש-. \"For years\" = לשנים.", "\"If we hadn't changed the schedule, we would have missed the signing ceremony, which would have been embarrassing\" = אם לא היינו משנים את הלוח, היינו מפספסים את טקס החתימה, וזה היה מביך. תנאי מסוג 3 לדבר על מה שלא קרה בעבר. \"Would have been\" = היה נשאר.", "\"Because of the situation in the region, we need to check the safety rules before anyone else travels there\" = בגלל המצב באזור, אנחנו צריכים לבדוק את כללי הבטיחות לפני שמישהו אחר ייסע לשם. \"Before anyone else travels\" = לפני שמישהו נוסף ייסע, הווה לזמן עתידי.", "\"The client doesn't want to meet in person. This may be about the project, not about travel\" = הלקוח לא רוצה להיפגש פנים אל פנים. ייתכן שזה קשור לפרויקט, לא לנסיעה. \"May be about\" = עשוי להיות קשור ל-.", "\"Our policy has two kinds of trips: essential and optional. I think this trip is essential\" = למדיניות שלנו יש שני סוגים של נסיעות: חיוניות ואופציונליות. לדעתי הנסיעה הזאת חיונית. \"Two kinds of\" = שני סוגים של. נקודותיים לפני רשימה.", "\"If we don't agree who pays the cancellation fees, we may have an argument that spoils the visit\" = אם לא נסכים מי משלם את דמי הביטול, ייתכן שתהיה מחלוקת שתקלקל את הביקור. \"Spoils\" = מקלקל. \"We may have an argument\" = ייתכן שתהיה מחלוקת.", "\"The expense claims were rejected because the receipts did not have enough details\" = תביעות ההוצאות נדחו, כי לקבלות לא היו מספיק פרטים. \"Were rejected\" = נדחו, סביל. \"Did not have\" = לא היו להן, עבר.", "\"Should the negotiations stall, we may need to send a senior manager, but that would cost more\" = אם המשא ומתן ייתקע, ייתכן שנצטרך לשלוח מנהל בכיר, אבל זה יעלה יותר כסף. \"Should\" בתחילת משפט לתנאי פורמלי, שקול ל-\"if the negotiations stall\".", "\"The two sites are far apart, so one travel day can take half of our work time\" = שני האתרים רחוקים זה מזה, לכן יום נסיעה אחד יכול לקחת חצי מזמן העבודה שלנו. \"Far apart\" = רחוקים זה מזה. \"Half of our work time\" = חצי מזמן העבודה.", "\"Looking back, we should have checked the visa rules earlier. The delay cost us two days of meetings\" = בדיעבד, היינו צריכים לבדוק את כללי הוויזה מוקדם יותר. העיכוב עלה לנו בשני ימי פגישות. \"Looking back\" = בהסתכלות לאחור. \"Cost us\" = עלה לנו."],
  ["\"Could you tell me the check-in and check-out times, and whether early check-in is possible?\" = אפשר לספר לי את שעות הצ'ק־אין והצ'ק־אאוט, ואם צ'ק־אין מוקדם אפשרי? \"Whether\" = אם, בשאלה עקיפה. \"Check-out\" = צ'ק־אאוט.", "\"I want to confirm the return flight before I leave. Could you email me the booking number?\" = אני רוצה לאשר את טיסת החזור לפני שאצא. אפשר לשלוח לי במייל את מספר ההזמנה? \"Before I leave\" = לפני שאצא, הווה אחרי \"before\". \"Booking number\" = מספר הזמנה.", "\"Is there a limit on meal expenses during the trip?\" = יש הגבלה על הוצאות אוכל במהלך הנסיעה? \"A limit on\" = הגבלה על. \"During\" = במהלך.", "\"The client asked if we can stay two more days. I'd like your opinion before I answer\" = הלקוח שאל אם נוכל להישאר עוד יומיים. הייתי רוצה לשמוע את דעתך לפני שאענה. \"Two more days\" = עוד יומיים. \"Before I answer\" = לפני שאענה.", "\"The conference registration is done, but the badges will be ready only on the morning of the first day\" = הרישום לכנס בוצע, אבל התגים יהיו מוכנים רק בבוקר היום הראשון. \"On the morning of\" = בבוקר של. \"Badges\" = תגים, תוויות זיהוי לכנס.", "\"Let me check the flight times with the airline before we finalize the schedule\" = תן לי לבדוק את זמני הטיסה מול חברת התעופה לפני שנסגור את הלוח. \"With the airline\" = מול חברת התעופה. \"Before we finalize\" = לפני שנסגור.", "\"We can cover the cost of the first night, but anything beyond that needs approval from finance\" = נוכל לכסות את העלות של הלילה הראשון, אבל כל מה שמעבר לכך דורש אישור מהכספים. \"Beyond that\" = מעבר לזה. \"Needs approval\" = דורש אישור.", "\"Would it be easier if we shared a car from the airport, to keep costs down?\" = האם יהיה קל יותר אם נשתף מכונית משדה התעופה, כדי להוזיל עלויות? \"Keep costs down\" = להוזיל עלויות, לשמור על מחיר נמוך.", "\"I'm sorry the schedule changed at the last minute. I'll try to make sure it doesn't happen again\" = מצטער שהלוח השתנה ברגע האחרון. אנסה לוודא שזה לא יקרה שוב. \"At the last minute\" = ברגע האחרון. \"Happen again\" = לקרות שוב.", "\"Please bring your ID and the printed boarding passes to the airport\" = נא להביא את תעודת הזהות ואת כרטיסי העלייה המודפסים לשדה התעופה. \"Boarding passes\" = כרטיסי עלייה למטוס. \"Printed\" = מודפסים, תואר לפני השם."],
  ["\"Overall, the trip went well, and the relationships we built with the client team will help us\" = בסך הכול הנסיעה הייתה טובה, והקשרים שבנינו עם צוות הלקוח יעזרו לנו. \"Overall\" = בסך הכול, פותח סיכום. \"We built\" = שבנינו, בעבר כי הקשרים כבר נוצרו.", "\"I'll send the expense report by Friday, and I've attached the receipts so approval is faster\" = אשלח את דוח ההוצאות עד יום שישי, וצירפתי את הקבלות כדי שהאישור יהיה מהיר יותר. \"I've attached\" = צירפתי, Present Perfect כי הפעולה הושלמה ומשפיעה עכשיו.", "\"We learned a lot from this trip, especially about planning time zones and extra days\" = למדנו הרבה מהנסיעה הזאת, במיוחד על תכנון אזורי זמן וימים נוספים. \"Learned a lot from\" = למדנו הרבה מ-. \"Especially about\" = במיוחד לגבי.", "\"Before the next trip, let's agree on a checklist, so we don't forget anything important\" = לפני הנסיעה הבאה, בוא נסכים על רשימת בדיקה, כדי שלא נשכח שום דבר חשוב. \"Checklist\" = רשימת בדיקה. \"Don't forget\" = לא לשכוח.", "\"The client was happy with the result, and they have already invited us to a follow-up workshop\" = הלקוח היה מרוצה מהתוצאה, והם כבר הזמינו אותנו לסדנת המשך. \"Already\" עם Present Perfect = כבר. \"Follow-up workshop\" = סדנת המשך.", "\"Thanks to your careful planning, the trip went smoothly, even with the weather delays\" = בזכות התכנון הקפדני שלך, הנסיעה עברה בצורה חלקה, גם עם העיכובים מהמזג אוויר. \"Thanks to\" = בזכות. \"Even with\" = גם עם.", "\"Please update your travel details in the system, so the finance team can pay your refund\" = נא לעדכן את פרטי הנסיעה שלך במערכת, כדי שצוות הכספים יוכל לשלם לך את ההחזר. \"So X can\" = כדי ש-X יוכל. \"Pay your refund\" = לשלם לך את ההחזר.", "\"I'm happy to share my notes from the visit with anyone who couldn't come\" = אשמח לשתף את הסיכומים שלי מהביקור עם מי שלא הצליח להגיע. \"Anyone who\" = כל מי ש-. \"Couldn't come\" = לא הצליח להגיע.", "\"Thanks for handling the logistics so well. The whole team saw how much effort you put in\" = תודה שטיפלת בלוגיסטיקה כל כך טוב. כל הצוות ראה כמה מאמץ השקעת. \"Put in\" = להשקיע, בעבר. \"How much effort\" = כמה מאמץ.", "\"Next quarter we'll review the travel policy to see whether we can reduce some costs without hurting our work\" = ברבעון הבא נבחן את מדיניות הנסיעות כדי לראות אם אפשר לצמצם עלויות בלי לפגוע בעבודה. \"To see whether\" = כדי לראות אם. \"Without hurting\" = בלי לפגוע."],
  ["\"Welcome to the team! We're happy to have you on board\" = ברוכים הבאים לצוות! אנחנו שמחים שאתה מצטרף אלינו. \"On board\" = בתוך הצוות, מצטרף לארגון. \"Welcome to\" = ברוך הבא ל-.", "\"Your first week will be mostly about getting to know the company\" = השבוע הראשון שלך יהיה בעיקר על היכרות עם החברה. \"Get to know\" = להכיר. \"Mostly about\" = בעיקר על.", "\"Your manager will show you around the office this morning\" = המנהל שלך יעביר אותך במשרד הבוקר. \"Show around\" = להעביר ולהציג מקום. \"This morning\" = הבוקר.", "\"Please bring your ID and the signed forms to the HR office\" = נא להביא את תעודת הזהות והטפסים החתומים למשרד משאבי האנוש. \"HR office\" = משרד משאבי אנוש. \"The signed forms\" = הטפסים החתומים, סביל.", "\"Our working hours are from nine to five, with a short lunch break\" = שעות העבודה שלנו הן מתשע עד חמש, עם הפסקת צהריים קצרה. \"From... to\" = מ-... עד. \"With a short lunch break\" = עם הפסקת צהריים קצרה.", "\"You'll receive your login details by email this afternoon\" = תקבל את פרטי ההתחברות שלך במייל אחר הצהריים. \"Receive\" = לקבל, פועל רשמי. \"By email\" = במייל, ציון אמצעי.", "\"Feel free to ask me anything, even if it seems small\" = אתה מוזמן לשאול אותי כל דבר, גם אם הוא נראה קטן. \"Feel free to\" = אתה מוזמן ל-. \"Even if it seems small\" = גם אם זה נראה קטן.", "\"Our team meets every Thursday to share updates\" = הצוות שלנו נפגש בכל יום חמישי כדי לשתף עדכונים. \"Every Thursday\" בלי \"on\". \"To share\" מציין מטרה.", "\"You'll have a mentor for your first three months\" = יהיה לך מנטור במשך שלושת החודשים הראשונים. \"For\" מציין משך. \"Your first three months\" = שלושת החודשים הראשונים.", "\"The cafeteria is on the second floor, next to the elevator\" = הקפיטריה נמצאת בקומה השנייה, ליד המעלית. \"On the second floor\" = בקומה השנייה, \"next to\" = ליד."],
  ["\"Your probation period is three months, and we'll review your progress at the end of it\" = תקופת הניסיון שלך היא שלושה חודשים, ונבחן את ההתקדמות שלך בסופה. \"Probation period\" = תקופת ניסיון. \"At the end of it\" = בסופה.", "\"Please let me know if you need any changes to your work schedule\" = נא לעדכן אותי אם אתה צריך שינויים בלוח העבודה. \"Let me know if\" = תעדכן אותי אם. \"Any changes\" = כל שינוי, שם עצם ברבים.", "\"We offer a training budget for every employee, so you can choose a course you'd like to take\" = אנחנו מציעים תקציב הדרכה לכל עובד, כך שאתה יכול לבחור קורס שתרצה ללמוד. \"Every employee\" + שם עצם ביחיד. \"Course you'd like to take\" = קורס שתרצה ללמוד.", "\"Your annual leave accrues each month, and you can use it after the first quarter\" = חופשת השנה שלך נצברת מדי חודש, ואפשר לנצל אותה אחרי הרבעון הראשון. \"Accrue\" = להצטבר, מונח משאבי אנוש. \"Use it\" = לנצל אותה.", "\"Could you confirm your emergency contact details for our records?\" = אפשר לאשר את פרטי איש הקשר לחירום שלך לצורך התיעוד שלנו? \"For our records\" = לתיעוד שלנו, ביטוי משרדי.", "\"If you're sick, please let your manager know before nine in the morning\" = אם אתה חולה, נא להודיע למנהל שלך לפני תשע בבוקר. תנאי מסוג 1: \"if\" + הווה (\"sick\"), ו-\"please\" בתוצאה. \"Let... know\" = להודיע.", "\"Our performance reviews take place twice a year, in June and December\" = הערכות הביצועים שלנו מתקיימות פעמיים בשנה, ביוני ובדצמבר. \"Take place\" = מתקיימות. \"Twice a year\" = פעמיים בשנה.", "\"The benefits package includes a pension fund and a health insurance plan\" = חבילת ההטבות כוללת קרן פנסיה ותוכנית ביטוח בריאות. \"Benefits package\" = חבילת הטבות, מונח משאבי אנוש.", "\"Please review the employee handbook and sign to confirm you've read it\" = נא לעיין בחוברת העובד ולחתום כדי לאשר שקראת אותה. \"To confirm you've read\" = כדי לאשר שקראת, Present Perfect לקריאה שהושלמה.", "\"You can book a meeting room through the calendar system\" = אפשר להזמין חדר ישיבות דרך מערכת היומן. \"Book a room\" = להזמין חדר. \"Through\" = דרך."],
  ["\"We're looking for a candidate who can take ownership of recruitment for the entire engineering department\" = אנחנו מחפשים מועמד שיכול לקחת אחריות על הגיוס של כל מחלקת ההנדסה. \"Take ownership of\" = לקחת אחריות על. \"Candidate who can\" = מועמד ש-.", "\"The job requires strong communication skills, since you'll be working with managers at all levels\" = התפקיד דורש כישורי תקשורת חזקים, כי תעבוד עם מנהלים בכל הדרגים. \"Since\" = כי. \"At all levels\" = בכל הדרגים.", "\"We noticed a drop in engagement scores, so we're planning a survey to understand the causes\" = שמנו לב לירידה בציוני המעורבות, ולכן אנחנו מתכננים סקר כדי להבין את הסיבות. \"A drop in\" = ירידה ב-. \"To understand\" = כדי להבין, מציין מטרה.", "\"Our exit interview process helps us learn why people leave, and we use that feedback to improve\" = תהליך ראיון העזיבה שלנו עוזר לנו להבין למה אנשים עוזבים, ואנחנו משתמשים במשוב הזה כדי להשתפר. \"Exit interview\" = ראיון עזיבה. \"Helps us learn why\" = עוזר לנו להבין למה.", "\"Please make sure the job description is up to date before we publish the advertisement\" = נא לוודא שתיאור התפקיד מעודכן לפני שאנחנו מפרסמים את המודעה. \"Up to date\" = עדכני. \"Before we publish\" = לפני ש-, הווה לזמן עתידי.", "\"We're developing a new onboarding program that should make the first weeks much easier for new hires\" = אנחנו מפתחים תוכנית קליטה חדשה שאמורה להפוך את השבועות הראשונים לקלים הרבה יותר לעובדים חדשים. \"Onboarding\" = קליטת עובדים. \"Should make\" = אמורה להפוך.", "\"Employees have raised concerns about the flexibility policy, and I'd like to address them in the next town hall\" = עובדים העלו חששות לגבי מדיניות הגמישות, ואני רוצה להתייחס אליהם באסיפת העובדים הבאה. \"Address\" = להתייחס. \"Town hall\" = אסיפת עובדים כללית.", "\"The compensation review is scheduled for the end of the quarter, so please submit your requests by then\" = בדיקת השכר מתוכננת לסוף הרבעון, לכן נא להגיש את הבקשות עד אז. \"Scheduled for\" = מתוכננת ל-. \"By then\" = עד אז.", "\"Our diversity goals are reflected in the hiring process, which now includes a diverse interview panel\" = יעדי המגוון שלנו משתקפים בתהליך הגיוס, שכולל עכשיו פאנל ראיונות מגוון. \"Reflected in\" = משתקף ב-. \"Diverse panel\" = פאנל מגוון.", "\"Some employees have asked for more clarity about career paths, so we're creating a clear ladder for each department\" = כמה עובדים ביקשו יותר בהירות לגבי מסלולי קריירה, לכן אנחנו יוצרים סולם ברור לכל מחלקה. \"Asked for clarity about\" = ביקשו בהירות לגבי. \"Career paths\" = מסלולי קריירה."],
  ["\"We understand that the restructuring has been unsettling, and we're committed to keeping everyone informed at each step\" = אנחנו מבינים שהארגון מחדש היה מטלטל, ואנחנו מחויבים לעדכן את כולם בכל שלב. \"Has been unsettling\" = היה מטלטל. \"Committed to keeping\" = מחויבים לשמור. \"At each step\" = בכל שלב.", "\"While the decision was difficult, it was made to secure the long-term stability of the company\" = אף שההחלטה הייתה קשה, היא התקבלה כדי לבטח את היציבות ארוכת הטווח של החברה. \"While\" = אף ש-. \"Was made to\" = נעשתה כדי ל-.", "\"Our compensation philosophy is to pay competitively, but we also reward performance that goes beyond the job description\" = פילוסופיית השכר שלנו היא לשלם בתחרותיות, אבל אנחנו גם מתגמלים ביצועים שחורגים מתיאור התפקיד. \"Pay competitively\" = לשלם בתחרותיות. \"Goes beyond\" = חורג מ-.", "\"I'd like to discuss your development plan, because I believe you have the potential to take on a leadership role\" = הייתי רוצה לדון בתוכנית ההתפתחות שלך, כי אני מאמין שיש לך פוטנציאל לקחת תפקיד ניהולי. \"Potential to\" + פועל. \"Take on a role\" = לקחת על עצמו תפקיד.", "\"We've noticed that some teams are overloaded, and we need to rebalance the workload before burnout becomes a bigger problem\" = שמנו לב שחלק מהצוותים עמוסים מדי, ואנחנו צריכים לאזן מחדש את עומס העבודה לפני שהשחיקה תהפוך לבעיה גדולה יותר. \"Overloaded\" = עמוסים מדי. \"Burnout\" = שחיקה. \"Before\" + הווה.", "\"Could you clarify how the bonus criteria were applied this year, since several employees have asked about it?\" = אפשר להבהיר איך יושמו קריטריוני הבונוס השנה, כי כמה עובדים שאלו על זה? \"Were applied\" = יושמו, סביל. \"Asked about it\" = שאלו על זה.", "\"The new policy is designed to make expectations explicit, which should reduce misunderstandings\" = המדיניות החדשה נועדה להפוך את הציפיות לברורות, וזה אמור לצמצם אי־הבנות. \"Designed to\" = נועדה ל-. \"Explicit\" = ברור, מפורש.", "\"We take all complaints seriously, and our investigation will be handled confidentially and fairly\" = אנחנו לוקחים כל תלונה ברצינות, והבירור ייערך בסודיות ובהגינות. \"Take seriously\" = לקחת ברצינות. \"Will be handled\" = ייערך, סביל לעתיד.", "\"Even though the timing isn't ideal, we believe the promotion reflects the real impact you've had on the team\" = למרות שהתזמון לא אידיאלי, אנחנו מאמינים שהקידום משקף את ההשפעה האמיתית שהייתה לך על הצוות. \"Reflects\" = משקף. \"The impact you've had\" = ההשפעה שהייתה לך, Present Perfect.", "\"Our goal is to create an environment where people feel safe raising concerns without fear of retaliation\" = המטרה שלנו היא ליצור סביבה שבה אנשים מרגישים בטוחים להעלות חששות בלי לחשוש מנקמה. \"Feel safe + ing\" = מרגישים בטוחים לעשות. \"Without fear of\" = בלי לחשוש מ-."],
  ["\"We changed the policy after feedback from several departments. It has created some new tension\" = שינינו את המדיניות אחרי משוב ממחלקות שונות. זה יצר מתח חדש. \"Has created\" = Present Perfect כי התוצאה נמשכת עכשיו.", "\"Because of legal limits, we can't share the details of the settlement, but the matter is closed\" = בגלל מגבלות משפטיות איננו יכולים לשתף את פרטי ההסדר, אבל הנושא נסגר. \"Because of\" + שם עצם. \"Settlement\" = הסדר, פשרה משפטית.", "\"If the performance problems are not solved during the review period, we will have to look at other options\" = אם בעיות הביצועים לא ייפתרו בתקופת הבדיקה, נצטרך לבחון אפשרויות אחרות. תנאי מסוג 1 עם \"are not solved\" בהווה לתנאי.", "\"It's never easy to balance business needs and employees' wellbeing\" = אף פעם לא קל לאזן בין צרכי העסק לבין רווחת העובדים. \"Never easy\" = אף פעם לא קל. \"Rather admit than pretend\" = עדיף להודות מאשר להעמיד פנים.", "\"If we had asked the team earlier, we could have predicted many of the objections\" = אילו היינו שואלים את הצוות מוקדם יותר, יכולנו לצפות הרבה מההתנגדויות. תנאי מסוג 3 עם \"had asked\" ו-\"could have predicted\".", "\"Exit data shows that people leave mostly from a few roles. This points to management, not only to salary\" = נתוני העזיבה מראים שאנשים עוזבים בעיקר מכמה תפקידים. זה מצביע על הניהול, ולא רק על השכר. \"Points to\" = מצביע על. \"Not only... but also\" = לא רק... אלא גם.", "\"We value this employee's work, but the restructuring leaves us no choice but to cut the position\" = אנחנו מעריכים את עבודתו של העובד, אבל הארגון מחדש לא משאיר לנו ברירה אלא לבטל את התפקיד. \"Leaves us no choice but to\" = לא משאיר לנו ברירה אלא ל-.", "\"The survey results were mixed. Don't assume that every negative comment reflects all employees\" = תוצאות הסקר היו מעורבות. אל תניחו שכל הערה שלילית משקפת את כל העובדים. \"Mixed\" = מעורבות, לא חד־משמעיות. \"Every\" + שם עצם ביחיד.", "\"Our policy protects privacy, so I can't share details. But I can assure you the investigation was thorough\" = המדיניות שלנו שומרת על פרטיות, לכן איני יכול לשתף פרטים. אבל אני יכול להבטיח לך שהבירור היה יסודי. \"Assure you\" = להבטיח לך. \"Thorough\" = יסודי.", "\"Going forward, the challenge is to keep the culture we value while we grow into a bigger and more diverse company\" = מכאן והלאה, האתגר הוא לשמור על התרבות שאנחנו מעריכים, תוך כדי צמיחה לחברה גדולה ומגוונת יותר. \"Going forward\" = מכאן והלאה. \"While we grow into\" = תוך כדי צמיחה ל-."],
  ["\"Could you tell me what you hope to get from the next review, so I can prepare?\" = אפשר לספר לי מה אתה מקווה להשיג מהבדיקה הבאה, כדי שאוכל להתכונן? \"Hope to get\" = מקווה להשיג. \"So I can prepare\" = כדי שאוכל להתכונן.", "\"I want to set clear goals for next quarter. Please tell me what success would look like for you\" = אני רוצה לקבוע יעדים ברורים לרבעון הבא. נא לספר לי איך הצלחה נראית בעיניך. \"What X would look like\" = איך X היה נראה, תנאי היפותטי מנומס.", "\"Let's meet again in two weeks to see how the plan works in practice\" = בוא נתכנס שוב בעוד שבועיים כדי לראות איך התוכנית עובדת בפועל. \"In two weeks\" = בעוד שבועיים. \"In practice\" = בפועל, בשטח.", "\"Thank you for being honest in our discussion. It helps me to hear your view directly\" = תודה שהיית כנה בדיון שלנו. זה עוזר לי לשמוע את הדעה שלך ישירות. \"Hear your view\" = לשמוע את דעתך. \"Directly\" = ישירות.", "\"I know this isn't the news you hoped for, so I want to explain the reasons openly\" = אני יודע שזו לא הבשורה שקיווית לה, ולכן אני רוצה להסביר את הסיבות בגלוי. \"Hoped for\" = קיווית לה. \"Openly\" = בגלוי.", "\"Would you like some time to think about the options before we decide together?\" = האם תרצה זמן לחשוב על האפשרויות לפני שנחליט ביחד? \"Some time to think\" = זמן מה לחשוב. \"Before we decide\" = לפני שנחליט, הווה אחרי \"before\".", "\"We're looking at a flexible schedule that could help with the childcare issue you raised\" = אנחנו בודקים לוח זמנים גמיש שיכול לעזור בנושא שמירת הילדים שהעלית. \"Looking at\" = בודקים. \"Could help with\" = יכול לעזור ב-. \"You raised\" = שהעלית, משפט יחסי ללא \"that\".", "\"Before we finalize the offer, let's make sure the job title and who you report to are clear\" = לפני שנסגור את ההצעה, בוא נוודא שברורים כותרת התפקיד ומי הממונה שלך. \"Who you report to\" = אל מי אתה מדווח, שאלה עקיפה בתוך המשפט.", "\"Please look at the draft of the new policy and tell me if anything is unclear or unfair\" = נא להציץ בטיוטת המדיניות החדשה ולספר לי אם משהו לא ברור או לא הוגן. \"Look at\" = להציץ, לבחון. \"Unclear or unfair\" = לא ברור או לא הוגן.", "\"I appreciate the effort you put into the project, and I want your contribution to be recognized\" = אני מעריך את המאמץ שהשקעת בפרויקט, ואני רוצה שהתרומה שלך תוכר. \"Put into\" = השקיע ב-. \"To be recognized\" = סביל, שתוכר."],
  ["\"Thank you for your hard work this year. Your work made a real difference for the team and our clients\" = תודה על העבודה הקשה השנה. העבודה שלך עשתה הבדל אמיתי לצוות וללקוחות שלנו. \"Made a real difference\" = עשתה הבדל אמיתי.", "\"I'm glad we solved the problem together, and I'm sure the new arrangement will work for everyone\" = אני שמח שפתרנו את הבעיה ביחד, ואני בטוח שההסדר החדש יעבוד לכולם. \"Solved... together\" = פתרנו ביחד. \"Work for everyone\" = לעבוד לכולם, כלומר להתאים.", "\"Our door is always open. You are always welcome to talk to me\" = הדלת שלנו תמיד פתוחה. אתה תמיד מוזמן לדבר איתי. \"Our door is open\" = ביטוי שמביע זמינות. \"Always welcome to\" = תמיד מוזמן ל-.", "\"Please remember the mentoring program. I encourage you to use it well\" = נא לזכור את תוכנית ההנחיה. אני מעודד אותך להשתמש בה היטב. \"Encourage you to\" + פועל = לעודד אותך ל-. \"Use it well\" = להשתמש בה היטב.", "\"In the future, we want to build a clear path for growth, so talented people can see a future here\" = בעתיד, אנחנו רוצים לבנות מסלול צמיחה ברור, כדי שאנשים מוכשרים יוכלו לראות כאן עתיד. \"So talented people can see\" = כדי שאנשים מוכשרים יוכלו לראות.", "\"I'm glad to confirm your promotion. I look forward to seeing your impact in the new role\" = אני שמח לאשר את הקידום שלך. אני מצפה לראות את ההשפעה שלך בתפקיד החדש. \"Look forward to seeing\" = מצפה לראות, אחרי \"look forward to\" בא ing.", "\"The onboarding went well, and the new hires have already settled in with their teams\" = הקליטה הייתה טובה, והעובדים החדשים כבר התמקמו עם הצוותים שלהם. \"Settled in\" = התמקם, התאקלם. \"Have already settled\" = Present Perfect כי זה משפיע עכשיו.", "\"We wrote down the lessons from this year's review, so the next one will be more efficient and fair\" = כתבנו את הלקחים ממחזור ההערכה של השנה, כך שהמחזור הבא יהיה יעיל והוגן יותר. \"Wrote down\" = כתבנו, בעבר. \"Next one\" = הבא, במקום שם עצם חוזר.", "\"Thank you for being open. I hope this talk gave you a clearer picture of where you stand\" = תודה על הפתיחות. אני מקווה שהשיחה הזאת נתנה לך תמונה ברורה יותר של המצב שלך. \"Where you stand\" = מה מצבך, שאלה עקיפה כנושא.", "\"Thank you for everything you've contributed. I wish you success in the next step of your career\" = תודה על כל מה שתרמת. אני מאחל לך הצלחה בשלב הבא בקריירה שלך. \"Everything you've contributed\" = כל מה שתרמת, Present Perfect. \"I wish you success\" = אני מאחל לך הצלחה."]
];
